window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["REV"]={"book":"REV","editions":{"dan-1819":[[1,1,"Jesu Christi Aabenbaring, som Gud haver givet ham, for at vise sine Tjenere de Ting, som snart skulle skee, og han udsendte sin Engel og betegnede dem ved ham for sin Tjener Johannes,","Jesu Christi Aabenbaring, som Gud haver givet ham, for at vise sine Tjenere de Ting, som snart skulle skee, og han udsendte sin Engel og betegnede dem ved ham for sin Tjener Johannes,"],[1,2,"som haver forkyndt Guds Ord og Jesu Christi Vidnesbyrd, og hvad han haver seet.","som haver forkyndt Guds Ord og Jesu Christi Vidnesbyrd, og hvad han haver seet."],[1,3,"Salig er den, som læser, og de, som høre Prophetiens Ord og bevare det, som er skrevet i den; thi Tiden er nær.","Salig er den, som læser, og de, som høre Prophetiens Ord og bevare det, som er skrevet i den; thi Tiden er nær."],[1,4,"Johannes til de syv Menigheder i Asien: Naade være med Eder og Fred fra den, der er og der var og der kommer, og fra de syv Aander, som ere for hans Throne,","Johannes til de syv Menigheder i Asien: Naade være med Eder og Fred fra den, der er og der var og der kommer, og fra de syv Aander, som ere for hans Throne,"],[1,5,"og fra Jesus Christus, det troe Vidne, den Førstefødte af de Døde og Jordens Kongers Fyrste, som os elskede og aftvættede os fra vore Synder med sit Blod,","og fra Jesus Christus, det troe Vidne, den Førstefødte af de Døde og Jordens Kongers Fyrste, som os elskede og aftvættede os fra vore Synder med sit Blod,"],[1,6,"og haver gjort os til Konger og Præster for sin Gud og Fader: ham være Ære og Kraft i al Evighed! Amen.","og haver gjort os til Konger og Præster for sin Gud og Fader: ham være Ære og Kraft i al Evighed! Amen."],[1,7,"See, han kommer med Skyerne, og hvert Øie skal see ham, ogsaa de, som ham igjennemstunge, og alle Jordens Slægter skulle hyle for ham. Ja, Amen!","See, han kommer med Skyerne, og hvert Øie skal see ham, ogsaa de, som ham igjennemstunge, og alle Jordens Slægter skulle hyle for ham. Ja, Amen!"],[1,8,"Jeg er Alpha og Omega , Begyndelsen og Enden, siger Herren, den, som er og som var og som kommer, den Almægtige.","Jeg er Alpha og Omega , Begyndelsen og Enden, siger Herren, den, som er og som var og som kommer, den Almægtige."],[1,9,"Jeg, Johannes, som og er Eders Broder og meddeelagtig i Trængslen og i Riget og i Jesu Christi Taalmodighed, var paa den Ø, som kaldes Patmos, for Guds Ords og for Jesu Christi Vidnesbyrds Skyld.","Jeg, Johannes, som og er Eders Broder og meddeelagtig i Trængslen og i Riget og i Jesu Christi Taalmodighed, var paa den Ø, som kaldes Patmos, for Guds Ords og for Jesu Christi Vidnesbyrds Skyld."],[1,10,"Jeg henrykkes i Aanden paa Herrens Dag, og jeg hørte bag mig en høi Røst som en Basunes, der sagde:","Jeg henrykkes i Aanden paa Herrens Dag, og jeg hørte bag mig en høi Røst som en Basunes, der sagde:"],[1,11,"Jeg er Alpha og Omega, den Første og den Sidste; og hvad du seer, skriv det i en Bog, og send det til Menighederne i Asien, til Ephesus og til Smyrna og til Pergamus og til Thyatira og til Sardes og til Philadelphia og til Laodicea.","Jeg er Alpha og Omega, den Første og den Sidste; og hvad du seer, skriv det i en Bog, og send det til Menighederne i Asien, til Ephesus og til Smyrna og til Pergamus og til Thyatira og til Sardes og til Philadelphia og til Laodicea."],[1,12,"Og jeg vendte mig for at see Røsten, som talede med mig; og da jeg vendte mig, saae jeg syv Guldlysestager,","Og jeg vendte mig for at see Røsten, som talede med mig; og da jeg vendte mig, saae jeg syv Guldlysestager,"],[1,13,"og imellem de syv Lysestager En, lig et Menneskes Søn, iført en sid Kjortel og opbunden under Brystet med et Guldbelte.","og imellem de syv Lysestager En, lig et Menneskes Søn, iført en sid Kjortel og opbunden under Brystet med et Guldbelte."],[1,14,"Men hans Hoved og Haar var hvidt som hvid Uld, som Snee; og hans Øine som Ildslue;","Men hans Hoved og Haar var hvidt som hvid Uld, som Snee; og hans Øine som Ildslue;"],[1,15,"og hans Fødder lige det skinnende Kobber, som glødede i Ovnen; og hans Røst som mange Vandes Lyd;","og hans Fødder lige det skinnende Kobber, som glødede i Ovnen; og hans Røst som mange Vandes Lyd;"],[1,16,"og han havde syv Stjerner i sin høire Haand; og et tveegget skarpt Sværd udgik af hans Mund; og hans Ansigt var som Solen, naar den skinner i sin Kraft.","og han havde syv Stjerner i sin høire Haand; og et tveegget skarpt Sværd udgik af hans Mund; og hans Ansigt var som Solen, naar den skinner i sin Kraft."],[1,17,"Og der jeg saae ham, faldt jeg ned for hans Fødder som en Død; og han lagde sin høire Haand paa mig og sagde til mig:","Og der jeg saae ham, faldt jeg ned for hans Fødder som en Død; og han lagde sin høire Haand paa mig og sagde til mig:"],[1,18,"frygt ikke! Jeg er den Første og den Sidste og de Levende; og jeg var død, og see, jeg er levende i al Evighed! Amen. Og jeg haver Helvedes og Dødens Nøgler.","frygt ikke! Jeg er den Første og den Sidste og de Levende; og jeg var død, og see, jeg er levende i al Evighed! Amen. Og jeg haver Helvedes og Dødens Nøgler."],[1,19,"Skriv, hvad du saae, baade det som er, og det som skal skee herefter;","Skriv, hvad du saae, baade det som er, og det som skal skee herefter;"],[1,20,"de syv Stjerners Hemmelighed, hvilke du haver seet i min høire Haand, og de syv Guldlysestager. De syv Stjerner ere de syv Menigheders Engle, og de syv Lysestager, som du saae, ere de syv Menigheder.","de syv Stjerners Hemmelighed, hvilke du haver seet i min høire Haand, og de syv Guldlysestager. De syv Stjerner ere de syv Menigheders Engle, og de syv Lysestager, som du saae, ere de syv Menigheder."],[2,1,"Skriv til Menighedens Engel i Ephesus: dette siger den, som holder de syv Stjerner i sin høire Haand, den som vandrer imellem de syv Guldlysestager:","Skriv til Menighedens Engel i Ephesus: dette siger den, som holder de syv Stjerner i sin høire Haand, den som vandrer imellem de syv Guldlysestager:"],[2,2,"jeg veed dine Gjerninger og dit Arbeide og din Taalmodighed, og at du ikke kan fordrage det Onde; og du prøvede dem, som sige sig at være Apostler og ere det ikke, og haver befundet dem at være Løgnere;","jeg veed dine Gjerninger og dit Arbeide og din Taalmodighed, og at du ikke kan fordrage det Onde; og du prøvede dem, som sige sig at være Apostler og ere det ikke, og haver befundet dem at være Løgnere;"],[2,3,"og du haver udstaaet og haver Taalmodighed; og du haver arbeidet for mit Navns Skyld og er ikke bleven træt.","og du haver udstaaet og haver Taalmodighed; og du haver arbeidet for mit Navns Skyld og er ikke bleven træt."],[2,4,"Men jeg haver dette imod dig, at du haver forladt din første Kjærlighed.","Men jeg haver dette imod dig, at du haver forladt din første Kjærlighed."],[2,5,"Kom derfor ihu, hvorfra du er falden, og vend om og gjør de forrige Gjerninger; men hvis ikke, da kommer jeg snart over dig og vil flytte din Lysestage fra dens Sted, hvis du ikke omvender dig.","Kom derfor ihu, hvorfra du er falden, og vend om og gjør de forrige Gjerninger; men hvis ikke, da kommer jeg snart over dig og vil flytte din Lysestage fra dens Sted, hvis du ikke omvender dig."],[2,6,"Dog, det haver du, at du hader de Nikolaiters Gjerninger, hvilke og jeg hader.","Dog, det haver du, at du hader de Nikolaiters Gjerninger, hvilke og jeg hader."],[2,7,"Hvo som haver Øren, høre, hvad Aanden siger til Menighederne: den, som seirer, ham vil jeg give at æde af Livsens Træ, som er midt i Guds Paradiis.","Hvo som haver Øren, høre, hvad Aanden siger til Menighederne: den, som seirer, ham vil jeg give at æde af Livsens Træ, som er midt i Guds Paradiis."],[2,8,"Og skriv i Menighedens Engel i Smyrna: dette siger den Første og den Sidste, han, som var død og er bleven levende:","Og skriv i Menighedens Engel i Smyrna: dette siger den Første og den Sidste, han, som var død og er bleven levende:"],[2,9,"jeg veed dine Gjerninger og din Trængsel og din Fattigdom, (dog du er rig), og Bespottelsen af dem, som sige sig selv at være Jøder, og ere det ikke, men ere Satans Synagoge.","jeg veed dine Gjerninger og din Trængsel og din Fattigdom, (dog du er rig), og Bespottelsen af dem, som sige sig selv at være Jøder, og ere det ikke, men ere Satans Synagoge."],[2,10,"Frygt ikke for det, du skal lide! See, Djævelen skal kaste Nogle af Eder i Fængsel, paa det I skulle fristes, og I skulle have Trængsel i ti Dage. Vær tro indtil Døden, saa vil jeg give dig Livsens Krone.","Frygt ikke for det, du skal lide! See, Djævelen skal kaste Nogle af Eder i Fængsel, paa det I skulle fristes, og I skulle have Trængsel i ti Dage. Vær tro indtil Døden, saa vil jeg give dig Livsens Krone."],[2,11,"Hvo som haver Øren, høre, hvad Aanden siger til Menighederne: den, som seirer, skal ingenlunde skades af den anden Død.","Hvo som haver Øren, høre, hvad Aanden siger til Menighederne: den, som seirer, skal ingenlunde skades af den anden Død."],[2,12,"Og skriv til Menighedens Engel i Pergamus: dette siger den, som haver det tveeggede skarpe Sværd:","Og skriv til Menighedens Engel i Pergamus: dette siger den, som haver det tveeggede skarpe Sværd:"],[2,13,"jeg veed dine Gjerninger, og hvor du boer, der hvor Satans Throne er; og du holder ved mit Navn og fornegtede ikke min Tro, endog i de Dage, i hvilke Antipas var, mit tro Vidne, som blev ihjelslagen hos Eder, der hvor Satan boer.","jeg veed dine Gjerninger, og hvor du boer, der hvor Satans Throne er; og du holder ved mit Navn og fornegtede ikke min Tro, endog i de Dage, i hvilke Antipas var, mit tro Vidne, som blev ihjelslagen hos Eder, der hvor Satan boer."],[2,14,"Men jeg haver noget Lidet imod dig, at du haver hos dig Nogle, som holde ved Bileams Lære, der lærte Balak at kaste Forargelse for Israels Børn, saa de aade Afgudsoffer og bedreve Hoer.","Men jeg haver noget Lidet imod dig, at du haver hos dig Nogle, som holde ved Bileams Lære, der lærte Balak at kaste Forargelse for Israels Børn, saa de aade Afgudsoffer og bedreve Hoer."],[2,15,"Saaledes haver du og dem, som holde ved de Nikolaiters Lærdom; hvilket jeg hader.","Saaledes haver du og dem, som holde ved de Nikolaiters Lærdom; hvilket jeg hader."],[2,16,"Vend om! Men hvis ikke, kommer jeg snart over dig og vil stride imod dem med min Munds Sværd.","Vend om! Men hvis ikke, kommer jeg snart over dig og vil stride imod dem med min Munds Sværd."],[2,17,"Hvo som haver Øren, høre, hvad Aanden siger til Menighederne: den, som seirer, ham vil jeg give at æde af den skjulte Manna, og jeg vil give ham en hvid Steen, og et nyt Navn skrevet paa Stenen, hvilket Ingen kjender, uden den, som annammer det.","Hvo som haver Øren, høre, hvad Aanden siger til Menighederne: den, som seirer, ham vil jeg give at æde af den skjulte Manna, og jeg vil give ham en hvid Steen, og et nyt Navn skrevet paa Stenen, hvilket Ingen kjender, uden den, som annammer det."],[2,18,"Og skriv til Menighedens Engel i Thyatira: dette siger Guds Søn, der haver Øine som Ildslue, og hvis Fødder ere som skinnende Kobber:","Og skriv til Menighedens Engel i Thyatira: dette siger Guds Søn, der haver Øine som Ildslue, og hvis Fødder ere som skinnende Kobber:"],[2,19,"jeg veed dine Gjerninger og din Kjærlighed og Tjeneste og Tro og Taalmodighed og dine Gjerninger, ja de sidste flere end de første.","jeg veed dine Gjerninger og din Kjærlighed og Tjeneste og Tro og Taalmodighed og dine Gjerninger, ja de sidste flere end de første."],[2,20,"Men jeg haver noget Lidet imod dig, at du tilsteder den Kvinde Jesabel, som siger sig selv at være en Prophetinde, at lære og forføre mine Tjenere til at bedrive Hoer og at æde Afgudsoffer.","Men jeg haver noget Lidet imod dig, at du tilsteder den Kvinde Jesabel, som siger sig selv at være en Prophetinde, at lære og forføre mine Tjenere til at bedrive Hoer og at æde Afgudsoffer."],[2,21,"Og jeg haver givet hende Tid, at hun skulle omvende sig fra hendes Horeri, og hun haver ikke omvendt sig.","Og jeg haver givet hende Tid, at hun skulle omvende sig fra hendes Horeri, og hun haver ikke omvendt sig."],[2,22,"See, jeg kaster hende paa Leiet og hendes Bolere i stor Trængsel, dersom de ikke omvende sig fra deres Gjerninger.","See, jeg kaster hende paa Leiet og hendes Bolere i stor Trængsel, dersom de ikke omvende sig fra deres Gjerninger."],[2,23,"Og ved Død vil jeg bortrykke hendes Børn, og alle Menigheder skulle kjende, at jeg er den, som ransager Nyrer og Hjerter; og jeg vil give Eder, hver efter Eders Gjerninger.","Og ved Død vil jeg bortrykke hendes Børn, og alle Menigheder skulle kjende, at jeg er den, som ransager Nyrer og Hjerter; og jeg vil give Eder, hver efter Eders Gjerninger."],[2,24,"Men jeg siger Eder og de Øvrige, som ere i Thyatira, saa mange som ikke annamme denne Lære og ikke kjende Satans Dybheder, som de kalde det: jeg vil ikke lægge en anden Byrde paa Eder.","Men jeg siger Eder og de Øvrige, som ere i Thyatira, saa mange som ikke annamme denne Lære og ikke kjende Satans Dybheder, som de kalde det: jeg vil ikke lægge en anden Byrde paa Eder."],[2,25,"Kun det I have, holder det fast, indtil jeg kommer.","Kun det I have, holder det fast, indtil jeg kommer."],[2,26,"Og den, som seirer, og som varer paa mine Gjerninger indtil Enden, ham vil jeg give Magt over Hedningerne;","Og den, som seirer, og som varer paa mine Gjerninger indtil Enden, ham vil jeg give Magt over Hedningerne;"],[2,27,"og han skal regjere dem med et Jernspiir, ligesom Leerkar skulle de sønderknuses, som og jeg annammede det af min Fader;","og han skal regjere dem med et Jernspiir, ligesom Leerkar skulle de sønderknuses, som og jeg annammede det af min Fader;"],[2,28,"og jeg vil give ham Morgenstjernen.","og jeg vil give ham Morgenstjernen."],[2,29,"Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!","Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!"],[3,1,"Og skriv til Menighedens Engel i Sardes: dette siger den, som haver de syv Guds Aander og de syv Stjerner: jeg veed dine Gjerninger, at du haver Navn som levende, enddog du er død.","Og skriv til Menighedens Engel i Sardes: dette siger den, som haver de syv Guds Aander og de syv Stjerner: jeg veed dine Gjerninger, at du haver Navn som levende, enddog du er død."],[3,2,"Bliv vaagen og styrk det Øvrige, som vil døe; thi jeg haver ikke fundet dine Gjerninger fuldkommede for Gud.","Bliv vaagen og styrk det Øvrige, som vil døe; thi jeg haver ikke fundet dine Gjerninger fuldkommede for Gud."],[3,3,"Kom derfor ihu, hvorledes du haver annammet og hørt, og bevar det og vend om. Dersom du da ikke vil vaage, skal jeg komme over dig som en Tyv, og du skal ikke vide, paa hvilken Stund jeg kommer over dig.","Kom derfor ihu, hvorledes du haver annammet og hørt, og bevar det og vend om. Dersom du da ikke vil vaage, skal jeg komme over dig som en Tyv, og du skal ikke vide, paa hvilken Stund jeg kommer over dig."],[3,4,"Dog haver du Nogle faa Personer i Sardes, som ikke have besmittet deres Klæder; de skulle vandre med mig i hvide Klæder, thi de ere værdige dertil.","Dog haver du Nogle faa Personer i Sardes, som ikke have besmittet deres Klæder; de skulle vandre med mig i hvide Klæder, thi de ere værdige dertil."],[3,5,"Den, som seirer, han skal iføres hvide Klæder, og jeg vil ikke udslettet hans Navn af Livsens Bog, og jeg vil bekjende hans Navn for min Fader og for hans Engle.","Den, som seirer, han skal iføres hvide Klæder, og jeg vil ikke udslettet hans Navn af Livsens Bog, og jeg vil bekjende hans Navn for min Fader og for hans Engle."],[3,6,"Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!","Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!"],[3,7,"Og skriv til Menighedens Engel i Philadelphia: dette siger den Hellige, den Sanddrue, den som haver Davids Nøgle, som lukker op, og Ingen lukker til, og lukker til, og Ingen lukker op:","Og skriv til Menighedens Engel i Philadelphia: dette siger den Hellige, den Sanddrue, den som haver Davids Nøgle, som lukker op, og Ingen lukker til, og lukker til, og Ingen lukker op:"],[3,8,"jeg veed dine Gjerninger. See, jeg haver stillet for dig en aabnet Dør, og Ingen kan lukke den; thi du haver en liden Kraft, dog haver du bevaret mit Ord og ikke fornegtet mit Navn.","jeg veed dine Gjerninger. See, jeg haver stillet for dig en aabnet Dør, og Ingen kan lukke den; thi du haver en liden Kraft, dog haver du bevaret mit Ord og ikke fornegtet mit Navn."],[3,9,"See, jeg lader komme Nogle af Satans Synagoge, som sige sig selv at være Jøder og ere det ikke, men lyve. See, jeg vil gjøre, at de skulle komme og tilbede for dine Fødder, og kjende, at jeg haver elsket dig.","See, jeg lader komme Nogle af Satans Synagoge, som sige sig selv at være Jøder og ere det ikke, men lyve. See, jeg vil gjøre, at de skulle komme og tilbede for dine Fødder, og kjende, at jeg haver elsket dig."],[3,10,"Efterdi du haver bevaret mit Ord om Taalmodighed, vil jeg og bevare dig fra Fristelsens Stund, som skal komme over ganske Jorderige, at friste dem, som boe paa Jorden.","Efterdi du haver bevaret mit Ord om Taalmodighed, vil jeg og bevare dig fra Fristelsens Stund, som skal komme over ganske Jorderige, at friste dem, som boe paa Jorden."],[3,11,"See, jeg kommer snart! Hold fast ved det, du haver, at Ingen skal tage din Krone.","See, jeg kommer snart! Hold fast ved det, du haver, at Ingen skal tage din Krone."],[3,12,"Den, som seirer, ham vil jeg gjøre til en Piller i min Guds Tempel, og han skal ikke ydermere gaae ud derfra; og jeg vil skrive min Guds Navn paa ham og min Guds Stad, det nye Jerusalems Navn, hvilken kommer ned af Himmelen fra min Gud, og mit det nye Navn.","Den, som seirer, ham vil jeg gjøre til en Piller i min Guds Tempel, og han skal ikke ydermere gaae ud derfra; og jeg vil skrive min Guds Navn paa ham og min Guds Stad, det nye Jerusalems Navn, hvilken kommer ned af Himmelen fra min Gud, og mit det nye Navn."],[3,13,"Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!","Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!"],[3,14,"Og skriv til Menighedens Engel i Laodicea: dette siger den, som er Amen, det trofaste og sanddrue Vidne, Guds Skabnings Begyndelse!","Og skriv til Menighedens Engel i Laodicea: dette siger den, som er Amen, det trofaste og sanddrue Vidne, Guds Skabnings Begyndelse!"],[3,15,"jeg veed dine Gjerninger, at du er hverken kold eller varm: gid du var kold eller varm!","jeg veed dine Gjerninger, at du er hverken kold eller varm: gid du var kold eller varm!"],[3,16,"Derfor, efterdi du er lunken, og hverken kold eller varm, vil jeg udspye dig af min Mund;","Derfor, efterdi du er lunken, og hverken kold eller varm, vil jeg udspye dig af min Mund;"],[3,17,"fordi du siger: jeg er rig og haver Overflod og fattes Intet; og du veed ikke, at du er elendig og jammerlig og fattig og blind og nøgen.","fordi du siger: jeg er rig og haver Overflod og fattes Intet; og du veed ikke, at du er elendig og jammerlig og fattig og blind og nøgen."],[3,18,"Jeg raader dig, at du kjøber af mig Guld, luttret i Ilden, at du kan vorde rig; og hvide Klæder, at du kan bedække dig, og din Nøgenheds Skam ikke skal blottes, og salv dine Øine med Øiensalve, at du kan see.","Jeg raader dig, at du kjøber af mig Guld, luttret i Ilden, at du kan vorde rig; og hvide Klæder, at du kan bedække dig, og din Nøgenheds Skam ikke skal blottes, og salv dine Øine med Øiensalve, at du kan see."],[3,19,"Hvilkesomhelst jeg elsker, dem straffer og tugter jeg; vær derfor nidkjær og omvend dig.","Hvilkesomhelst jeg elsker, dem straffer og tugter jeg; vær derfor nidkjær og omvend dig."],[3,20,"See, jeg staaer for Døren og banker; dersom Nogen hører min Røst og oplader Døren, til ham vil jeg gaae ind og holde Nadvere med ham, og han med mig.","See, jeg staaer for Døren og banker; dersom Nogen hører min Røst og oplader Døren, til ham vil jeg gaae ind og holde Nadvere med ham, og han med mig."],[3,21,"Den, som seirer, ham vil jeg give at sidde med mig paa min Throne, ligesom og jeg haver seiret og sidder hos min Fader paa hans Throne.","Den, som seirer, ham vil jeg give at sidde med mig paa min Throne, ligesom og jeg haver seiret og sidder hos min Fader paa hans Throne."],[3,22,"Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!","Hvo som haver Øren, høre, hvad Aanden siger til Menighederne!"],[4,1,"Derefter saae jeg, og see, der var en Dør opladt i Himmelen, og den første Røst, som jeg havde hørt som en Basunes, der talede med mig, sagde: stig hid op, og jeg vil vise dig, hvad herefter skal skee.","Derefter saae jeg, og see, der var en Dør opladt i Himmelen, og den første Røst, som jeg havde hørt som en Basunes, der talede med mig, sagde: stig hid op, og jeg vil vise dig, hvad herefter skal skee."],[4,2,"Og strax henryktes jeg; og see, en Throne var sat i Himmelen, og En sad paa Thronen.","Og strax henryktes jeg; og see, en Throne var sat i Himmelen, og En sad paa Thronen."],[4,3,"Og den Siddende var at see til lig Jaspissteen og Sarder, og der var en Regnbue trindt omkring Thronen, at see til lig Smaragden.","Og den Siddende var at see til lig Jaspissteen og Sarder, og der var en Regnbue trindt omkring Thronen, at see til lig Smaragden."],[4,4,"Og Trindt omkring Thronen vare fire og tyve Throner; og paa de Throner saae jeg fire og tyve Ældste sidde, iførte hvide Klæder, og de havde Guldkroner paa deres Hoveder.","Og Trindt omkring Thronen vare fire og tyve Throner; og paa de Throner saae jeg fire og tyve Ældste sidde, iførte hvide Klæder, og de havde Guldkroner paa deres Hoveder."],[4,5,"Og af Thronen udgik Lyn og Tordener og Røster, og syv antændte Fakler brændte for Thronen, hvilke ere de syv Guds Aander.","Og af Thronen udgik Lyn og Tordener og Røster, og syv antændte Fakler brændte for Thronen, hvilke ere de syv Guds Aander."],[4,6,"Og for Thronen var et Glarhav, ligt Krystal, og i Thronens Midte og omkring Thronen vare fire Dyr, fulde af Øine fortil og bagtil.","Og for Thronen var et Glarhav, ligt Krystal, og i Thronens Midte og omkring Thronen vare fire Dyr, fulde af Øine fortil og bagtil."],[4,7,"Og det første Dyr var ligt en Løve; og det andet Dyr var ligt en Oxe; og det tredie Dyr havde Ansigt som et Menneske; og det fjerde Dyr var ligt en flyvende Ørn.","Og det første Dyr var ligt en Løve; og det andet Dyr var ligt en Oxe; og det tredie Dyr havde Ansigt som et Menneske; og det fjerde Dyr var ligt en flyvende Ørn."],[4,8,"Og de fire Dyr havde, hvert især, sex Vinger rundt om og indentil fulde af Øine; og de havde ingen Hvile Dag eller Nat, sigende: hellig, hellig, hellig er Herren, Gud, den Almægtige, den, som var og som er og som kommer!","Og de fire Dyr havde, hvert især, sex Vinger rundt om og indentil fulde af Øine; og de havde ingen Hvile Dag eller Nat, sigende: hellig, hellig, hellig er Herren, Gud, den Almægtige, den, som var og som er og som kommer!"],[4,9,"Og naar Dyrene give Ære og Priis og Tak til ham, som sidder paa Thronen, ham, som lever i al Evighed,","Og naar Dyrene give Ære og Priis og Tak til ham, som sidder paa Thronen, ham, som lever i al Evighed,"],[4,10,"da falde de fire og tyve Ældste ned for ham, som sidder paa Thronen, og tilbede ham, som lever i al Evighed, og lægge deres Kroner ned for Thronen, sigende:","da falde de fire og tyve Ældste ned for ham, som sidder paa Thronen, og tilbede ham, som lever i al Evighed, og lægge deres Kroner ned for Thronen, sigende:"],[4,11,"værdig er du, Herre! at annamme Ære og Priis og Kraft; thi du haver skabt alle Ting, og ved din Villie ere de, og bleve de skabte.","værdig er du, Herre! at annamme Ære og Priis og Kraft; thi du haver skabt alle Ting, og ved din Villie ere de, og bleve de skabte."],[5,1,"Og jeg saae i hans høire Haand, som sad paa Thronen, en Bog, beskreven inden og uden, og beseglet med syv Segl.","Og jeg saae i hans høire Haand, som sad paa Thronen, en Bog, beskreven inden og uden, og beseglet med syv Segl."],[5,2,"Og jeg saae en vældig Engel, som udraabte med høi Røst: hvo er værdig at oplade Bogen og bryde dens Segl?","Og jeg saae en vældig Engel, som udraabte med høi Røst: hvo er værdig at oplade Bogen og bryde dens Segl?"],[5,3,"Og Ingen i Himmelen, ei heller paa Jorden, ei heller under Jorden, formaaede at oplade Bogen, eller at see deri.","Og Ingen i Himmelen, ei heller paa Jorden, ei heller under Jorden, formaaede at oplade Bogen, eller at see deri."],[5,4,"Og jeg græd saare, fordi Ingen fandtes værdig at oplade og læse Bogen, ei heller at see deri.","Og jeg græd saare, fordi Ingen fandtes værdig at oplade og læse Bogen, ei heller at see deri."],[5,5,"Og een af de Ældste sagde til mig: græd ikke; see, Løven, som er af Judas Stamme, af Davids Rod, haver vundet Seier til at oplade Bogen og bryde dens Segl.","Og een af de Ældste sagde til mig: græd ikke; see, Løven, som er af Judas Stamme, af Davids Rod, haver vundet Seier til at oplade Bogen og bryde dens Segl."],[5,6,"Og jeg saae, og see, midt imellem Thronen og de fire Dyr, og midt imellem de Ældste stod et Lam, ligesom slagtet, som havde syv Horn og syv Øine, hvilke ere de syv Guds Aander, som ere udsendte til den ganske Jord.","Og jeg saae, og see, midt imellem Thronen og de fire Dyr, og midt imellem de Ældste stod et Lam, ligesom slagtet, som havde syv Horn og syv Øine, hvilke ere de syv Guds Aander, som ere udsendte til den ganske Jord."],[5,7,"Og det kom og tog Bogen af hans høire Haand, som sad paa Thronen.","Og det kom og tog Bogen af hans høire Haand, som sad paa Thronen."],[5,8,"Og der det havde taget Bogen, faldt de fire Dyr og de fire og tyve Ældste ned for Lammet, havende hver sin Harpe og Guldskaaler fyldte med Røgelse, som er de Helliges Bønner.","Og der det havde taget Bogen, faldt de fire Dyr og de fire og tyve Ældste ned for Lammet, havende hver sin Harpe og Guldskaaler fyldte med Røgelse, som er de Helliges Bønner."],[5,9,"Og de sang en ny Sang, sigende: du er værdig at tage Bogen og oplade dens Segl, fordi du er slagtet, og med dit Blod haver kjøbt os til Gud af alle Stammer og Tungemaal og Folk og Slægter.","Og de sang en ny Sang, sigende: du er værdig at tage Bogen og oplade dens Segl, fordi du er slagtet, og med dit Blod haver kjøbt os til Gud af alle Stammer og Tungemaal og Folk og Slægter."],[5,10,"Og du haver gjort os til Konger og Præster for vor Gud, og vi skulle regjere over Jorden.","Og du haver gjort os til Konger og Præster for vor Gud, og vi skulle regjere over Jorden."],[5,11,"Og jeg saae og hørte mange Engles Røst omkring Thronen, og Dyrenes og de Ældste, og deres Tal var titusinde Gange Titusinde, og tusinde Gange Tusinde.","Og jeg saae og hørte mange Engles Røst omkring Thronen, og Dyrenes og de Ældste, og deres Tal var titusinde Gange Titusinde, og tusinde Gange Tusinde."],[5,12,"De sagde med høi Røst: Lammet, som er slagtet, er værdigt at annamme Magt og Rigdom og Viisdom og Styrke, og Priis og Ære og Velsignelse!","De sagde med høi Røst: Lammet, som er slagtet, er værdigt at annamme Magt og Rigdom og Viisdom og Styrke, og Priis og Ære og Velsignelse!"],[5,13,"Og hver Skabning, som er i Himmelen og paa Jorden og under Jorden, og hvad der er i Havet, og Alt, hvad der er i dem, hørte jeg sige: ham, som sidder paa Thronen, og Lammet, være Velsignelse og Priis og Ære og Kraft i al Evighed!","Og hver Skabning, som er i Himmelen og paa Jorden og under Jorden, og hvad der er i Havet, og Alt, hvad der er i dem, hørte jeg sige: ham, som sidder paa Thronen, og Lammet, være Velsignelse og Priis og Ære og Kraft i al Evighed!"],[5,14,"Og de fire Dyr sagde: Amen! Og de fire og tyve Ældste faldt ned og tilbade ham, som lever i al Evighed!","Og de fire Dyr sagde: Amen! Og de fire og tyve Ældste faldt ned og tilbade ham, som lever i al Evighed!"],[6,1,"Og jeg saae, at Lammet oplod eet af de syv Segl, og jeg hørte eet af de fire Dyr sige, som en Tordens Røst: kom og see!","Og jeg saae, at Lammet oplod eet af de syv Segl, og jeg hørte eet af de fire Dyr sige, som en Tordens Røst: kom og see!"],[6,2,"Og jeg saae, og see, en hvid Hest, og den, som sad paa den, havde en Bue; og ham blev given en Krone, og han drog ud seirende og til Seier.","Og jeg saae, og see, en hvid Hest, og den, som sad paa den, havde en Bue; og ham blev given en Krone, og han drog ud seirende og til Seier."],[6,3,"Og der det oplod det andet Segl, hørte jeg det andet Dyr sige: kom og see!","Og der det oplod det andet Segl, hørte jeg det andet Dyr sige: kom og see!"],[6,4,"Og der fremgik en anden Hest, som var rød, og ham, som sad derpaa, blev givet at tage Fred fra Jorden, og at de skulde flygte hverandre; og ham blev givet et stort Sværd.","Og der fremgik en anden Hest, som var rød, og ham, som sad derpaa, blev givet at tage Fred fra Jorden, og at de skulde flygte hverandre; og ham blev givet et stort Sværd."],[6,5,"Og der det oplod det tredie Segl, hørte jeg det tredie Dyr sige: kom og see! Og jeg saae, og see, en sort Hest, og den, der sad paa den, havde en Vægt i sin Haand.","Og der det oplod det tredie Segl, hørte jeg det tredie Dyr sige: kom og see! Og jeg saae, og see, en sort Hest, og den, der sad paa den, havde en Vægt i sin Haand."],[6,6,"Og jeg hørte en Røst midt iblandt de fire Dyr, som sagde: en Maade Hvede for en Penge og Tre Maader Byg for en Penge; og du skal ikke gjøre Olien og Vinen Skade.","Og jeg hørte en Røst midt iblandt de fire Dyr, som sagde: en Maade Hvede for en Penge og Tre Maader Byg for en Penge; og du skal ikke gjøre Olien og Vinen Skade."],[6,7,"Og der det oplod det fjerde Segl, hørte jeg det fjerde Dyrs Røst sige: kom og see!","Og der det oplod det fjerde Segl, hørte jeg det fjerde Dyrs Røst sige: kom og see!"],[6,8,"Og jeg saae, og see, en blegguul Hest, og den, som sad derpaa, hans Navn var Døden, og Helvede fulgte med ham; og ham blev given Magt over den fjerde Deel af Jorden, at ihjelslaae med Sværd og med Hunger og med Pest og ved Jordens vilde Dyr.","Og jeg saae, og see, en blegguul Hest, og den, som sad derpaa, hans Navn var Døden, og Helvede fulgte med ham; og ham blev given Magt over den fjerde Deel af Jorden, at ihjelslaae med Sværd og med Hunger og med Pest og ved Jordens vilde Dyr."],[6,9,"Og der det oplod det femte Segl, saae jeg under Alteret deres Sjæle, som vare myrdede for Guds Ords Skyld og for det Vidnesbyrds Skyld, som de bare.","Og der det oplod det femte Segl, saae jeg under Alteret deres Sjæle, som vare myrdede for Guds Ords Skyld og for det Vidnesbyrds Skyld, som de bare."],[6,10,"Og de raabte med høi Røst og sagde: Herre, du Hellige og Sanddrue! hvor længe tøver du at dømme og hevne vort Blod paa dem, som boe paa Jorden?","Og de raabte med høi Røst og sagde: Herre, du Hellige og Sanddrue! hvor længe tøver du at dømme og hevne vort Blod paa dem, som boe paa Jorden?"],[6,11,"Og dem bleve givne, hver især, lange hvide Kjortler, og der blev sagt til dem, at de skulde hvile sig endnu en liden Tid, indtil Tallet af deres Medtjenere og deres Brødre blev fuldt, hvilke herefter skulde ihjelslaaes ligesom de.","Og dem bleve givne, hver især, lange hvide Kjortler, og der blev sagt til dem, at de skulde hvile sig endnu en liden Tid, indtil Tallet af deres Medtjenere og deres Brødre blev fuldt, hvilke herefter skulde ihjelslaaes ligesom de."],[6,12,"Og jeg saae, at det oplod det sjette Segl, og see, der skete et stort Jordskjælv, og Solen blev sort som en Haarsæk, og Maanen blev som Blod.","Og jeg saae, at det oplod det sjette Segl, og see, der skete et stort Jordskjælv, og Solen blev sort som en Haarsæk, og Maanen blev som Blod."],[6,13,"Og Himmelens Stjerner faldt ned paa Jorden, som et Figentræ nedkaster sine umodne Figen, naar det røres af et stærkt Veir.","Og Himmelens Stjerner faldt ned paa Jorden, som et Figentræ nedkaster sine umodne Figen, naar det røres af et stærkt Veir."],[6,14,"Og Himmelen veg bort, lig en Bog, der sammenrulles, og hvert Bjerg og hver Ø flyttedes af deres Steder.","Og Himmelen veg bort, lig en Bog, der sammenrulles, og hvert Bjerg og hver Ø flyttedes af deres Steder."],[6,15,"Og Kongerne paa Jorden og Fyrsterne og de Rige og Øversterne og de Vældige og hver Træl og hver Fri skjulte sig i Huler og i Bjergenes Kløfter.","Og Kongerne paa Jorden og Fyrsterne og de Rige og Øversterne og de Vældige og hver Træl og hver Fri skjulte sig i Huler og i Bjergenes Kløfter."],[6,16,"Og de sagde til Bjergene og Klipperne: styrter over os og skjuler for hans Ansigt, som sidder paa Thronen, og for Lammets Vrede!","Og de sagde til Bjergene og Klipperne: styrter over os og skjuler for hans Ansigt, som sidder paa Thronen, og for Lammets Vrede!"],[6,17,"Thi hans Vredes den store Dag er kommen; og hvo kan bestaae?","Thi hans Vredes den store Dag er kommen; og hvo kan bestaae?"],[7,1,"Og derefter saae jeg fire Engle staae paa Jordens fire Hjørner, som holdt Jordens fire Vinde, paa det ingen Vind skulle blæse over Jorden, ei heller over Havet, ei heller over noget Træ.","Og derefter saae jeg fire Engle staae paa Jordens fire Hjørner, som holdt Jordens fire Vinde, paa det ingen Vind skulle blæse over Jorden, ei heller over Havet, ei heller over noget Træ."],[7,2,"Og jeg saae en anden Engel opstige fra Solens Opgang, som havde den levende Guds Segl; og han raabte med høi Røst til de fire Engle, hvilke det var givet at skade Jorden og Havet, sigende:","Og jeg saae en anden Engel opstige fra Solens Opgang, som havde den levende Guds Segl; og han raabte med høi Røst til de fire Engle, hvilke det var givet at skade Jorden og Havet, sigende:"],[7,3,"skader ikke Jorden, ei heller Havet, ei heller Træerne, indtil vi faae beseglet vor Guds Tjenere i deres Pander.","skader ikke Jorden, ei heller Havet, ei heller Træerne, indtil vi faae beseglet vor Guds Tjenere i deres Pander."],[7,4,"Og jeg hørte deres Tal, som bleve beseglede, hundrede og fire og fyrretyve tusinde Beseglede af alle Israels Børns Stammer:","Og jeg hørte deres Tal, som bleve beseglede, hundrede og fire og fyrretyve tusinde Beseglede af alle Israels Børns Stammer:"],[7,5,"Af Judas Stamme tolv tusinde Beseglede; af Rubens Stamme tolv tusinde Beseglede; af Gads Stamme tolv tusinde Beseglede;","Af Judas Stamme tolv tusinde Beseglede; af Rubens Stamme tolv tusinde Beseglede; af Gads Stamme tolv tusinde Beseglede;"],[7,6,"af Assers Stamme tolv tusinde Beseglede; af Naphthali’ Stamme tolv tusinde Beseglede; af Manasse’ Stamme tolv tusinde Beseglede;","af Assers Stamme tolv tusinde Beseglede; af Naphthali’ Stamme tolv tusinde Beseglede; af Manasse’ Stamme tolv tusinde Beseglede;"],[7,7,"af Simeons Stamme tolv tusinde Beseglede; af Levi Stamme tolv tusinde Beseglede; af Issachars Stamme tolv tusinde Beseglede;","af Simeons Stamme tolv tusinde Beseglede; af Levi Stamme tolv tusinde Beseglede; af Issachars Stamme tolv tusinde Beseglede;"],[7,8,"af Sebulons Stamme tolv tusinde Beseglede; af Josephs Stamme tolv tusinde Beseglede; af Benjamins Stamme tolv tusinde Beseglede.","af Sebulons Stamme tolv tusinde Beseglede; af Josephs Stamme tolv tusinde Beseglede; af Benjamins Stamme tolv tusinde Beseglede."],[7,9,"Derefter saae jeg, og see, en stor Skare, hvilken Ingen kunde tælle, af alle Hedninger og Stammer og Folk og Tungemaal, som stode for Thronen og for Lammet, iførte lange hvide Klæder og Palmegrene i deres Hænder,","Derefter saae jeg, og see, en stor Skare, hvilken Ingen kunde tælle, af alle Hedninger og Stammer og Folk og Tungemaal, som stode for Thronen og for Lammet, iførte lange hvide Klæder og Palmegrene i deres Hænder,"],[7,10,"og som raabte med høi Røst og sagde: Saliggjørelsen tilhører vor Gud, ham, som sidder paa Thronen og Lammet!","og som raabte med høi Røst og sagde: Saliggjørelsen tilhører vor Gud, ham, som sidder paa Thronen og Lammet!"],[7,11,"Og alle Englene stode omkring Thronen og om de Ældste og om de fire Dyr, og faldt ned for Thronen paa deres Ansigt, og tilbade Gud og sagde:","Og alle Englene stode omkring Thronen og om de Ældste og om de fire Dyr, og faldt ned for Thronen paa deres Ansigt, og tilbade Gud og sagde:"],[7,12,"Amen! Velsignelse og Ære og Viisdom og Tak og Priis og Magt og Styrke være vor Gud i al Evighed! Amen.","Amen! Velsignelse og Ære og Viisdom og Tak og Priis og Magt og Styrke være vor Gud i al Evighed! Amen."],[7,13,"Og en af de Ældste talede og sagde til mig: disse, som ere iførte de lange hvide Kjortler, hvor ere de? og hvorfra ere de komne?","Og en af de Ældste talede og sagde til mig: disse, som ere iførte de lange hvide Kjortler, hvor ere de? og hvorfra ere de komne?"],[7,14,"Og jeg sagde til ham: Herre! du veed det. Og han sagde til mig: disse ere de, som ere komne ud af den store Trængsel, og have tvættet deres Kjortler og have gjort dem hvide i Lammets Blod.","Og jeg sagde til ham: Herre! du veed det. Og han sagde til mig: disse ere de, som ere komne ud af den store Trængsel, og have tvættet deres Kjortler og have gjort dem hvide i Lammets Blod."],[7,15,"Derfor ere de for Guds Throne og tjene ham Dag og Nat i hans Tempel; og han, som sidder paa Thronen, skal udbrede Paulun over dem.","Derfor ere de for Guds Throne og tjene ham Dag og Nat i hans Tempel; og han, som sidder paa Thronen, skal udbrede Paulun over dem."],[7,16,"De skulle ikke hungre mere, ei heller tørste mere, Solen skal ei falde paa dem, ei heller nogen Hede.","De skulle ikke hungre mere, ei heller tørste mere, Solen skal ei falde paa dem, ei heller nogen Hede."],[7,17,"Thi Lammet, som er i Thronens Midte, skal vogte dem og lede dem til levende Vandkilder; og Gud skal aftørre hver Taare af deres Øine.","Thi Lammet, som er i Thronens Midte, skal vogte dem og lede dem til levende Vandkilder; og Gud skal aftørre hver Taare af deres Øine."],[8,1,"Og der det oplod det syvende Segl, blev der Stilhed i Himmelen ved en halv Time.","Og der det oplod det syvende Segl, blev der Stilhed i Himmelen ved en halv Time."],[8,2,"Og jeg saae de syv Engle, som staae for Gud; og dem bleve givne syv Basuner.","Og jeg saae de syv Engle, som staae for Gud; og dem bleve givne syv Basuner."],[8,3,"Og en anden Engel kom og stod ved Røg-Alteret, som havde et Guldrøgelseskar, og ham blev given mangen Røgelse, at han, under alle de Helliges Bønner, skulde offre den paa det Guld-Alter, som er for Thronen.","Og en anden Engel kom og stod ved Røg-Alteret, som havde et Guldrøgelseskar, og ham blev given mangen Røgelse, at han, under alle de Helliges Bønner, skulde offre den paa det Guld-Alter, som er for Thronen."],[8,4,"Og Røgen af Røgelsen opsteg med de Helliges Bønner af Engelens Haand for Gud.","Og Røgen af Røgelsen opsteg med de Helliges Bønner af Engelens Haand for Gud."],[8,5,"Og Engelen tog Røgelsekarret og fyldte det med Ilden af Alteret og kastede det paa Jorden; og der kom Røster og Torden og Lys og Jordskjælv.","Og Engelen tog Røgelsekarret og fyldte det med Ilden af Alteret og kastede det paa Jorden; og der kom Røster og Torden og Lys og Jordskjælv."],[8,6,"Og de syv Engle, som havde de syv Basuner, gjorde sig rede til at basune.","Og de syv Engle, som havde de syv Basuner, gjorde sig rede til at basune."],[8,7,"Og den første Engel basunede, og der kom Hagel og Ild, blandet med Blod, og blev kastet paa Jorden; og den tredie Deel af Træerne opbrændtes, og alt grønt Græs opbrændtes.","Og den første Engel basunede, og der kom Hagel og Ild, blandet med Blod, og blev kastet paa Jorden; og den tredie Deel af Træerne opbrændtes, og alt grønt Græs opbrændtes."],[8,8,"Og den anden Engel basunede, og der blev ligesom et stort Bjerg, brændende i Lue, kastet i Havet; og den tredie Deel af Havet blev Blod.","Og den anden Engel basunede, og der blev ligesom et stort Bjerg, brændende i Lue, kastet i Havet; og den tredie Deel af Havet blev Blod."],[8,9,"Og Trediedelen af Skabningerne i Havet, som havde Liv, døde; og Trediedelen af Skibene blev ødelagt.","Og Trediedelen af Skabningerne i Havet, som havde Liv, døde; og Trediedelen af Skibene blev ødelagt."],[8,10,"Og den tredie Engel basunede, og fra Himmelen faldt en stor Stjerne, brændende som en Fakkel, og den faldt paa Trediedelen af Floderne paa Vandkilderne.","Og den tredie Engel basunede, og fra Himmelen faldt en stor Stjerne, brændende som en Fakkel, og den faldt paa Trediedelen af Floderne paa Vandkilderne."],[8,11,"Og Stjernens Navn kaldtes Malurt; og den tredie Deel af Vandene blev til Malurt, og mange Mennesker døde af Vandene, fordi de vare blevne beske.","Og Stjernens Navn kaldtes Malurt; og den tredie Deel af Vandene blev til Malurt, og mange Mennesker døde af Vandene, fordi de vare blevne beske."],[8,12,"Og en fjerde Engel basunerede, og den tredie Deel af Solen blev ramt og den tredie Deel af Maanen og den tredie Deel af Stjernerne, saa at Trediedelen af dem blev formørket, og at Dagen fattedes Trediedelen af sit Skin og Natten desligeste.","Og en fjerde Engel basunerede, og den tredie Deel af Solen blev ramt og den tredie Deel af Maanen og den tredie Deel af Stjernerne, saa at Trediedelen af dem blev formørket, og at Dagen fattedes Trediedelen af sit Skin og Natten desligeste."],[8,13,"Og jeg saae, og jeg hørte en Engel flyve midt igjennem Himmelen, som sagde med høi Røst: vee, vee, vee dem, som boe paa Jorden, for de øvrige Basunrøster af de tre Engle, som skulle basune!","Og jeg saae, og jeg hørte en Engel flyve midt igjennem Himmelen, som sagde med høi Røst: vee, vee, vee dem, som boe paa Jorden, for de øvrige Basunrøster af de tre Engle, som skulle basune!"],[9,1,"Og de femte Engel basunede, og jeg saae en Stjerne, nedfalden fra Himmelen paa Jorden, og den blev Nøglen given til Afgrundens Brønd.","Og de femte Engel basunede, og jeg saae en Stjerne, nedfalden fra Himmelen paa Jorden, og den blev Nøglen given til Afgrundens Brønd."],[9,2,"Og den oplod Afgrundens Brønd, og en Røg gik op af Brønden lig Røgen af en stor Ovn; og Solen og Luften blev formørket af Brøndens Røg.","Og den oplod Afgrundens Brønd, og en Røg gik op af Brønden lig Røgen af en stor Ovn; og Solen og Luften blev formørket af Brøndens Røg."],[9,3,"Og af Røgen udkom Græshopper paa Jorden, og dem blev givet Magt, som Jordens Skorpioner have Magt.","Og af Røgen udkom Græshopper paa Jorden, og dem blev givet Magt, som Jordens Skorpioner have Magt."],[9,4,"Og der blev sagt til de, at de ikke maatte skade Græsset paa Jorden, ei heller noget Grønt, ei heller noget Træ, men alene de Mennesker, som ikke have Guds Segl i deres Pander.","Og der blev sagt til de, at de ikke maatte skade Græsset paa Jorden, ei heller noget Grønt, ei heller noget Træ, men alene de Mennesker, som ikke have Guds Segl i deres Pander."],[9,5,"Og det blev dem givet ikke at dræbe dem, men at pine dem i fem Maaneder; og Pinen, de voldte, var som Pinen af en Skorpion, naar den stikker et Menneske.","Og det blev dem givet ikke at dræbe dem, men at pine dem i fem Maaneder; og Pinen, de voldte, var som Pinen af en Skorpion, naar den stikker et Menneske."],[9,6,"Og i de samme Dage skulle Menneskene søge Døden, og ikke finde den, og begjere at døe, og Døden skal flye fra dem.","Og i de samme Dage skulle Menneskene søge Døden, og ikke finde den, og begjere at døe, og Døden skal flye fra dem."],[9,7,"Og Græshoppernes Skikkelse lignede Heste, udrustede til Krig, og paa deres Hoveder vare som Kroner af Guld, og deres Ansigter vare som Menneskers Ansigter.","Og Græshoppernes Skikkelse lignede Heste, udrustede til Krig, og paa deres Hoveder vare som Kroner af Guld, og deres Ansigter vare som Menneskers Ansigter."],[9,8,"Og de havde Haar som Kvinders Haar, og deres Tænder vare som Løvers.","Og de havde Haar som Kvinders Haar, og deres Tænder vare som Løvers."],[9,9,"Og de havde Pantsere som Jernpantsere; og deres Vingers Lyd var som Lyd af Vogne, naar mange Heste fare i Krig.","Og de havde Pantsere som Jernpantsere; og deres Vingers Lyd var som Lyd af Vogne, naar mange Heste fare i Krig."],[9,10,"Og de havde Haler ligesom Skorpioner, og der vare Braadde i deres Haler; og deres magt var til at skade Menneskene i fem Maaneder.","Og de havde Haler ligesom Skorpioner, og der vare Braadde i deres Haler; og deres magt var til at skade Menneskene i fem Maaneder."],[9,11,"Og de havde en Konge over sig, Afgrundens Engel; hans Navn er paa Hebraisk Abaddon , og paa Græsk haver han Navnet Apollyon.","Og de havde en Konge over sig, Afgrundens Engel; hans Navn er paa Hebraisk Abaddon , og paa Græsk haver han Navnet Apollyon."],[9,12,"Det første Vee er til Ende; see, der komme endnu to Veer derefter.","Det første Vee er til Ende; see, der komme endnu to Veer derefter."],[9,13,"Og den sjette Engel basunede, og jeg hørte en Røst af de fire Horn paa det Guldalter, som stod for Gud;","Og den sjette Engel basunede, og jeg hørte en Røst af de fire Horn paa det Guldalter, som stod for Gud;"],[9,14,"den sagde til den sjette Engel, der havde Basunen: løs de fire Engle, som ere bundne ved den store Flod Euphrates.","den sagde til den sjette Engel, der havde Basunen: løs de fire Engle, som ere bundne ved den store Flod Euphrates."],[9,15,"Og de fire Engle bleve løste, som til Time og Dag og Maaned og Aar vare beredte at ihjelslaae den tredie Deel af Menneskene.","Og de fire Engle bleve løste, som til Time og Dag og Maaned og Aar vare beredte at ihjelslaae den tredie Deel af Menneskene."],[9,16,"Og Tallet paa Rytternes Hær var to Gange ti tusinde Gange ti tusinde; og jeg hørte deres Tal.","Og Tallet paa Rytternes Hær var to Gange ti tusinde Gange ti tusinde; og jeg hørte deres Tal."],[9,17,"Og saaledes saae jeg Hestene i Synet og dem, som sadde derpaa, hvilke havde ildrøde og fiolblaae og svovlgule Pantsere; og Hestenes Hoveder vare som Løvers Hoveder, og af deres Munde udgik Ild og Røg og Svovl.","Og saaledes saae jeg Hestene i Synet og dem, som sadde derpaa, hvilke havde ildrøde og fiolblaae og svovlgule Pantsere; og Hestenes Hoveder vare som Løvers Hoveder, og af deres Munde udgik Ild og Røg og Svovl."],[9,18,"Af disse tre, af Ilden og Røgen og Svovlet, som udgik af deres Munde, blev Trediedelen af Menneskene ihjelslagen.","Af disse tre, af Ilden og Røgen og Svovlet, som udgik af deres Munde, blev Trediedelen af Menneskene ihjelslagen."],[9,19,"Thi deres magt er i deres Mund; thi deres Haler ere ligesom Hugorme, og de have Hoveder, og med dem gjøre de Skade.","Thi deres magt er i deres Mund; thi deres Haler ere ligesom Hugorme, og de have Hoveder, og med dem gjøre de Skade."],[9,20,"Og de øvrige Mennesker, som ikke vare ihjelslagne i disse Plager, hverken omvendte sig fra deres Hænders Gjerninger, faa at de ikke tilbade Djævle og Afguder af Guld og af Sølv og af Kobber og af Steen og af Træ, som hverken kunne see eller høre eller gaae;","Og de øvrige Mennesker, som ikke vare ihjelslagne i disse Plager, hverken omvendte sig fra deres Hænders Gjerninger, faa at de ikke tilbade Djævle og Afguder af Guld og af Sølv og af Kobber og af Steen og af Træ, som hverken kunne see eller høre eller gaae;"],[9,21,"ei heller omvendte de sig fra deres Mord eller fra deres Trolddom eller fra deres Horeri eller fra deres Tyveri.","ei heller omvendte de sig fra deres Mord eller fra deres Trolddom eller fra deres Horeri eller fra deres Tyveri."],[10,1,"Og jeg saae en anden vældig Engel komme ned fra Himmelen, svøbt i en Sky, og en Regnbue var paa hans Hoved, og hans Ansigt var som Solen, og hans Fødder som Ildstøtter.","Og jeg saae en anden vældig Engel komme ned fra Himmelen, svøbt i en Sky, og en Regnbue var paa hans Hoved, og hans Ansigt var som Solen, og hans Fødder som Ildstøtter."],[10,2,"Og han havde i sin Haand en liden Bog, som var opladt, og han satte sin høire Fod paa Havet, men den venstre paa Jorden.","Og han havde i sin Haand en liden Bog, som var opladt, og han satte sin høire Fod paa Havet, men den venstre paa Jorden."],[10,3,"Og han raabte med stærk Røst, som en Løve brøler; og der han havde raabt, talede de syv Tordener deres Røster.","Og han raabte med stærk Røst, som en Løve brøler; og der han havde raabt, talede de syv Tordener deres Røster."],[10,4,"Og der de syv Tordener havde talet deres Røster, vilde jeg til at skrive; og jeg hørte en Røst fra Himmelen, som sagde til mig: forsegl, hvad de syv Tordener talede, men nedskriv det ikke.","Og der de syv Tordener havde talet deres Røster, vilde jeg til at skrive; og jeg hørte en Røst fra Himmelen, som sagde til mig: forsegl, hvad de syv Tordener talede, men nedskriv det ikke."],[10,5,"Og Engelen, som jeg saae staae paa Havet og paa Jorden, opløftede sin Haand til Himmelen,","Og Engelen, som jeg saae staae paa Havet og paa Jorden, opløftede sin Haand til Himmelen,"],[10,6,"og svoer ved den, som lever i al Evighed, som skabte Himmelen og hvad derudi er, og Jorden og hvad derudi er, og Havet og hvad derudi er, at der ikke mere skal gives Tid;","og svoer ved den, som lever i al Evighed, som skabte Himmelen og hvad derudi er, og Jorden og hvad derudi er, og Havet og hvad derudi er, at der ikke mere skal gives Tid;"],[10,7,"men i de Dage, da den syvende Engels Røst skal høres, skal Guds skjulte Raad fuldkommes, som han haver forkyndet sine Tjenere, Propheterne.","men i de Dage, da den syvende Engels Røst skal høres, skal Guds skjulte Raad fuldkommes, som han haver forkyndet sine Tjenere, Propheterne."],[10,8,"Og den Røst, som jeg havde hørt fra Himmelen, talede atter med mig og sagde: gak hen, tag den liden Bog, som er opladt i Engelens Haand, der staaer paa Havet og paa Jorden.","Og den Røst, som jeg havde hørt fra Himmelen, talede atter med mig og sagde: gak hen, tag den liden Bog, som er opladt i Engelens Haand, der staaer paa Havet og paa Jorden."],[10,9,"Og jeg gik hen til Engelen og sagde til ham: giv mig den liden Bog. Og han sagde til mig: tag og nedsvælg den! og den skal smerte i dit Liv, men i din Mund skal den være sød som Honning.","Og jeg gik hen til Engelen og sagde til ham: giv mig den liden Bog. Og han sagde til mig: tag og nedsvælg den! og den skal smerte i dit Liv, men i din Mund skal den være sød som Honning."],[10,10,"Og jeg tog den liden Bog af Engelens Haand og nedsvælgede den: og den var i min Mund sød som Honning, men der jeg havde nedsvælget den, følede jeg Smerte i mit Liv.","Og jeg tog den liden Bog af Engelens Haand og nedsvælgede den: og den var i min Mund sød som Honning, men der jeg havde nedsvælget den, følede jeg Smerte i mit Liv."],[10,11,"Og han sagde til mig: det bør dig atter at prophetere imod Folk og Hedninger og Tungemaal og mange Konger.","Og han sagde til mig: det bør dig atter at prophetere imod Folk og Hedninger og Tungemaal og mange Konger."],[11,1,"Og mig blev givet et Rør, ligesom en Maalestok; og Engelen stod der, sigende: staa op og maal Guds Tempel og Alteret og dem, som tilbede derudi.","Og mig blev givet et Rør, ligesom en Maalestok; og Engelen stod der, sigende: staa op og maal Guds Tempel og Alteret og dem, som tilbede derudi."],[11,2,"Men Forgaarden udenfor Templet, gaa den forbi og maal den ikke, thi den er given Hedningerne; og de skulle nedtræde den hellige Stad i to og fyrretyve Maaneder.","Men Forgaarden udenfor Templet, gaa den forbi og maal den ikke, thi den er given Hedningerne; og de skulle nedtræde den hellige Stad i to og fyrretyve Maaneder."],[11,3,"Og jeg vil give mine tvende Vidner, at de skulle prophetere tusinde to hundrede og tresindstyve Dage, iførte Sække.","Og jeg vil give mine tvende Vidner, at de skulle prophetere tusinde to hundrede og tresindstyve Dage, iførte Sække."],[11,4,"Disse ere de tvende Olietræer og de tvende Lysestager, som staae for Jordens Gud.","Disse ere de tvende Olietræer og de tvende Lysestager, som staae for Jordens Gud."],[11,5,"Og dersom Nogen vil gjøre dem Skade, udgaaer der Ild af deres Mund og fortærer deres Fjender; og dersom Nogen vil gjøre dem Skade, bør det ham saaledes at ihjelslaaes.","Og dersom Nogen vil gjøre dem Skade, udgaaer der Ild af deres Mund og fortærer deres Fjender; og dersom Nogen vil gjøre dem Skade, bør det ham saaledes at ihjelslaaes."],[11,6,"Disse have magt at tillukke Himmelen, at der ingen Regn skal falde i deres Propheties Dage; og de have Magt over Vandene, at forvandle dem til Blod, og at slaae Jorden med allehaande Plager, saa ofte de ville.","Disse have magt at tillukke Himmelen, at der ingen Regn skal falde i deres Propheties Dage; og de have Magt over Vandene, at forvandle dem til Blod, og at slaae Jorden med allehaande Plager, saa ofte de ville."],[11,7,"Og naar de faae fuldendt deres Vidnesbyrd, skal det Dyr, som opstiger af Afgrunden, føre Krig imod dem og overvinde dem og ihjelslaae dem.","Og naar de faae fuldendt deres Vidnesbyrd, skal det Dyr, som opstiger af Afgrunden, føre Krig imod dem og overvinde dem og ihjelslaae dem."],[11,8,"Og deres Legemer skulle ligge paa den store Stads Gader, hvilken i aandelig Mening kaldes Sodoma og Ægypten, der, hvor vor Herre er korsfæstet.","Og deres Legemer skulle ligge paa den store Stads Gader, hvilken i aandelig Mening kaldes Sodoma og Ægypten, der, hvor vor Herre er korsfæstet."],[11,9,"Og nogle af Folkeslagene og Stammerne og Tungemaalene og Hedningerne skulle see deres Legemer tre Dage og en halv og ikke tilstede deres Legemer at lægges i Graven.","Og nogle af Folkeslagene og Stammerne og Tungemaalene og Hedningerne skulle see deres Legemer tre Dage og en halv og ikke tilstede deres Legemer at lægges i Graven."],[11,10,"Og de, som boe paa Jorden, skulle glæde sig over dem og fryde sig; og de skulle sende hverandre Gaver, fordi disse to Propheter vare dem til Plage, som boe paa Jorden.","Og de, som boe paa Jorden, skulle glæde sig over dem og fryde sig; og de skulle sende hverandre Gaver, fordi disse to Propheter vare dem til Plage, som boe paa Jorden."],[11,11,"Og efter de tre Dage og en halv kom Livs Aande fra Gud i dem; og de stode paa deres Fødder, og en stor Frygt faldt paa dem, som saae dem.","Og efter de tre Dage og en halv kom Livs Aande fra Gud i dem; og de stode paa deres Fødder, og en stor Frygt faldt paa dem, som saae dem."],[11,12,"Og de hørte en stærk Røst fra Himmelen, som sagde til dem: stiger hid op. Og de stege op til Himmelen i en Sky, og deres Fjender saae dem.","Og de hørte en stærk Røst fra Himmelen, som sagde til dem: stiger hid op. Og de stege op til Himmelen i en Sky, og deres Fjender saae dem."],[11,13,"Og i samme Stund skete et stort Jordskjælv, og Tiendedelen af Staden faldt, og der bleve ihjelslagne i Jordskjælvet syv tusinde Personer; og de andre bleve forfærdede og gave Himmelens Gud Ære.","Og i samme Stund skete et stort Jordskjælv, og Tiendedelen af Staden faldt, og der bleve ihjelslagne i Jordskjælvet syv tusinde Personer; og de andre bleve forfærdede og gave Himmelens Gud Ære."],[11,14,"Det andet Vee er til Ende; see, det tredie Vee kommer snart.","Det andet Vee er til Ende; see, det tredie Vee kommer snart."],[11,15,"Og den syvende Engel basunede, og der hørtes stærke Røster i Himmelen, som sagde: Verdens Riger ere blevne vor Herres og hans Salvedes, og han skal regjere i al Evighed.","Og den syvende Engel basunede, og der hørtes stærke Røster i Himmelen, som sagde: Verdens Riger ere blevne vor Herres og hans Salvedes, og han skal regjere i al Evighed."],[11,16,"Og de fire og tyve Ældste, som sadde for Gud paa deres Throner, faldt ned paa deres Ansigter og tilbade Gud, sigende:","Og de fire og tyve Ældste, som sadde for Gud paa deres Throner, faldt ned paa deres Ansigter og tilbade Gud, sigende:"],[11,17,"vi takke dig, Herre, Gud, den Almægtige, den, der er og der var og der kommer! fordi du haver taget din store Magt og dit Kongedømme.","vi takke dig, Herre, Gud, den Almægtige, den, der er og der var og der kommer! fordi du haver taget din store Magt og dit Kongedømme."],[11,18,"Og Hedningerne vrededes, og din Vrede er kommen, og de Dødes Tid, at de skulle dømmes, og at du skal give dine Tjenere Propheterne Løn, og de Hellige og dem, som frygte dit Navn, de Smaa og de Store, og fordærve dem, som fordærve Jorden.","Og Hedningerne vrededes, og din Vrede er kommen, og de Dødes Tid, at de skulle dømmes, og at du skal give dine Tjenere Propheterne Løn, og de Hellige og dem, som frygte dit Navn, de Smaa og de Store, og fordærve dem, som fordærve Jorden."],[11,19,"Og Guds Tempel blev opladt i Himmelen, og hans Pagtes Ark blev seet i hans Tempel, og der kom Lyn og Røster og Tordener og Jordskjælv og stor Hagel.","Og Guds Tempel blev opladt i Himmelen, og hans Pagtes Ark blev seet i hans Tempel, og der kom Lyn og Røster og Tordener og Jordskjælv og stor Hagel."],[12,1,"Og et stort Tegn blev seet i Himmelen: en Kvinde beklædt med Solen, og Maanen under hendes Fødder, og paa hendes Hoved en Krone af tolv Stjerner.","Og et stort Tegn blev seet i Himmelen: en Kvinde beklædt med Solen, og Maanen under hendes Fødder, og paa hendes Hoved en Krone af tolv Stjerner."],[12,2,"Og hun var frugtsommelig og skreg i Barnsnød under Fødselsveer.","Og hun var frugtsommelig og skreg i Barnsnød under Fødselsveer."],[12,3,"Og et andet Tegn blev seet i Himmelen, og see, der var en stor ildrød Drage, som havde syv Hoveder og ti Horn, og paa sine Hoveder syv Kroner.","Og et andet Tegn blev seet i Himmelen, og see, der var en stor ildrød Drage, som havde syv Hoveder og ti Horn, og paa sine Hoveder syv Kroner."],[12,4,"Og dens Hale drog Trediedelen af Himmelens Stjerner og kastede dem paa Jorden. Og Dragen stod for Kvinden, som skulde føde, og naar hun havde født sit Barn, den da kunde opsluge det.","Og dens Hale drog Trediedelen af Himmelens Stjerner og kastede dem paa Jorden. Og Dragen stod for Kvinden, som skulde føde, og naar hun havde født sit Barn, den da kunde opsluge det."],[12,5,"Og hun fødte et Drengebarn, som skulde regjere alle Folkeslag med et Jernspiir; og hendes Barn blev bortrykt til Gud og hans Throne.","Og hun fødte et Drengebarn, som skulde regjere alle Folkeslag med et Jernspiir; og hendes Barn blev bortrykt til Gud og hans Throne."],[12,6,"Og Kvinden flyede i Ørken, hvor hun haver et Sted beredt af Gud, at de der skulde ernære hende tusinde to hundrede og tresindstyve Dage.","Og Kvinden flyede i Ørken, hvor hun haver et Sted beredt af Gud, at de der skulde ernære hende tusinde to hundrede og tresindstyve Dage."],[12,7,"Og der blev en Strid i Himmelen: Michael og hans Engle strede mod Dragen, og Dragen sted og dens Engle.","Og der blev en Strid i Himmelen: Michael og hans Engle strede mod Dragen, og Dragen sted og dens Engle."],[12,8,"Men de mægtede Intet; ei heller blev deres Sted ydermere fundet i Himmelen.","Men de mægtede Intet; ei heller blev deres Sted ydermere fundet i Himmelen."],[12,9,"Og den store Drage blev nedstyrtet, den gamle Slange, som kaldes Djævelen og Satanas, som forfører den ganske Verden, blev nedstyrtet paa Jorden, og hans Engle bleve nedstyrtede med ham.","Og den store Drage blev nedstyrtet, den gamle Slange, som kaldes Djævelen og Satanas, som forfører den ganske Verden, blev nedstyrtet paa Jorden, og hans Engle bleve nedstyrtede med ham."],[12,10,"Og jeg hørte en stærk Røst i Himmelen, som sagde: nu er Saligheden og Kraften og Riget blevet vor Guds, og magten han Salvedes; thi nedstyrtet er vore Brødres Anklager, som anklagede dem for vor Gud Dag og Nat.","Og jeg hørte en stærk Røst i Himmelen, som sagde: nu er Saligheden og Kraften og Riget blevet vor Guds, og magten han Salvedes; thi nedstyrtet er vore Brødres Anklager, som anklagede dem for vor Gud Dag og Nat."],[12,11,"Og de have overvundet ham ved Lammets Blod og ved Ordet, de vidnede; og de elskede ikke deres Liv indtil Døden .","Og de have overvundet ham ved Lammets Blod og ved Ordet, de vidnede; og de elskede ikke deres Liv indtil Døden ."],[12,12,"Derfor fryder Eder, I Himle, og I, som boe i dem! Vee, dem, som beboe Jorden og Havet! thi Djævelen er nedstegen til Eder; han haver stor Vrede, fordi han veed, at han kun haver en liden Tid.","Derfor fryder Eder, I Himle, og I, som boe i dem! Vee, dem, som beboe Jorden og Havet! thi Djævelen er nedstegen til Eder; han haver stor Vrede, fordi han veed, at han kun haver en liden Tid."],[12,13,"Og der Dragen saae, at den var styrtet til Jorden, forfulgte den Kvinden, som havde født Drengebarnet.","Og der Dragen saae, at den var styrtet til Jorden, forfulgte den Kvinden, som havde født Drengebarnet."],[12,14,"Og den store Ørns tvende Vinger bleve Kvinden givne, at hun skulle flyve til Ørken, til sit Sted, hvor hun næres en Tid og Tider og en halv Tid, borte fra Slangen.","Og den store Ørns tvende Vinger bleve Kvinden givne, at hun skulle flyve til Ørken, til sit Sted, hvor hun næres en Tid og Tider og en halv Tid, borte fra Slangen."],[12,15,"Og Slangen skød af sin Mund efter Kvinden Vand som en Strøm for at bortskylle hende med Strømmen.","Og Slangen skød af sin Mund efter Kvinden Vand som en Strøm for at bortskylle hende med Strømmen."],[12,16,"Og Jorden kom Kvinden til Hjælp; og Jorden oplod sin Mund og opslugte Strømmen, som Dragen havde skudt af sin Mund.","Og Jorden kom Kvinden til Hjælp; og Jorden oplod sin Mund og opslugte Strømmen, som Dragen havde skudt af sin Mund."],[12,17,"Og Dragen forbittredes paa Kvinden, og gik bort at føre Krig mod de Øvrige af hendes Sæd, dem, som bevare Guds Befalinger og holde ved Jesu Christi Vidnesbyrd.","Og Dragen forbittredes paa Kvinden, og gik bort at føre Krig mod de Øvrige af hendes Sæd, dem, som bevare Guds Befalinger og holde ved Jesu Christi Vidnesbyrd."],[12,18,"Og jeg stod paa Havets Sand.","Og jeg stod paa Havets Sand."],[13,1,"Og jeg saae et Dyr stige op af Havet, som havde syv Hoveder og ti Horn, og paa sine Horn ti Kroner, og paa sine Hoveder Bespottelsens Navn.","Og jeg saae et Dyr stige op af Havet, som havde syv Hoveder og ti Horn, og paa sine Horn ti Kroner, og paa sine Hoveder Bespottelsens Navn."],[13,2,"Og Dyret, som jeg saae, var ligt en Parder og dets Fødder som en Bjørns og dets Mund som en Løves Mund; og Dragen gav det sin Kraft og sin Throne og stor Magt.","Og Dyret, som jeg saae, var ligt en Parder og dets Fødder som en Bjørns og dets Mund som en Løves Mund; og Dragen gav det sin Kraft og sin Throne og stor Magt."],[13,3,"Og jeg saae eet af dets Hoveder ligesom saaret til Døden, og dets dødelige Saar blev lægt, og al Jorden forundrede sig og fulgte efter Dyret.","Og jeg saae eet af dets Hoveder ligesom saaret til Døden, og dets dødelige Saar blev lægt, og al Jorden forundrede sig og fulgte efter Dyret."],[13,4,"Og de tilbade Dragen, som havde givet Dyret Magt; og de tilbade Dyret og sagde: hvo er Dyret lig? hvo kan stride imod det?","Og de tilbade Dragen, som havde givet Dyret Magt; og de tilbade Dyret og sagde: hvo er Dyret lig? hvo kan stride imod det?"],[13,5,"Og en Mund blev det given til at tale store Ting og Bespottelse, og Magt blev det given til at virke i to og fyrretyve Maaneder.","Og en Mund blev det given til at tale store Ting og Bespottelse, og Magt blev det given til at virke i to og fyrretyve Maaneder."],[13,6,"Og det oplod sin Mund til Bespottelse imod Gud, at bespotte hans Navn og hans Paulun, og dem, som boe i Himmelen.","Og det oplod sin Mund til Bespottelse imod Gud, at bespotte hans Navn og hans Paulun, og dem, som boe i Himmelen."],[13,7,"Og der blev givet det at føre Krig mod de Hellige og at overvinde dem; og Magt blev det givet over hver Stamme og hvert Tungemaal og hvert Folk.","Og der blev givet det at føre Krig mod de Hellige og at overvinde dem; og Magt blev det givet over hver Stamme og hvert Tungemaal og hvert Folk."],[13,8,"Og de skulle tilbede det, Alle, som boe paa Jorden, hvis Navne ikke fra Verdens Begyndelse ere skrevne i Lammets, det slagtedes, Livsens Bog.","Og de skulle tilbede det, Alle, som boe paa Jorden, hvis Navne ikke fra Verdens Begyndelse ere skrevne i Lammets, det slagtedes, Livsens Bog."],[13,9,"Dersom Nogen haver Øren, han høre!","Dersom Nogen haver Øren, han høre!"],[13,10,"Dersom Nogen samler til Fængsel, han gaaer i Fængsel; dersom Nogen Dræber med Sværd, ham bør det at dræbes med Sværd. Her er de Helliges Taalmodighed og Tro.","Dersom Nogen samler til Fængsel, han gaaer i Fængsel; dersom Nogen Dræber med Sværd, ham bør det at dræbes med Sværd. Her er de Helliges Taalmodighed og Tro."],[13,11,"Og jeg saae et andet Dyr stige op af Jorden, og det havde to Horn lige med Lammet og talede som Dragen.","Og jeg saae et andet Dyr stige op af Jorden, og det havde to Horn lige med Lammet og talede som Dragen."],[13,12,"Og det øver al det første Dyrs magt for dets Aasyn og gjør, at Jorden og de, som boe derpaa, skulle tilbede det første Dyr, hvis dødelige Saar blev lægt.","Og det øver al det første Dyrs magt for dets Aasyn og gjør, at Jorden og de, som boe derpaa, skulle tilbede det første Dyr, hvis dødelige Saar blev lægt."],[13,13,"Og det gjør store Tegn, saa at det endog kommer Ild til at falde ned af Himmelen paa Jorden for Menneskenes Aasyn.","Og det gjør store Tegn, saa at det endog kommer Ild til at falde ned af Himmelen paa Jorden for Menneskenes Aasyn."],[13,14,"Og det forfører dem, som boe paa Jorden, for de Tegns Skyld, hvilke ere givne det at gjøre for Dyrets Aasyn, sigende til dem, som boe paa Jorden, at de skulle gjøre et Billede for det Dyr, som fik Saar af Sværdet, og dog levede.","Og det forfører dem, som boe paa Jorden, for de Tegns Skyld, hvilke ere givne det at gjøre for Dyrets Aasyn, sigende til dem, som boe paa Jorden, at de skulle gjøre et Billede for det Dyr, som fik Saar af Sværdet, og dog levede."],[13,15,"Og det fik Magt at give Dyrets Billede Aand, at Dyrets Billede endog kunde tale og gjøre, at hvilkesomhelst, der ikke vilde tilbede Dyrets Billede, skulde ihjelslaaes.","Og det fik Magt at give Dyrets Billede Aand, at Dyrets Billede endog kunde tale og gjøre, at hvilkesomhelst, der ikke vilde tilbede Dyrets Billede, skulde ihjelslaaes."],[13,16,"Og det gjør, at der gives Alle, baade Smaa og Store, baade Rige og Fattige, baade Frie og Trælle, et Mærke i deres høire Haand eller i deres Pande;","Og det gjør, at der gives Alle, baade Smaa og Store, baade Rige og Fattige, baade Frie og Trælle, et Mærke i deres høire Haand eller i deres Pande;"],[13,17,"og at Ingen kan kjøbe eller sælge, uden den, som haver Mærket eller Dyrets Navn eller dets Navns Tal.","og at Ingen kan kjøbe eller sælge, uden den, som haver Mærket eller Dyrets Navn eller dets Navns Tal."],[13,18,"Her er Viisdom! Hvo som haver Forstand, beregne Dyrets Tal; thi det er et Menneskes Tal, og dets Tal er sex hundrede tresindstyve og sex.","Her er Viisdom! Hvo som haver Forstand, beregne Dyrets Tal; thi det er et Menneskes Tal, og dets Tal er sex hundrede tresindstyve og sex."],[14,1,"Og jeg saae, og see, Lammet stod paa Zions Bjerg og med det hundrede fire og fyrretyve Tusinde, som havde dets Faders Navn skrevet i deres Pander.","Og jeg saae, og see, Lammet stod paa Zions Bjerg og med det hundrede fire og fyrretyve Tusinde, som havde dets Faders Navn skrevet i deres Pander."],[14,2,"Og jeg hørte en Røst af Himmelen, som mange Vandes Lyd og som en stærk Tordens Lyd, og jeg hørte Harpelegeres Lyd, som legede paa deres Harper.","Og jeg hørte en Røst af Himmelen, som mange Vandes Lyd og som en stærk Tordens Lyd, og jeg hørte Harpelegeres Lyd, som legede paa deres Harper."],[14,3,"Og de sang en ny Sang for Thronen og for de fire Dyr og de Ældste! og Ingen kunde lære den Sang, uden de hundrede fire og fyrretyve Tusinde, de Kjøbte fra Jorden.","Og de sang en ny Sang for Thronen og for de fire Dyr og de Ældste! og Ingen kunde lære den Sang, uden de hundrede fire og fyrretyve Tusinde, de Kjøbte fra Jorden."],[14,4,"Disse ere de, som ikke have besmittet sig med Kvinder, thi de ere Jomfruer; disse ere de, som følge Lammet, i hvor det gaaer. Disse ere Kjøbte fra Menneskene, en Førstegrøde for Gud og Lammet,","Disse ere de, som ikke have besmittet sig med Kvinder, thi de ere Jomfruer; disse ere de, som følge Lammet, i hvor det gaaer. Disse ere Kjøbte fra Menneskene, en Førstegrøde for Gud og Lammet,"],[14,5,"og i deres Mund er ikke funden Svig; thi de ere ustraffelige for Guds Throne.","og i deres Mund er ikke funden Svig; thi de ere ustraffelige for Guds Throne."],[14,6,"Og jeg saae en anden Engel flyve midt igjennem Himmelen, som havde et evigt Evangelium at forkynde dem, som boe paa Jorden, og alle Slægter og Stammer og Tungemaal og Folk;","Og jeg saae en anden Engel flyve midt igjennem Himmelen, som havde et evigt Evangelium at forkynde dem, som boe paa Jorden, og alle Slægter og Stammer og Tungemaal og Folk;"],[14,7,"som sagde med høi Røst: frygter Gud, og giver ham Ære, thi hans Doms Time er kommen; og tilbeder den, som haver gjort Himmelen og Jorden og Havet og Vandenes Kilder.","som sagde med høi Røst: frygter Gud, og giver ham Ære, thi hans Doms Time er kommen; og tilbeder den, som haver gjort Himmelen og Jorden og Havet og Vandenes Kilder."],[14,8,"Og en anden Engel fulgte, som sagde: den er falden, den er falden, Babylon den store Stad; thi den haver givet alle Hedninger at drikke af sit Horeries giftige Viin.","Og en anden Engel fulgte, som sagde: den er falden, den er falden, Babylon den store Stad; thi den haver givet alle Hedninger at drikke af sit Horeries giftige Viin."],[14,9,"Og den tredie Engel fulgte dem og sagde med høi Røst: dersom Nogen tilbeder Dyret og dets Billede og tager Mærket i sin Pande eller i sin Haand,","Og den tredie Engel fulgte dem og sagde med høi Røst: dersom Nogen tilbeder Dyret og dets Billede og tager Mærket i sin Pande eller i sin Haand,"],[14,10,"han drikke og Guds Vredes Viin, som er iskjenket ublandet i hans Fortørnelses Kalk; og han skal pines med Ild og Svovl for de hellige Engles og for Lammets Aasyn.","han drikke og Guds Vredes Viin, som er iskjenket ublandet i hans Fortørnelses Kalk; og han skal pines med Ild og Svovl for de hellige Engles og for Lammets Aasyn."],[14,11,"Og deres Pines Røg opstiger i al Evighed; og de have ikke Hvile Dag eller Nat, de, som tilbede Dyret og dets Billede, og hvo som annammer dets Navns Mærke.","Og deres Pines Røg opstiger i al Evighed; og de have ikke Hvile Dag eller Nat, de, som tilbede Dyret og dets Billede, og hvo som annammer dets Navns Mærke."],[14,12,"Her er de Helliges Taalmodighed; her ere de, som bevare Guds Befalinger og Jesu Tro.","Her er de Helliges Taalmodighed; her ere de, som bevare Guds Befalinger og Jesu Tro."],[14,13,"Og jeg hørte en Røst af Himmelen, som sagde til mig: skriv: salige ere de Døde, som døe i Herren herefter. Ja, Aanden siger, at de skulle hvile fra deres Arbeider, men deres Gjerninger følge med dem.","Og jeg hørte en Røst af Himmelen, som sagde til mig: skriv: salige ere de Døde, som døe i Herren herefter. Ja, Aanden siger, at de skulle hvile fra deres Arbeider, men deres Gjerninger følge med dem."],[14,14,"Og jeg saae, og see, en hvid Sky, og En sad paa Skyen, lig et Menneskes Søn, som havde en Guldkrone paa sit Hoved og en skarp Segel i sin Haand.","Og jeg saae, og see, en hvid Sky, og En sad paa Skyen, lig et Menneskes Søn, som havde en Guldkrone paa sit Hoved og en skarp Segel i sin Haand."],[14,15,"Og en anden Engel udgik af Templet, som raabte med høi Røst til den, som sad paa Skyen: udstræk din Segl og høst; thi Timen at høste er kommen, fordi Jordens Høst er moden.","Og en anden Engel udgik af Templet, som raabte med høi Røst til den, som sad paa Skyen: udstræk din Segl og høst; thi Timen at høste er kommen, fordi Jordens Høst er moden."],[14,16,"Og den, som sad paa Skyen, lod sin Segel gaae over Jorden, og Jorden blev høstet.","Og den, som sad paa Skyen, lod sin Segel gaae over Jorden, og Jorden blev høstet."],[14,17,"Og en anden Engel udgik af Templet i Himmelen; ogsaa han havde en skarp Segl.","Og en anden Engel udgik af Templet i Himmelen; ogsaa han havde en skarp Segl."],[14,18,"Og en anden Engel udgik fra Alteret, som havde Magt over Ilden; og han raabte med stærkt Skrig til den, som havde den skarpe Segel, sigende: udstræk din skarpe Segel og afskær Druerne af Jordens Viintræ; thi dets Druer ere modne.","Og en anden Engel udgik fra Alteret, som havde Magt over Ilden; og han raabte med stærkt Skrig til den, som havde den skarpe Segel, sigende: udstræk din skarpe Segel og afskær Druerne af Jordens Viintræ; thi dets Druer ere modne."],[14,19,"Og Engelen lod sin Segel gaae over Jorden og afskar Frugten af Jordens Viintræ og kastede den i Guds Vredes store Persekar.","Og Engelen lod sin Segel gaae over Jorden og afskar Frugten af Jordens Viintræ og kastede den i Guds Vredes store Persekar."],[14,20,"Og Persekarret blev traadt udenfor Staden, og der gik Blod ud af Persekarret indtil Hestenes Bidsler, tusinde og sex hundrede Stadier langt.","Og Persekarret blev traadt udenfor Staden, og der gik Blod ud af Persekarret indtil Hestenes Bidsler, tusinde og sex hundrede Stadier langt."],[15,1,"Og jeg saae et andet Tegn i Himmelen, stort og forunderligt: syv Engle, som havde de syv sidste Plager; thi med disse fuldkommes Guds Vrede.","Og jeg saae et andet Tegn i Himmelen, stort og forunderligt: syv Engle, som havde de syv sidste Plager; thi med disse fuldkommes Guds Vrede."],[15,2,"Og jeg saae som et Glarhav, blandet med Ild, og dem, som havde vundet Seier over Dyret og over dets Billede og over dets Mærke og over dets Navns Tal, staaende ved Glarhavet og holdende Guds Harper.","Og jeg saae som et Glarhav, blandet med Ild, og dem, som havde vundet Seier over Dyret og over dets Billede og over dets Mærke og over dets Navns Tal, staaende ved Glarhavet og holdende Guds Harper."],[15,3,"Og de sang Mose’, den Guds Tjeners, Sang, og Lammets Sang, sigende: store og forunderlige ere dine Gjerninger, Herre, Gud, du Almægtige! Retfærdige og sande ere dine Veie, du de Helliges Konge!","Og de sang Mose’, den Guds Tjeners, Sang, og Lammets Sang, sigende: store og forunderlige ere dine Gjerninger, Herre, Gud, du Almægtige! Retfærdige og sande ere dine Veie, du de Helliges Konge!"],[15,4,"Hvo skulde ikke frygte dig, Herre! og prise dit Navn? Thi du er alene hellig; thi alle Folkeslag skulle komme og tilbede for dit Aasyn, fordi dine Domme ere aabenbarede.","Hvo skulde ikke frygte dig, Herre! og prise dit Navn? Thi du er alene hellig; thi alle Folkeslag skulle komme og tilbede for dit Aasyn, fordi dine Domme ere aabenbarede."],[15,5,"Og derefter saae jeg, og see, Vidnesbyrdets Tabernakel i Himmelen blev opladt,","Og derefter saae jeg, og see, Vidnesbyrdets Tabernakel i Himmelen blev opladt,"],[15,6,"og de syv Engle, som havde de syv Plager, udgik af Templet, iførte et reent og skinnende Linklæde og opbundne under Brystet med Guldbelter.","og de syv Engle, som havde de syv Plager, udgik af Templet, iførte et reent og skinnende Linklæde og opbundne under Brystet med Guldbelter."],[15,7,"Og eet af de fire Dyr gav de syv Engle syv Guldskaaler fyldte med Guds Vrede, hans, som lever i al Evighed.","Og eet af de fire Dyr gav de syv Engle syv Guldskaaler fyldte med Guds Vrede, hans, som lever i al Evighed."],[15,8,"Og Templet fyldtes med Røg af Guds Herlighed og af hans Magt; og Ingen kunde indgaae i Templet, førend de syv Engles syv Plager fik Ende.","Og Templet fyldtes med Røg af Guds Herlighed og af hans Magt; og Ingen kunde indgaae i Templet, førend de syv Engles syv Plager fik Ende."],[16,1,"Og jeg hørte en stærk Røst fra Templet, som sagde til de syv Engle: gaaer hen og udgyder Guds Vredes Skaaler paa Jorden.","Og jeg hørte en stærk Røst fra Templet, som sagde til de syv Engle: gaaer hen og udgyder Guds Vredes Skaaler paa Jorden."],[16,2,"Og den første gik hen og udgød sin Skaal paa Jorden, og der blev en ond og fordærvelig Byld paa de Mennesker, som havde Dyrets Mærke, og dem, som tilbade dets Billede.","Og den første gik hen og udgød sin Skaal paa Jorden, og der blev en ond og fordærvelig Byld paa de Mennesker, som havde Dyrets Mærke, og dem, som tilbade dets Billede."],[16,3,"Og den anden Engel udgød sin Skaal i Havet, og det blev Blod som af en Myrdet, og hver levende Sjæl i Havet døde.","Og den anden Engel udgød sin Skaal i Havet, og det blev Blod som af en Myrdet, og hver levende Sjæl i Havet døde."],[16,4,"Og den tredie Engel udgød sin Skaal i Floderne og Vandkilderne, og de bleve Blod.","Og den tredie Engel udgød sin Skaal i Floderne og Vandkilderne, og de bleve Blod."],[16,5,"Og jeg hørte Vandenes Engel sige: retfærdig er du Herre! du, som er og som var, du Hellige, at du haver udført denne Dom.","Og jeg hørte Vandenes Engel sige: retfærdig er du Herre! du, som er og som var, du Hellige, at du haver udført denne Dom."],[16,6,"Fordi de have udøst Helliges og Propheters Blod, haver du og givet dem Blod at drikke; thi de ere det værd.","Fordi de have udøst Helliges og Propheters Blod, haver du og givet dem Blod at drikke; thi de ere det værd."],[16,7,"Og jeg hørte en Anden fra Alteret sige: ja Herre, Gud, du Almægtige! dine Domme ere sande og retfærdige.","Og jeg hørte en Anden fra Alteret sige: ja Herre, Gud, du Almægtige! dine Domme ere sande og retfærdige."],[16,8,"Og den fjerde Engel udgød sin Skaal i Solen; og den fik Magt at brænde Menneskene med Ild.","Og den fjerde Engel udgød sin Skaal i Solen; og den fik Magt at brænde Menneskene med Ild."],[16,9,"Og Menneskene brændte i stor Hede og bespottede Guds Navn, som haver Magt over disse Plager; og de omvendte sig ikke at give ham Ære.","Og Menneskene brændte i stor Hede og bespottede Guds Navn, som haver Magt over disse Plager; og de omvendte sig ikke at give ham Ære."],[16,10,"Og den femte Engel udgød sin Skaal paa Dyrets Throne; og dets Rige blev formørket, og de tyggede deres Tunger af Pine.","Og den femte Engel udgød sin Skaal paa Dyrets Throne; og dets Rige blev formørket, og de tyggede deres Tunger af Pine."],[16,11,"Og de bespottede Himmelens Gud for deres Piner og for deres Bylder; og de omvendte sig ikke fra deres Gjerninger.","Og de bespottede Himmelens Gud for deres Piner og for deres Bylder; og de omvendte sig ikke fra deres Gjerninger."],[16,12,"Og den sjette Engel udgød sin Skaal i den store Flod Euphrates; og dens Vand borttørredes, paa det Veien skulde beredes for Kongerne fra Østen.","Og den sjette Engel udgød sin Skaal i den store Flod Euphrates; og dens Vand borttørredes, paa det Veien skulde beredes for Kongerne fra Østen."],[16,13,"Og jeg saae af Dragens Mund og af Dyrets Mund og af den falske Prophets Mund udkomme tre urene Aander, som lignede Padder.","Og jeg saae af Dragens Mund og af Dyrets Mund og af den falske Prophets Mund udkomme tre urene Aander, som lignede Padder."],[16,14,"Thi de ere Djævelens Aander og gjøre Tegn; og de gaae ud til Jordens, ja hele Jorderiges Konger, at samle dem til Krigen paa Guds den Almægtiges hiin store Dag.","Thi de ere Djævelens Aander og gjøre Tegn; og de gaae ud til Jordens, ja hele Jorderiges Konger, at samle dem til Krigen paa Guds den Almægtiges hiin store Dag."],[16,15,"See, jeg kommer som en Tyv. Salig er den, som vaager og bevarer sine Klæder, at han ikke skal gaae nøgen, og de skulle see hans Skam.","See, jeg kommer som en Tyv. Salig er den, som vaager og bevarer sine Klæder, at han ikke skal gaae nøgen, og de skulle see hans Skam."],[16,16,"Og han forsamlede dem til det Sted, som kaldes paa Hebraisk Harmageddon.","Og han forsamlede dem til det Sted, som kaldes paa Hebraisk Harmageddon."],[16,17,"Og den syvende Engel udgød sin Skaal i Luften; og en stærk Røst udgik fra Templet i Himmelen, fra Thronen, som sagde: det er skeet.","Og den syvende Engel udgød sin Skaal i Luften; og en stærk Røst udgik fra Templet i Himmelen, fra Thronen, som sagde: det er skeet."],[16,18,"Og der skete Røster og Tordener og Lyn; og der skete et stort Jordskjælv, saadant som ikke er skeet fra den Tid, at Menneskene bleve til paa Jorden, et saadant Jordskjælv, saa stort.","Og der skete Røster og Tordener og Lyn; og der skete et stort Jordskjælv, saadant som ikke er skeet fra den Tid, at Menneskene bleve til paa Jorden, et saadant Jordskjælv, saa stort."],[16,19,"Og den store Stad blev til tre Dele, og Hedningernes Stæder nedfaldt; og den store Babylon blev ihukommet for Gud, at han vilde skjenke hende med Vinen af sin strenge Vrede.","Og den store Stad blev til tre Dele, og Hedningernes Stæder nedfaldt; og den store Babylon blev ihukommet for Gud, at han vilde skjenke hende med Vinen af sin strenge Vrede."],[16,20,"Og hver Ø flyede, og Bjergene blev ikke fundne.","Og hver Ø flyede, og Bjergene blev ikke fundne."],[16,21,"Og en stor Hagel, centnertung, faldt ned fra Himmelen paa Menneskene; og Menneskene bespottede Gud for Hagelens Plage, thi dens Plage er meget stor.","Og en stor Hagel, centnertung, faldt ned fra Himmelen paa Menneskene; og Menneskene bespottede Gud for Hagelens Plage, thi dens Plage er meget stor."],[17,1,"Een af de syv Engle, som havde de syv Skaaler, som og talede med mig og sagde til mig: kom, jeg vil vise dig Dommen over den store Skjøge, som sidder paa de mange Vande,","Een af de syv Engle, som havde de syv Skaaler, som og talede med mig og sagde til mig: kom, jeg vil vise dig Dommen over den store Skjøge, som sidder paa de mange Vande,"],[17,2,"med hvilken Kongerne paa Jorden have bolet, og de, som boe paa Jorden, ere blevne drukne af hendes Horeries Viin.","med hvilken Kongerne paa Jorden have bolet, og de, som boe paa Jorden, ere blevne drukne af hendes Horeries Viin."],[17,3,"Og han førte mig i Aanden hen i Ørken, og jeg saae en Kvinde, som sad paa et skarlagenfarvet Dyr, fuldt med Bespottelsens Navne, som havde syv Hoveder og ti Horn.","Og han førte mig i Aanden hen i Ørken, og jeg saae en Kvinde, som sad paa et skarlagenfarvet Dyr, fuldt med Bespottelsens Navne, som havde syv Hoveder og ti Horn."],[17,4,"Og Kvinden var klædt i Purpur og Skarlagen og udziret med Guld og med Ædelstene og Perler; hun havde et Guldbæger i sin Haand, fuldt af Verderstyggeligheder og hendes Horeries Ureenhed.","Og Kvinden var klædt i Purpur og Skarlagen og udziret med Guld og med Ædelstene og Perler; hun havde et Guldbæger i sin Haand, fuldt af Verderstyggeligheder og hendes Horeries Ureenhed."],[17,5,"Og paa hendes Pande var skrevet et Navn: Hemmelighed! Babylon den store, en Moder til Skjøger og al Vederstyggelighed paa Jorden.","Og paa hendes Pande var skrevet et Navn: Hemmelighed! Babylon den store, en Moder til Skjøger og al Vederstyggelighed paa Jorden."],[17,6,"Og jeg saae Kvinden drukken af de Helliges Blod og af Jesu Vidners Blod; og jeg forundrede mig, der jeg saae hende, med en stor Forundring.","Og jeg saae Kvinden drukken af de Helliges Blod og af Jesu Vidners Blod; og jeg forundrede mig, der jeg saae hende, med en stor Forundring."],[17,7,"Og Engelen sagde til mig: hvi forundrede du dig? Jeg vil sige dig den Kvindes Hemmelighed og Dyrets, som bærer hende, som haver de syv Hoveder og de ti Horn.","Og Engelen sagde til mig: hvi forundrede du dig? Jeg vil sige dig den Kvindes Hemmelighed og Dyrets, som bærer hende, som haver de syv Hoveder og de ti Horn."],[17,8,"Det Dyr, som du saae, haver været og er ikke, og skal opstige af Afgrunden og fare bort til Fordærvelse; og de skulle forundre sig, som boe paa Jorden, de, hvis Navne ikke ere skrevne i Livsens Bog, fra Verdens Grundvold blev lagt, naar de see Dyret, som var og ikke, enddog det er.","Det Dyr, som du saae, haver været og er ikke, og skal opstige af Afgrunden og fare bort til Fordærvelse; og de skulle forundre sig, som boe paa Jorden, de, hvis Navne ikke ere skrevne i Livsens Bog, fra Verdens Grundvold blev lagt, naar de see Dyret, som var og ikke, enddog det er."],[17,9,"Her behøves et Sind, som haver Viisdom. De syv Hoveder ere syv Bjerge, paa hvilke Kvinden sidder.","Her behøves et Sind, som haver Viisdom. De syv Hoveder ere syv Bjerge, paa hvilke Kvinden sidder."],[17,10,"Ogsaa Kongerne ere syv; de fem ere faldne, og den ene er der, den anden er ikke endnu kommet, og naar han kommer, bør det ham at blive en liden Tid.","Ogsaa Kongerne ere syv; de fem ere faldne, og den ene er der, den anden er ikke endnu kommet, og naar han kommer, bør det ham at blive en liden Tid."],[17,11,"Og Dyret, som var og er ikke, er end selv den ottende, og er af de syv og farer bort til Fordærvelse.","Og Dyret, som var og er ikke, er end selv den ottende, og er af de syv og farer bort til Fordærvelse."],[17,12,"Og de to Horn, som du saae, ere ti Konger, hvilke ikke endnu have annammet Riget, men annamme en Magt som Konger een Time med Dyret.","Og de to Horn, som du saae, ere ti Konger, hvilke ikke endnu have annammet Riget, men annamme en Magt som Konger een Time med Dyret."],[17,13,"Disse have een Mening, og deres Magt og Myndig skulle de overgive Dyret.","Disse have een Mening, og deres Magt og Myndig skulle de overgive Dyret."],[17,14,"Disse skulle stride med Lammet, og Lammet skal overvinde dem, fordi det er Herrers Herre og Kongers Konge, og de, som ere med det, de Kaldte og Udvalgte og Trofaste.","Disse skulle stride med Lammet, og Lammet skal overvinde dem, fordi det er Herrers Herre og Kongers Konge, og de, som ere med det, de Kaldte og Udvalgte og Trofaste."],[17,15,"Og han sagde til mig: de Vande, som du saae, der hvor Skjøgen sidder, ere Folk og Skarer og Slægter og Tungemaal.","Og han sagde til mig: de Vande, som du saae, der hvor Skjøgen sidder, ere Folk og Skarer og Slægter og Tungemaal."],[17,16,"Og de ti Horn, som du saae paa Dyret, disse skulle hade Skjøgen og gjøre hende øde og nøgen, og æde hendes Kjød og opbrænde hende med Ild.","Og de ti Horn, som du saae paa Dyret, disse skulle hade Skjøgen og gjøre hende øde og nøgen, og æde hendes Kjød og opbrænde hende med Ild."],[17,17,"Thi Gud haver givet dem i Hjertet at gjøre efter hans Sind, og at have eet Sind og at give Dyret deres Rige, indtil Guds Ord blive fuldbyrdede.","Thi Gud haver givet dem i Hjertet at gjøre efter hans Sind, og at have eet Sind og at give Dyret deres Rige, indtil Guds Ord blive fuldbyrdede."],[17,18,"Og Kvinden, som du saae, er den store Stad, som haver Herredømme over Jordens Konger.","Og Kvinden, som du saae, er den store Stad, som haver Herredømme over Jordens Konger."],[18,1,"Og derefter saae jeg en Engel fare ned fra Himmelen, som havde stor Magt, og Jorden oplystes af hans Glands.","Og derefter saae jeg en Engel fare ned fra Himmelen, som havde stor Magt, og Jorden oplystes af hans Glands."],[18,2,"Og han raabte med Styrke, med høi Røst, og sagde: den er falden, den er falden, Babylon den store, og er bleven Djævlenes Bolig og et Fængsel for alle urene Aander, og et Fængsel for alle urene og afskyede Fugle!","Og han raabte med Styrke, med høi Røst, og sagde: den er falden, den er falden, Babylon den store, og er bleven Djævlenes Bolig og et Fængsel for alle urene Aander, og et Fængsel for alle urene og afskyede Fugle!"],[18,3,"Thi af hendes Horeries giftige Viin have alle Folkeslag drukket, og Jordens Konger have bolet med hende, og Jordens Kjøbmænd ere blevne rige af hendes Yppigheds Fylde.","Thi af hendes Horeries giftige Viin have alle Folkeslag drukket, og Jordens Konger have bolet med hende, og Jordens Kjøbmænd ere blevne rige af hendes Yppigheds Fylde."],[18,4,"Og jeg hørte en anden Røst fra Himmelen, som sagde: gaaer bort fra hende, I mit Folk! at I ikke skulle blive deelagtige i hendes Synder, og at I ikke skulle rammes af hendes Plager.","Og jeg hørte en anden Røst fra Himmelen, som sagde: gaaer bort fra hende, I mit Folk! at I ikke skulle blive deelagtige i hendes Synder, og at I ikke skulle rammes af hendes Plager."],[18,5,"Thi hendes Synder naae indtil Himmelen, og Gud haver kommet hendes Uretfærdigheder ihu.","Thi hendes Synder naae indtil Himmelen, og Gud haver kommet hendes Uretfærdigheder ihu."],[18,6,"Betaler hende, som hun haver betalt Eder, og gjengjelder hende dobbelt efter hendes Gjerninger: og skjenker hende dobbelt i den Kalk, som hun haver skjenket med.","Betaler hende, som hun haver betalt Eder, og gjengjelder hende dobbelt efter hendes Gjerninger: og skjenker hende dobbelt i den Kalk, som hun haver skjenket med."],[18,7,"Saa meget som hun haver ophøiet sig selv og levet i Yppighed, saa meget giver hende af Pine og Sorrig. Fordi hun siger i sit Hjerte: jeg sidder som Dronning og er ikke Enke, og Sorrig skal jeg ingenlunde see,","Saa meget som hun haver ophøiet sig selv og levet i Yppighed, saa meget giver hende af Pine og Sorrig. Fordi hun siger i sit Hjerte: jeg sidder som Dronning og er ikke Enke, og Sorrig skal jeg ingenlunde see,"],[18,8,"derfor skulle hendes Plager komme paa een Dag: Død og Sorrig og Hunger, og hun skal opbrændes med Ild; thi stærk er den Herre Gud, som dømmer hende.","derfor skulle hendes Plager komme paa een Dag: Død og Sorrig og Hunger, og hun skal opbrændes med Ild; thi stærk er den Herre Gud, som dømmer hende."],[18,9,"Og Jordens Konger skulle begræde hende og hyle over hende, de, som have bolet og drevet Vellyst med hende, naar de see Røgen af hendes Brand,","Og Jordens Konger skulle begræde hende og hyle over hende, de, som have bolet og drevet Vellyst med hende, naar de see Røgen af hendes Brand,"],[18,10,"staaende langt borte af Frygt for hendes Piinsel, og sigende: vee! vee! du store Stad, Babylon, du stærke Stad; thi paa een Time er din Dom kommen.","staaende langt borte af Frygt for hendes Piinsel, og sigende: vee! vee! du store Stad, Babylon, du stærke Stad; thi paa een Time er din Dom kommen."],[18,11,"Og Jordens Kjøbmænd skulle græde og sørge over hende, fordi Ingen mere kjøber deres Ladning:","Og Jordens Kjøbmænd skulle græde og sørge over hende, fordi Ingen mere kjøber deres Ladning:"],[18,12,"Ladning af Guld og Sølv og dyrebare Stene og Perler og kosteligt Linklæde og Purpur og Silke og Skarlagen og allehaande vellugtende Træ og allehaande Arbeide af Elfenbeen og allehaande Arbeide af kosteligt Træ og af Kobber og Jern og Marmor","Ladning af Guld og Sølv og dyrebare Stene og Perler og kosteligt Linklæde og Purpur og Silke og Skarlagen og allehaande vellugtende Træ og allehaande Arbeide af Elfenbeen og allehaande Arbeide af kosteligt Træ og af Kobber og Jern og Marmor"],[18,13,"og Kaneelbark og Røgelser og Salve og Virak og Viin og Olie og fiint Meel og Hvede og Øxne og Faar og Heste og Vogne og Slaver, ja Menneskesjæle.","og Kaneelbark og Røgelser og Salve og Virak og Viin og Olie og fiint Meel og Hvede og Øxne og Faar og Heste og Vogne og Slaver, ja Menneskesjæle."],[18,14,"Og Frugten, din Sjæl lystedes ved, er vegen fra dig, og alt det Lækkre og Glindsende er veget fra dig, og du skal ingenlunde finde det mere.","Og Frugten, din Sjæl lystedes ved, er vegen fra dig, og alt det Lækkre og Glindsende er veget fra dig, og du skal ingenlunde finde det mere."],[18,15,"De, som handlede dermed, som ere blevne rige ved hende, skulle staae langt borte af Frygt for hendes Piinsel, og græde og sørge, sigende:","De, som handlede dermed, som ere blevne rige ved hende, skulle staae langt borte af Frygt for hendes Piinsel, og græde og sørge, sigende:"],[18,16,"vee! vee! den store Stad, som var klædt i kosteligt Linklæde og Purpur og Skarlagen, og udziret med Guld og Ædelstene og Perler; thi i een Time er saa stor Rigdom gaaet tilgrunde.","vee! vee! den store Stad, som var klædt i kosteligt Linklæde og Purpur og Skarlagen, og udziret med Guld og Ædelstene og Perler; thi i een Time er saa stor Rigdom gaaet tilgrunde."],[18,17,"Og alle Styrmænd og den hele Hob paa Skibene og Søfolkene og Alle, som befare Havet, stode langt borte,","Og alle Styrmænd og den hele Hob paa Skibene og Søfolkene og Alle, som befare Havet, stode langt borte,"],[18,18,"og raabte, der de saae Røgen af hendes Brand, og sagde: hvo var lig den store Stad?","og raabte, der de saae Røgen af hendes Brand, og sagde: hvo var lig den store Stad?"],[18,19,"Og de kastede Støv paa deres Hoveder, grædende og sørgende, og sagde: vee! vee! den store Stad i hvilken Alle, som havde Skibe paa Havet, berigedes af dens Pragt! thi i een Time er den gaaet tilgrunde.","Og de kastede Støv paa deres Hoveder, grædende og sørgende, og sagde: vee! vee! den store Stad i hvilken Alle, som havde Skibe paa Havet, berigedes af dens Pragt! thi i een Time er den gaaet tilgrunde."],[18,20,"Fryd dig over den, du Himmel, og I hellige Apostler og Propheter! fordi Gud haver udført Eders Ret imod den.","Fryd dig over den, du Himmel, og I hellige Apostler og Propheter! fordi Gud haver udført Eders Ret imod den."],[18,21,"Og en vældig Engel opløftede en Steen som en stor Møllesteen, og kastede den i Havet og sagde: saa skal Babylon, den store Stad nedkastes med Hast og ikke findes mere.","Og en vældig Engel opløftede en Steen som en stor Møllesteen, og kastede den i Havet og sagde: saa skal Babylon, den store Stad nedkastes med Hast og ikke findes mere."],[18,22,"Og Harpelegeres og Sangeres og Fløiters og Basuners Lyd skal ikke høres i dig mere; og ikke nogen Kunstner i nogen Kunst findes i dig mere; og Møllens Lyd ikke høres i dig mere;","Og Harpelegeres og Sangeres og Fløiters og Basuners Lyd skal ikke høres i dig mere; og ikke nogen Kunstner i nogen Kunst findes i dig mere; og Møllens Lyd ikke høres i dig mere;"],[18,23,"og Lampens Lys skal ikke skinne i dig mere; og Brudgoms og Bruds Røst ikke høres i dig mere, fordi dine Kjøbmænd vare Fyrster paa Jorden, fordi ved din Trolddom ere alle Folkene bedaarede.","og Lampens Lys skal ikke skinne i dig mere; og Brudgoms og Bruds Røst ikke høres i dig mere, fordi dine Kjøbmænd vare Fyrster paa Jorden, fordi ved din Trolddom ere alle Folkene bedaarede."],[18,24,"Og i den er Propheters og Helliges Blod fundet alle deres, som ere myrdede paa Jorden.","Og i den er Propheters og Helliges Blod fundet alle deres, som ere myrdede paa Jorden."],[19,1,"Og derefter hørte jeg en høi Røst af en stor Skare i Himmelen, som sagde: Halleluja! Saliggjørelse og Ære og Priis og Magt være Herren vor Gud!","Og derefter hørte jeg en høi Røst af en stor Skare i Himmelen, som sagde: Halleluja! Saliggjørelse og Ære og Priis og Magt være Herren vor Gud!"],[19,2,"Thi sande og retfærdige ere hans Domme, at han haver dømt den store Skjøge, som fordærvede Jorden med sit Horeri, og at han haver krævet sine Tjeneres Blod af hendes Haand.","Thi sande og retfærdige ere hans Domme, at han haver dømt den store Skjøge, som fordærvede Jorden med sit Horeri, og at han haver krævet sine Tjeneres Blod af hendes Haand."],[19,3,"Og de sagde anden Gang: Halleluja! og hendes Røg opstiger i al Evighed.","Og de sagde anden Gang: Halleluja! og hendes Røg opstiger i al Evighed."],[19,4,"Og de fire og tyve Ældste og de fire Dyr faldt ned og tilbade Gud, som sad paa Thronen, og sagde: Amen! Halleluja!","Og de fire og tyve Ældste og de fire Dyr faldt ned og tilbade Gud, som sad paa Thronen, og sagde: Amen! Halleluja!"],[19,5,"Og en Røst udgik fra Thronen, som sagde: lover vor Gud, alle hans Tjenere, og I, som ham frygte, baade de Smaa og de Store!","Og en Røst udgik fra Thronen, som sagde: lover vor Gud, alle hans Tjenere, og I, som ham frygte, baade de Smaa og de Store!"],[19,6,"Og jeg hørte som en stor Skares Røst og som mange Vandes Lyd og som stærke Tordeners Lyd, som sagde: Halleluja! fordi Herren, Gud, den Almægtige, haver antaget Riget.","Og jeg hørte som en stor Skares Røst og som mange Vandes Lyd og som stærke Tordeners Lyd, som sagde: Halleluja! fordi Herren, Gud, den Almægtige, haver antaget Riget."],[19,7,"Lader os glæde og fryde os og give ham Æren; thi Lammets Bryllup er kommet, og hans Brud haver smykket sig.","Lader os glæde og fryde os og give ham Æren; thi Lammets Bryllup er kommet, og hans Brud haver smykket sig."],[19,8,"Og det blev hende givet at føre sig i reent og skinnende Linklæde; thi Linklædet er de Helliges Dyder.","Og det blev hende givet at føre sig i reent og skinnende Linklæde; thi Linklædet er de Helliges Dyder."],[19,9,"Og han siger til mig: skriv: salige ere de, som ere kaldede til Lammets Bryllups Nadvere! Og han siger til mig: disse ere de sande Guds Ord.","Og han siger til mig: skriv: salige ere de, som ere kaldede til Lammets Bryllups Nadvere! Og han siger til mig: disse ere de sande Guds Ord."],[19,10,"Og jeg faldt ned for hans Fødder at tilbede ham, og han siger til mig: gjør det ikke! Jeg er din Medtjener og dine Brødres, som have Jesu Vidnesbyrd ; tilbed Gud; thi Jesu Vidnesbyrd er Prophetiens Aand.","Og jeg faldt ned for hans Fødder at tilbede ham, og han siger til mig: gjør det ikke! Jeg er din Medtjener og dine Brødres, som have Jesu Vidnesbyrd ; tilbed Gud; thi Jesu Vidnesbyrd er Prophetiens Aand."],[19,11,"Og jeg saae Himmelen opladt, og see, en hvid Hest, og den, der sad paa den, kaldes Sanddru og Trofast, og han dømmer og strider med Retfærdighed.","Og jeg saae Himmelen opladt, og see, en hvid Hest, og den, der sad paa den, kaldes Sanddru og Trofast, og han dømmer og strider med Retfærdighed."],[19,12,"Men hans Øine vare som Ildslue, og der vare mange Kroner paa hans Hoved; han havde et Navn skrevet, hvilket Ingen kjender, uden han selv;","Men hans Øine vare som Ildslue, og der vare mange Kroner paa hans Hoved; han havde et Navn skrevet, hvilket Ingen kjender, uden han selv;"],[19,13,"og han var iført et Klæde, dyppet i Blod, og hans Navn kaldes: Guds Ord.","og han var iført et Klæde, dyppet i Blod, og hans Navn kaldes: Guds Ord."],[19,14,"Og hærene i Himmelen fulgte ham paa hvide Heste, iførte hvidt og reent Linklæde.","Og hærene i Himmelen fulgte ham paa hvide Heste, iførte hvidt og reent Linklæde."],[19,15,"Og af hans Mund udgik et skarpt Sværd, at han med det skulde slaae Hedningerne; og han skal regjere dem med et Jernspiir, og han skal træde Guds, de Almægtiges, Vredes og Fortørnelses Viins Persekar.","Og af hans Mund udgik et skarpt Sværd, at han med det skulde slaae Hedningerne; og han skal regjere dem med et Jernspiir, og han skal træde Guds, de Almægtiges, Vredes og Fortørnelses Viins Persekar."],[19,16,"Og han haver et Navn skrevet paa Klædebonnet paa sin Lænd: Kongers Konge og Herrers Herre.","Og han haver et Navn skrevet paa Klædebonnet paa sin Lænd: Kongers Konge og Herrers Herre."],[19,17,"Og jeg saae en Engel staaende i Solen, og han raabte med høi Røst og sagde til alle Fugle, som flyve midt under Himmelen: kommer og forsamles til den store Guds Nadvere,","Og jeg saae en Engel staaende i Solen, og han raabte med høi Røst og sagde til alle Fugle, som flyve midt under Himmelen: kommer og forsamles til den store Guds Nadvere,"],[19,18,"for at æde Kongers Kjød og Krigshøvdingers Kjød og Vældiges Kjød og Kjødet af Heste og af dem, som sidde paa dem, og Kjødet af Alle, Frie og Trælle, og Smaa og Store.","for at æde Kongers Kjød og Krigshøvdingers Kjød og Vældiges Kjød og Kjødet af Heste og af dem, som sidde paa dem, og Kjødet af Alle, Frie og Trælle, og Smaa og Store."],[19,19,"Og jeg saae Dyret og Kongerne paa Jorden og deres Hære forsamlede, at føre Krig imod den, som sad paa Hesten og imod hans Hær.","Og jeg saae Dyret og Kongerne paa Jorden og deres Hære forsamlede, at føre Krig imod den, som sad paa Hesten og imod hans Hær."],[19,20,"Og Dyret blev grebet og med det den falske Prophet, som havde gjort Tegnene for dets Aasyn, med hvilke han havde forført dem, som toge Dyrets Mærke, og dem, som tilbade dets Billede; disse To bleve levende kastede i Ildsøen, som brænder med Svovl.","Og Dyret blev grebet og med det den falske Prophet, som havde gjort Tegnene for dets Aasyn, med hvilke han havde forført dem, som toge Dyrets Mærke, og dem, som tilbade dets Billede; disse To bleve levende kastede i Ildsøen, som brænder med Svovl."],[19,21,"Og de Andre bleve ihjelslagne med hans Sværd, som sad paa Hesten, hvilken udgik af hans Mund, og alle Fugle blev mættede af deres Kjød.","Og de Andre bleve ihjelslagne med hans Sværd, som sad paa Hesten, hvilken udgik af hans Mund, og alle Fugle blev mættede af deres Kjød."],[20,1,"Og jeg saae en Engel fare ned fra Himmelen; han havde Afgrundens Nøgle og en stor Lænke i sin Haand.","Og jeg saae en Engel fare ned fra Himmelen; han havde Afgrundens Nøgle og en stor Lænke i sin Haand."],[20,2,"Og han greb Dragen, den gamle Slange, som er Djævelen og Satanas, og bandt ham for tusinde Aar","Og han greb Dragen, den gamle Slange, som er Djævelen og Satanas, og bandt ham for tusinde Aar"],[20,3,"og kastede ham i Afgrunden og tillukkede og forseglede over ham, at han ikke mere skulde forføre Folkene, indtil de tusinde Aar fuldendtes; og efter dem bør det ham at løses en liden Tid.","og kastede ham i Afgrunden og tillukkede og forseglede over ham, at han ikke mere skulde forføre Folkene, indtil de tusinde Aar fuldendtes; og efter dem bør det ham at løses en liden Tid."],[20,4,"Og jeg saae Throner, og de satte sig paa dem, og Dom blev dem given; og jeg saae deres Sjæle, som vare halshugne for Jesu Vidnesbyrds og for Guds Ords Skyld, og dem, som ikke havde tilbedet Dyret, ei heller dets Billede, og ikke havde taget Mærket i deres Pande og paa deres Haand; og de bleve levende og regjerede med Christus de tusinde Aar.","Og jeg saae Throner, og de satte sig paa dem, og Dom blev dem given; og jeg saae deres Sjæle, som vare halshugne for Jesu Vidnesbyrds og for Guds Ords Skyld, og dem, som ikke havde tilbedet Dyret, ei heller dets Billede, og ikke havde taget Mærket i deres Pande og paa deres Haand; og de bleve levende og regjerede med Christus de tusinde Aar."],[20,5,"Men de andre Døde bleve ikke levende igjen, indtil de tusinde Aar fuldendtes. Denne er den første Opstandelse.","Men de andre Døde bleve ikke levende igjen, indtil de tusinde Aar fuldendtes. Denne er den første Opstandelse."],[20,6,"Salig og hellig er den, som haver Deel i den første Opstandelse; over disse haver den anden Død ikke Magt, men de skulle være Guds og Christi Præster og skulle regjere med ham tusinde Aar.","Salig og hellig er den, som haver Deel i den første Opstandelse; over disse haver den anden Død ikke Magt, men de skulle være Guds og Christi Præster og skulle regjere med ham tusinde Aar."],[20,7,"Og naar de tusinde Aar ere fuldendte, skal Satanas løses af sit Fængsel.","Og naar de tusinde Aar ere fuldendte, skal Satanas løses af sit Fængsel."],[20,8,"Og han skal udgaae at forføre Folkene fra Jordens fire Hjørner, Gog og Magog, at forsamle dem til Strid; deres Tal er om Havets Sand.","Og han skal udgaae at forføre Folkene fra Jordens fire Hjørner, Gog og Magog, at forsamle dem til Strid; deres Tal er om Havets Sand."],[20,9,"Og de droge frem over Jordens Flade og omringede de Helliges Leir og den elskede Stad. Og Ild nedfaldt af Himmelen fra Gud, og fortærede dem.","Og de droge frem over Jordens Flade og omringede de Helliges Leir og den elskede Stad. Og Ild nedfaldt af Himmelen fra Gud, og fortærede dem."],[20,10,"Og Djævelen, som dem forførte, blev kastet i Søen af Ild og Svovl, hvor Dyret og den falske Prophet var; og de skulle pines Dag og Nat i al Evighed.","Og Djævelen, som dem forførte, blev kastet i Søen af Ild og Svovl, hvor Dyret og den falske Prophet var; og de skulle pines Dag og Nat i al Evighed."],[20,11,"Og jeg saae en stor hvid Throne og ham, som sad derpaa, for hvis Aasyn Jorden og Himmelen flyede; og der blev ikke fundet Sted for dem.","Og jeg saae en stor hvid Throne og ham, som sad derpaa, for hvis Aasyn Jorden og Himmelen flyede; og der blev ikke fundet Sted for dem."],[20,12,"Og jeg saae de Døde, Smaa og Store, staaende for Gud, og Bøgerne bleve opladte; og en anden Bog blev opladt, som er Livsens Bog; og de Døde bleve dømte efter det, som er skrevet i Bøgerne efter deres Gjerninger.","Og jeg saae de Døde, Smaa og Store, staaende for Gud, og Bøgerne bleve opladte; og en anden Bog blev opladt, som er Livsens Bog; og de Døde bleve dømte efter det, som er skrevet i Bøgerne efter deres Gjerninger."],[20,13,"Og Havet afgav de Døde, som vare i det; og Døden og Helvede afgave de Døde, som var i dem, og de bleve dømte, hver efter sine Gjerninger.","Og Havet afgav de Døde, som vare i det; og Døden og Helvede afgave de Døde, som var i dem, og de bleve dømte, hver efter sine Gjerninger."],[20,14,"Og Døden og Helvede bleve kastede i Ildsøen. Denne er den anden Død.","Og Døden og Helvede bleve kastede i Ildsøen. Denne er den anden Død."],[20,15,"Og dersom nogen ikke fandtes skreven i Livsens Bog, blev han kastet i Ildsøen.","Og dersom nogen ikke fandtes skreven i Livsens Bog, blev han kastet i Ildsøen."],[21,1,"Og jeg saae en ny Himmel og en ny Jord; thi de første Himmel og den første Jord var forgaaet, og Havet var ikke mere.","Og jeg saae en ny Himmel og en ny Jord; thi de første Himmel og den første Jord var forgaaet, og Havet var ikke mere."],[21,2,"Og jeg, Johannes, saae den hellige Stad, det nye Jerusalem, at stige ned af Himmelen fra Gud, beredet som Bruden, smykket for sin Brudgom.","Og jeg, Johannes, saae den hellige Stad, det nye Jerusalem, at stige ned af Himmelen fra Gud, beredet som Bruden, smykket for sin Brudgom."],[21,3,"Og jeg hørte en høi Røst fra Himmelen, som sagde: see, Guds Paulun er hos Menneskene, og han skal boe hos dem, og de skulle være hans Folk, og Gud selv skal være med dem og være deres Gud.","Og jeg hørte en høi Røst fra Himmelen, som sagde: see, Guds Paulun er hos Menneskene, og han skal boe hos dem, og de skulle være hans Folk, og Gud selv skal være med dem og være deres Gud."],[21,4,"Og Gud skal aftørre hver Taare af deres Øine, og Døden skal ikke være mere, ei heller Sorrig, ei heller Skrig, ei heller Pine skal være mere; thi det Første er veget bort.","Og Gud skal aftørre hver Taare af deres Øine, og Døden skal ikke være mere, ei heller Sorrig, ei heller Skrig, ei heller Pine skal være mere; thi det Første er veget bort."],[21,5,"Og den som sad paa Thronen, sagde: see, jeg gjør alle Ting nye. Og han siger til mig: skriv; thi disse Ord ere sande og trofaste.","Og den som sad paa Thronen, sagde: see, jeg gjør alle Ting nye. Og han siger til mig: skriv; thi disse Ord ere sande og trofaste."],[21,6,"Og han sagde til mig: det er skeet. Jeg er Alpha og Omega, Begyndelsen og Enden. Den Tørstige vil jeg give af Livsens Vands Kilde uforskyldt.","Og han sagde til mig: det er skeet. Jeg er Alpha og Omega, Begyndelsen og Enden. Den Tørstige vil jeg give af Livsens Vands Kilde uforskyldt."],[21,7,"Den, som seirer, skal arve alle Ting, og jeg vil være ham en Gud, og han skal være mig en Søn.","Den, som seirer, skal arve alle Ting, og jeg vil være ham en Gud, og han skal være mig en Søn."],[21,8,"Men de Feige og Vantroe og Vederstyggelige og Manddrabere og Skjørlevnere og Troldkarle og Afgudsdyrkere og alle Løgnere, deres Deel skal være i Søen, som brænder med Ild og Svovl; dette er den anden Død.","Men de Feige og Vantroe og Vederstyggelige og Manddrabere og Skjørlevnere og Troldkarle og Afgudsdyrkere og alle Løgnere, deres Deel skal være i Søen, som brænder med Ild og Svovl; dette er den anden Død."],[21,9,"Og een af de syv Engle, som havde de syv Skaaler fulde af de syv sidste Plager, kom til mig og talede med mig og sagde: kom, jeg vil vise dig Bruden, Lammets Hustru.","Og een af de syv Engle, som havde de syv Skaaler fulde af de syv sidste Plager, kom til mig og talede med mig og sagde: kom, jeg vil vise dig Bruden, Lammets Hustru."],[21,10,"Og han førte mig i Aanden hen paa et stort og høit Bjerg og viste mig den store Stad, det hellige Jerusalem, som nedsteg af Himmelen fra Gud.","Og han førte mig i Aanden hen paa et stort og høit Bjerg og viste mig den store Stad, det hellige Jerusalem, som nedsteg af Himmelen fra Gud."],[21,11,"Den havde Guds Herlighed, og dens Glands var som den dyrebareste Steen, som krystalklar Jaspis.","Den havde Guds Herlighed, og dens Glands var som den dyrebareste Steen, som krystalklar Jaspis."],[21,12,"Den havde ogsaa en stor og høi Muur med tolv Porte, og over Portene tolv Engle og paaskrevne Navne, hvilke ere Israels Børns tolv Stammer;","Den havde ogsaa en stor og høi Muur med tolv Porte, og over Portene tolv Engle og paaskrevne Navne, hvilke ere Israels Børns tolv Stammer;"],[21,13,"mod Østen tre Porte, mod Norden tre Porte, mod Sønden tre Porte, mod Vesten tre Porte.","mod Østen tre Porte, mod Norden tre Porte, mod Sønden tre Porte, mod Vesten tre Porte."],[21,14,"Og Stadens Muur havde tolv Grundvolde, og paa dem Lammets tolv Apostlers Navne.","Og Stadens Muur havde tolv Grundvolde, og paa dem Lammets tolv Apostlers Navne."],[21,15,"Og den, som talede med mig, havde et Guldrør, at han skulde maale Staden og dens Porte og dens Muur.","Og den, som talede med mig, havde et Guldrør, at han skulde maale Staden og dens Porte og dens Muur."],[21,16,"Og Staden ligger i Fiirkant; dens Længde er saa stor som Breden. Og han maalte Staden med Røret: Tolv tusinde Stadier; og dens Høide svarer lige til dens Længde og Brede.","Og Staden ligger i Fiirkant; dens Længde er saa stor som Breden. Og han maalte Staden med Røret: Tolv tusinde Stadier; og dens Høide svarer lige til dens Længde og Brede."],[21,17,"Og han maalte dens Muur, hundrede fire og fyrretyve Alen, efter et Menneskes Maal, som Engelen brugte.","Og han maalte dens Muur, hundrede fire og fyrretyve Alen, efter et Menneskes Maal, som Engelen brugte."],[21,18,"Og dens Muur var fra Grunden opbygt af Jaspis, og Staden var reent Guld, lig det rene Glar.","Og dens Muur var fra Grunden opbygt af Jaspis, og Staden var reent Guld, lig det rene Glar."],[21,19,"Og Stadens Muurs Grundvolde vare prydede med allehaande dyrebare Stene; den første Grundvold var Jaspis, den anden Saphir, den tredie Chalcedon, den fjerde Smaragd,","Og Stadens Muurs Grundvolde vare prydede med allehaande dyrebare Stene; den første Grundvold var Jaspis, den anden Saphir, den tredie Chalcedon, den fjerde Smaragd,"],[21,20,"den femte Sardonyx, den sjette Sarder, den syvende Chrysolith, den ottende Beryl, den niende Topas, den tiende Chrysopras, den ellevte Hyacinth, den tolvte Amethyst.","den femte Sardonyx, den sjette Sarder, den syvende Chrysolith, den ottende Beryl, den niende Topas, den tiende Chrysopras, den ellevte Hyacinth, den tolvte Amethyst."],[21,21,"Og de tolv Porte vare Perler, enhver af Portene een Perle, og Stadens Gade var reent Guld, som et gjennemsigtigt Glar.","Og de tolv Porte vare Perler, enhver af Portene een Perle, og Stadens Gade var reent Guld, som et gjennemsigtigt Glar."],[21,22,"Og jeg saa intet Tempel i den; thi dens Tempel er Herren, Gud den Almægtige og Lammet.","Og jeg saa intet Tempel i den; thi dens Tempel er Herren, Gud den Almægtige og Lammet."],[21,23,"Og Staden behøver ikke Sol eller Maane til at skinne i den; thi Guds Herlighed oplyser den, og Lammet er dens Lys.","Og Staden behøver ikke Sol eller Maane til at skinne i den; thi Guds Herlighed oplyser den, og Lammet er dens Lys."],[21,24,"Og Folkeslagene af de Frelste skulle vandre i dens Lys, og Jordens Konger føre deres Glands og Herlighed til den.","Og Folkeslagene af de Frelste skulle vandre i dens Lys, og Jordens Konger føre deres Glands og Herlighed til den."],[21,25,"Dens Porte skulle ikke lukkes om Dagen, og Nat skal der ikke være.","Dens Porte skulle ikke lukkes om Dagen, og Nat skal der ikke være."],[21,26,"Og de skulle føre Folkenes Glands og Herlighed til den.","Og de skulle føre Folkenes Glands og Herlighed til den."],[21,27,"Og intet Ureent skal komme ind i den, ei heller Nogen, som øver Vederstyggelighed og Løgn; kun de, som ere skrevne i Lammets Livsens Bog.","Og intet Ureent skal komme ind i den, ei heller Nogen, som øver Vederstyggelighed og Løgn; kun de, som ere skrevne i Lammets Livsens Bog."],[22,1,"Og han viste mig Livsens Vands rene Flod, skinnende som Krystal, som udvælder fra Guds og Lammets Throne.","Og han viste mig Livsens Vands rene Flod, skinnende som Krystal, som udvælder fra Guds og Lammets Throne."],[22,2,"Midt i dens Gade og paa begge Sider af Floden voxte Livsens Træ, som bar tolv Gange Frugt og gav hver Maaned sin Frugt; og Bladene af Træet tjente til Folkenes Lægedom.","Midt i dens Gade og paa begge Sider af Floden voxte Livsens Træ, som bar tolv Gange Frugt og gav hver Maaned sin Frugt; og Bladene af Træet tjente til Folkenes Lægedom."],[22,3,"Og der skal ingen Forbandelse være mere; og Guds og Lammets Throne skal være i den, og hans Tjenere skulle tjene ham.","Og der skal ingen Forbandelse være mere; og Guds og Lammets Throne skal være i den, og hans Tjenere skulle tjene ham."],[22,4,"Og de skulle see hans Ansigt, og hans Navn skal være i deres Pander.","Og de skulle see hans Ansigt, og hans Navn skal være i deres Pander."],[22,5,"Og Nat skal der ikke være, og de behøve ikke Lys eller Solens Skin, fordi Gud Herren lyser for dem; og de skulle regjere i al Evighed.","Og Nat skal der ikke være, og de behøve ikke Lys eller Solens Skin, fordi Gud Herren lyser for dem; og de skulle regjere i al Evighed."],[22,6,"Og han sagde til mig: disse Ord ere trofaste og sande; og Herren, de hellige Propheters Gud, haver udsendt sin Engel at vise sine Tjenere, hvad snart bør skee.","Og han sagde til mig: disse Ord ere trofaste og sande; og Herren, de hellige Propheters Gud, haver udsendt sin Engel at vise sine Tjenere, hvad snart bør skee."],[22,7,"See, jeg kommer snart. Salig er den, som bevarer denne Bogs Propheties Ord!","See, jeg kommer snart. Salig er den, som bevarer denne Bogs Propheties Ord!"],[22,8,"Og jeg, Johannes, er den, som saae og hørte disse Ting, og der jeg havde hørt og seet, faldt jeg ned at tilbede for Engelens Fødder, som viste mig disse Ting.","Og jeg, Johannes, er den, som saae og hørte disse Ting, og der jeg havde hørt og seet, faldt jeg ned at tilbede for Engelens Fødder, som viste mig disse Ting."],[22,9,"Og han siger til mig: gjør det ikke; thi jeg er din Medtjener og dine Brødres, Propheternes, og deres, som bevare denne Bogs Ord; tilbed Gud!","Og han siger til mig: gjør det ikke; thi jeg er din Medtjener og dine Brødres, Propheternes, og deres, som bevare denne Bogs Ord; tilbed Gud!"],[22,10,"Og han siger til mig: du skal ikke forsegle denne Bogs Propheties Ord, thi Tiden er nær.","Og han siger til mig: du skal ikke forsegle denne Bogs Propheties Ord, thi Tiden er nær."],[22,11,"Lad den, som gjør Uret, fremdeles gjøre Uret, og den Uteerlige fremdeles øve Uteerlighed, og den Retfærdige fremdeles blive retfærdig, og den Hellige fremdeles blive helliget.","Lad den, som gjør Uret, fremdeles gjøre Uret, og den Uteerlige fremdeles øve Uteerlighed, og den Retfærdige fremdeles blive retfærdig, og den Hellige fremdeles blive helliget."],[22,12,"Og see, jeg kommer snart, og min Løn er med mig til at betale Hver, som hans Gjerning monne være.","Og see, jeg kommer snart, og min Løn er med mig til at betale Hver, som hans Gjerning monne være."],[22,13,"Jeg er Alpha og Omega, Begyndelse og Ende, den Første og den Sidste.","Jeg er Alpha og Omega, Begyndelse og Ende, den Første og den Sidste."],[22,14,"Salige ere de, som gjøre hans Befalinger, paa det de maa faae Adgang til Livsens Træ og indgaae igjennem Portene i Staden.","Salige ere de, som gjøre hans Befalinger, paa det de maa faae Adgang til Livsens Træ og indgaae igjennem Portene i Staden."],[22,15,"Men udenfor ere Hundene og Troldkarlene og Skjørlevnerne og Manddraberne og Afgudsdyrkerne og hver, som elsker og øver Løgn.","Men udenfor ere Hundene og Troldkarlene og Skjørlevnerne og Manddraberne og Afgudsdyrkerne og hver, som elsker og øver Løgn."],[22,16,"Jeg, Jesus, haver udsendt min Engel at vidne disse Ting for Eder i Menighederne; jeg er den af Davids Rod og Slægt, den skinnende Morgenstjerne.","Jeg, Jesus, haver udsendt min Engel at vidne disse Ting for Eder i Menighederne; jeg er den af Davids Rod og Slægt, den skinnende Morgenstjerne."],[22,17,"Og Aanden og Bruden sige: kom! Og hvo som hører, sige: kom! Og hvo som tørster, komme, og hvo som vil tage Livsens Vand uforskyldt!","Og Aanden og Bruden sige: kom! Og hvo som hører, sige: kom! Og hvo som tørster, komme, og hvo som vil tage Livsens Vand uforskyldt!"],[22,18,"Thi jeg vidner for hver, som hører denne Bogs Propheties Ord: dersom Nogen lægger Noget til disse Ting, da skal Gud lægge paa ham de Plager, som ere skrevne i denne Bog.","Thi jeg vidner for hver, som hører denne Bogs Propheties Ord: dersom Nogen lægger Noget til disse Ting, da skal Gud lægge paa ham de Plager, som ere skrevne i denne Bog."],[22,19,"Og dersom Nogen tager Noget bort fra denne Propheties Bogs Ord, da skal Gud borttage hans Deel af Livsens Bog og af den hellige Stad og fra de Ting, som ere skrevne i denne Bog.","Og dersom Nogen tager Noget bort fra denne Propheties Bogs Ord, da skal Gud borttage hans Deel af Livsens Bog og af den hellige Stad og fra de Ting, som ere skrevne i denne Bog."],[22,20,"Han, som vidner disse Ting, siger: ja, jeg kommer snart! Amen. Ja, kom, Herre Jesus!","Han, som vidner disse Ting, siger: ja, jeg kommer snart! Amen. Ja, kom, Herre Jesus!"],[22,21,"Vor Herres Jesu Christi Naade være med Eder alle! Amen.","Vor Herres Jesu Christi Naade være med Eder alle! Amen."]],"epo-londona":[[1,1,"Apokalipso de Jesuo Kristo, kiun Dio donis al li, por montri al siaj servistoj tion, kio devas baldaŭ okazi; kaj Li sendis kaj montris ĝin per Sia anĝelo al Sia servisto Johano,","Apokalipso de Jesuo Kristo, kiun Dio donis al li, por montri al siaj servistoj tion, kio devas baldaŭ okazi; kaj Li sendis kaj montris ĝin per Sia anĝelo al Sia servisto Johano,"],[1,2,"kiu atestis la vorton de Dio kaj la ateston de Jesuo Kristo, pri ĉio, kion li vidis.","kiu atestis la vorton de Dio kaj la ateston de Jesuo Kristo, pri ĉio, kion li vidis."],[1,3,"Feliĉaj estas la leganto kaj la aŭskultantoj de la vortoj de la profetaĵo kaj la observantoj de la skribitaĵoj en ĝi; ĉar la tempo estas proksima.","Feliĉaj estas la leganto kaj la aŭskultantoj de la vortoj de la profetaĵo kaj la observantoj de la skribitaĵoj en ĝi; ĉar la tempo estas proksima."],[1,4,"Johano al la sep eklezioj en Azio: Graco al vi kaj paco de Tiu, kiu estas kaj estis kaj venos; kaj de la sep spiritoj antaŭ Lia trono;","Johano al la sep eklezioj en Azio: Graco al vi kaj paco de Tiu, kiu estas kaj estis kaj venos; kaj de la sep spiritoj antaŭ Lia trono;"],[1,5,"kaj de Jesuo Kristo, la fidela atestanto, la unuenaskita el la mortintoj, kaj la reganto de la reĝoj de la tero. Al tiu, kiu nin amas, kaj nin malligis de niaj pekoj per sia sango,","kaj de Jesuo Kristo, la fidela atestanto, la unuenaskita el la mortintoj, kaj la reganto de la reĝoj de la tero. Al tiu, kiu nin amas, kaj nin malligis de niaj pekoj per sia sango,"],[1,6,"kaj faris nin regno, pastroj al lia Dio kaj Patro; al li la gloro kaj la potenco por ĉiam kaj eterne. Amen.","kaj faris nin regno, pastroj al lia Dio kaj Patro; al li la gloro kaj la potenco por ĉiam kaj eterne. Amen."],[1,7,"Jen li venas kun la nuboj; kaj lin vidos ĉiu okulo, kaj tiuj, kiuj lin trapikis; kaj ĉiuj gentoj de la tero ploros pro li. Vere, Amen.","Jen li venas kun la nuboj; kaj lin vidos ĉiu okulo, kaj tiuj, kiuj lin trapikis; kaj ĉiuj gentoj de la tero ploros pro li. Vere, Amen."],[1,8,"Mi estas la Alfa kaj la Omega, diras la Sinjoro, la Dio, kiu estas kaj estis kaj venos, la Plejpotenca.","Mi estas la Alfa kaj la Omega, diras la Sinjoro, la Dio, kiu estas kaj estis kaj venos, la Plejpotenca."],[1,9,"Mi, Johano, via frato kaj partoprenanto kun vi en la aflikto kaj regno kaj pacienco de Jesuo, estis sur la insulo nomata Patmos pro la vorto de Dio kaj la atesto de Jesuo.","Mi, Johano, via frato kaj partoprenanto kun vi en la aflikto kaj regno kaj pacienco de Jesuo, estis sur la insulo nomata Patmos pro la vorto de Dio kaj la atesto de Jesuo."],[1,10,"Mi min trovis en la Spirito en la tago de la Sinjoro, kaj mi aŭdis malantaŭ mi grandan voĉon kvazaŭ de trumpeto,","Mi min trovis en la Spirito en la tago de la Sinjoro, kaj mi aŭdis malantaŭ mi grandan voĉon kvazaŭ de trumpeto,"],[1,11,"dirantan: Kion vi vidas, tion skribu en libron kaj sendu al la sep eklezioj: al Efeso kaj al Smirna kaj al Pergamo kaj al Tiatira kaj al Sardes kaj al Filadelfia kaj al Laodikea.","dirantan: Kion vi vidas, tion skribu en libron kaj sendu al la sep eklezioj: al Efeso kaj al Smirna kaj al Pergamo kaj al Tiatira kaj al Sardes kaj al Filadelfia kaj al Laodikea."],[1,12,"Kaj mi min turnis, por vidi la voĉon, kiu parolis kun mi. Kaj turniĝinte, mi vidis sep orajn lampingojn;","Kaj mi min turnis, por vidi la voĉon, kiu parolis kun mi. Kaj turniĝinte, mi vidis sep orajn lampingojn;"],[1,13,"kaj meze de la sep lampingoj iun similan al la Filo de homo, vestitan ĝispiede, kaj zonitan ĉirkaŭ la brusto per ora zono.","kaj meze de la sep lampingoj iun similan al la Filo de homo, vestitan ĝispiede, kaj zonitan ĉirkaŭ la brusto per ora zono."],[1,14,"Kaj lia kapo kaj liaj haroj estis blankaj kiel blanka lano, kiel neĝo; kaj liaj okuloj estis kiel fajra flamo;","Kaj lia kapo kaj liaj haroj estis blankaj kiel blanka lano, kiel neĝo; kaj liaj okuloj estis kiel fajra flamo;"],[1,15,"kaj liaj piedoj estis kiel brilanta latuno, kvazaŭ rafinita en forno; kaj lia voĉo estis kiel voĉo de multaj akvoj.","kaj liaj piedoj estis kiel brilanta latuno, kvazaŭ rafinita en forno; kaj lia voĉo estis kiel voĉo de multaj akvoj."],[1,16,"Kaj li havis en sia dekstra mano sep stelojn; kaj el lia buŝo eliris akra dutranĉa glavo; kaj lia aspekto estis kiel brilas la suno en sia forteco.","Kaj li havis en sia dekstra mano sep stelojn; kaj el lia buŝo eliris akra dutranĉa glavo; kaj lia aspekto estis kiel brilas la suno en sia forteco."],[1,17,"Kaj kiam mi vidis lin, mi falis ĉe liaj piedoj kvazaŭ senviva. Kaj li metis sian dekstran manon sur min, dirante: Ne timu; mi estas la unua kaj la lasta,","Kaj kiam mi vidis lin, mi falis ĉe liaj piedoj kvazaŭ senviva. Kaj li metis sian dekstran manon sur min, dirante: Ne timu; mi estas la unua kaj la lasta,"],[1,18,"kaj la vivanta; kaj mi fariĝis mortinta, kaj jen, mi estas vivanta por ĉiam kaj eterne, kaj mi havas la ŝlosilojn de la morto kaj de Hades.","kaj la vivanta; kaj mi fariĝis mortinta, kaj jen, mi estas vivanta por ĉiam kaj eterne, kaj mi havas la ŝlosilojn de la morto kaj de Hades."],[1,19,"Skribu do tion, kion vi vidis, kaj kio estas, kaj kio okazos poste;","Skribu do tion, kion vi vidis, kaj kio estas, kaj kio okazos poste;"],[1,20,"la misteron de la sep steloj, kiujn vi vidis en mia dekstra mano, kaj la sep orajn lampingojn. La sep steloj estas la anĝeloj de la sep eklezioj; kaj la sep lampingoj estas la sep eklezioj.","la misteron de la sep steloj, kiujn vi vidis en mia dekstra mano, kaj la sep orajn lampingojn. La sep steloj estas la anĝeloj de la sep eklezioj; kaj la sep lampingoj estas la sep eklezioj."],[2,1,"Al la anĝelo de la eklezio en Efeso skribu: Tiele diras la tenanto de la sep steloj en sia dekstra mano, la iranto meze de la sep oraj lampingoj:","Al la anĝelo de la eklezio en Efeso skribu: Tiele diras la tenanto de la sep steloj en sia dekstra mano, la iranto meze de la sep oraj lampingoj:"],[2,2,"Mi scias viajn farojn, kaj vian laboron kaj vian paciencon, kaj ke vi ne povas toleri la malbonulojn, kaj ke vi provis tiujn, kiuj nomas sin apostoloj kaj ne estas tiaj, kaj trovis ilin malveraj;","Mi scias viajn farojn, kaj vian laboron kaj vian paciencon, kaj ke vi ne povas toleri la malbonulojn, kaj ke vi provis tiujn, kiuj nomas sin apostoloj kaj ne estas tiaj, kaj trovis ilin malveraj;"],[2,3,"kaj vi havas paciencon kaj toleris pro mia nomo kaj ne laciĝis.","kaj vi havas paciencon kaj toleris pro mia nomo kaj ne laciĝis."],[2,4,"Sed mi havas kontraŭ vi, ke vi forlasis vian unuan amon.","Sed mi havas kontraŭ vi, ke vi forlasis vian unuan amon."],[2,5,"Memoru do, de kie vi falis, kaj pentu, kaj faru la unuajn farojn; alie mi venos al vi, kaj formovos vian lampingon el ĝia loko, se vi ne pentos.","Memoru do, de kie vi falis, kaj pentu, kaj faru la unuajn farojn; alie mi venos al vi, kaj formovos vian lampingon el ĝia loko, se vi ne pentos."],[2,6,"Sed ĉi tion vi havas, ke vi malamas la farojn de la Nikolaitoj, kiujn mi ankaŭ malamas.","Sed ĉi tion vi havas, ke vi malamas la farojn de la Nikolaitoj, kiujn mi ankaŭ malamas."],[2,7,"Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. Al la venkanto mi donos manĝi el la arbo de vivo, kiu estas en la Paradizo de Dio.","Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. Al la venkanto mi donos manĝi el la arbo de vivo, kiu estas en la Paradizo de Dio."],[2,8,"Kaj al la anĝelo de la eklezio en Smirna skribu: Tiele diras la unua kaj la lasta, kiu fariĝis senviva kaj vivis:","Kaj al la anĝelo de la eklezio en Smirna skribu: Tiele diras la unua kaj la lasta, kiu fariĝis senviva kaj vivis:"],[2,9,"Mi scias vian aflikton kaj vian malriĉecon (vi tamen estas riĉa), kaj la blasfemon de tiuj, kiuj nomas sin Judoj, kaj estas ne tiaj, sed sinagogo de Satano.","Mi scias vian aflikton kaj vian malriĉecon (vi tamen estas riĉa), kaj la blasfemon de tiuj, kiuj nomas sin Judoj, kaj estas ne tiaj, sed sinagogo de Satano."],[2,10,"Ne timu tion, kion vi suferos; jen la diablo ĵetos iujn el vi en malliberejon, por ke vi estu elprovataj; kaj vi havos aflikton dek tagojn. Estu fidela ĝis morto, kaj mi donos al vi la kronon de vivo.","Ne timu tion, kion vi suferos; jen la diablo ĵetos iujn el vi en malliberejon, por ke vi estu elprovataj; kaj vi havos aflikton dek tagojn. Estu fidela ĝis morto, kaj mi donos al vi la kronon de vivo."],[2,11,"Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. La venkanto tute ne difektiĝos de la dua morto.","Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. La venkanto tute ne difektiĝos de la dua morto."],[2,12,"Kaj al la anĝelo de la eklezio en Pergamo skribu: Tiele diras la portanto de la akra dutranĉa glavo:","Kaj al la anĝelo de la eklezio en Pergamo skribu: Tiele diras la portanto de la akra dutranĉa glavo:"],[2,13,"Mi scias, kie vi loĝas: tie, kie estas la trono de Satano; kaj vi tenas firme mian nomon, kaj ne malkonfesis mian fidon, eĉ en la tagoj de Antipas, mia fidela atestinto, kiu estis mortigita inter vi, kie loĝas Satano.","Mi scias, kie vi loĝas: tie, kie estas la trono de Satano; kaj vi tenas firme mian nomon, kaj ne malkonfesis mian fidon, eĉ en la tagoj de Antipas, mia fidela atestinto, kiu estis mortigita inter vi, kie loĝas Satano."],[2,14,"Sed mi havas kelkon kontraŭ vi: ke vi havas tie sekvantojn de la instruo de Bileam, kiu instruis al Balak ĵeti falilon antaŭ la Izraelidojn, por ke ili manĝu idoloferitaĵojn kaj malĉastu.","Sed mi havas kelkon kontraŭ vi: ke vi havas tie sekvantojn de la instruo de Bileam, kiu instruis al Balak ĵeti falilon antaŭ la Izraelidojn, por ke ili manĝu idoloferitaĵojn kaj malĉastu."],[2,15,"Kaj vi ankaŭ havas sekvantojn de la instruo de la Nikolaitoj tiel same.","Kaj vi ankaŭ havas sekvantojn de la instruo de la Nikolaitoj tiel same."],[2,16,"Pentu do; alie mi rapide venos al vi, kaj militos kontraŭ ili per la glavo de mia buŝo.","Pentu do; alie mi rapide venos al vi, kaj militos kontraŭ ili per la glavo de mia buŝo."],[2,17,"Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. Al la venkanto mi donos el la kaŝita manao, kaj mi donos al li blankan ŝtoneton, kaj sur la ŝtoneto novan nomon skribitan, kiun konas neniu krom la ricevanto.","Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. Al la venkanto mi donos el la kaŝita manao, kaj mi donos al li blankan ŝtoneton, kaj sur la ŝtoneto novan nomon skribitan, kiun konas neniu krom la ricevanto."],[2,18,"Kaj al la anĝelo de la eklezio en Tiatira skribu: Tiele diras la Filo de Dio, kiu havas okulojn kiel fajra flamo, kaj liaj piedoj estas kiel brilanta latuno:","Kaj al la anĝelo de la eklezio en Tiatira skribu: Tiele diras la Filo de Dio, kiu havas okulojn kiel fajra flamo, kaj liaj piedoj estas kiel brilanta latuno:"],[2,19,"Mi scias viajn farojn, kaj viajn amon kaj fidon kaj servadon kaj paciencon, kaj pri viaj faroj, ke la lastaj estas pli multaj ol la unuaj.","Mi scias viajn farojn, kaj viajn amon kaj fidon kaj servadon kaj paciencon, kaj pri viaj faroj, ke la lastaj estas pli multaj ol la unuaj."],[2,20,"Sed mi havas kontraŭ vi, ke vi toleras la virinon Izebel, kiu nomas sin profetino; kaj ŝi instruas kaj delogas miajn servistojn malĉasti kaj manĝi idoloferitaĵojn.","Sed mi havas kontraŭ vi, ke vi toleras la virinon Izebel, kiu nomas sin profetino; kaj ŝi instruas kaj delogas miajn servistojn malĉasti kaj manĝi idoloferitaĵojn."],[2,21,"Kaj mi donis al ŝi tempon, por ke ŝi pentu; kaj ŝi ne volas penti pri sia malĉasteco.","Kaj mi donis al ŝi tempon, por ke ŝi pentu; kaj ŝi ne volas penti pri sia malĉasteco."],[2,22,"Jen mi ĵetos ŝin en liton, kaj la kun ŝi adultantojn en grandan aflikton, se ili ne pentos pri ŝiaj faroj.","Jen mi ĵetos ŝin en liton, kaj la kun ŝi adultantojn en grandan aflikton, se ili ne pentos pri ŝiaj faroj."],[2,23,"Kaj mi pereigos ŝiajn idojn per morto; kaj ĉiuj eklezioj scios, ke mi estas tiu, kiu esploras internaĵojn kaj korojn; kaj mi donos al ĉiu el vi laŭ viaj faroj.","Kaj mi pereigos ŝiajn idojn per morto; kaj ĉiuj eklezioj scios, ke mi estas tiu, kiu esploras internaĵojn kaj korojn; kaj mi donos al ĉiu el vi laŭ viaj faroj."],[2,24,"Sed al vi mi diras, al la ceteraj en Tiatira, al ĉiuj, kiuj ne havas ĉi tiun instruon, kaj kiuj ne konas la profundaĵojn de Satano, kiel oni diras: Mi ne ĵetos sur vin alian ŝarĝon.","Sed al vi mi diras, al la ceteraj en Tiatira, al ĉiuj, kiuj ne havas ĉi tiun instruon, kaj kiuj ne konas la profundaĵojn de Satano, kiel oni diras: Mi ne ĵetos sur vin alian ŝarĝon."],[2,25,"Tamen tion, kion vi havas, tenu, ĝis mi venos.","Tamen tion, kion vi havas, tenu, ĝis mi venos."],[2,26,"Kaj al la venkanto kaj la observanto de miaj faroj ĝis la fino mi donos aŭtoritaton super la nacioj;","Kaj al la venkanto kaj la observanto de miaj faroj ĝis la fino mi donos aŭtoritaton super la nacioj;"],[2,27,"kaj li regos ilin per fera sceptro, kiel la potaj vazoj estas dispecigataj; kiel mi ankaŭ ricevis de mia Patro;","kaj li regos ilin per fera sceptro, kiel la potaj vazoj estas dispecigataj; kiel mi ankaŭ ricevis de mia Patro;"],[2,28,"kaj mi donos al li la matenan stelon.","kaj mi donos al li la matenan stelon."],[2,29,"Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.","Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj."],[3,1,"Kaj al la anĝelo de la eklezio en Sardes skribu: Tiele diras tiu, kiu havas la sep Spiritojn de Dio, kaj la sep stelojn: Mi scias viajn farojn, ke vi estas nomata viva, kaj estas malviva.","Kaj al la anĝelo de la eklezio en Sardes skribu: Tiele diras tiu, kiu havas la sep Spiritojn de Dio, kaj la sep stelojn: Mi scias viajn farojn, ke vi estas nomata viva, kaj estas malviva."],[3,2,"Fariĝu vigla, kaj firmigu la restaĵojn, kiuj estis preskaŭ mortantaj; ĉar mi ne trovis viajn farojn plenumitaj antaŭ mia Dio.","Fariĝu vigla, kaj firmigu la restaĵojn, kiuj estis preskaŭ mortantaj; ĉar mi ne trovis viajn farojn plenumitaj antaŭ mia Dio."],[3,3,"Memoru do, kiel vi ricevis kaj aŭdis; kaj observu, kaj pentu. Se do vi ne viglos, mi venos, kvazaŭ ŝtelisto, kaj vi ne scios, je kiu horo mi venos al vi.","Memoru do, kiel vi ricevis kaj aŭdis; kaj observu, kaj pentu. Se do vi ne viglos, mi venos, kvazaŭ ŝtelisto, kaj vi ne scios, je kiu horo mi venos al vi."],[3,4,"Sed vi havas en Sardes kelkajn nomojn, kiuj ne makulis siajn vestojn; kaj ili promenos kun mi en blankaĵoj; ĉar ili estas indaj.","Sed vi havas en Sardes kelkajn nomojn, kiuj ne makulis siajn vestojn; kaj ili promenos kun mi en blankaĵoj; ĉar ili estas indaj."],[3,5,"La venkanto estos tiel vestita per blankaj vestoj; kaj mi ja ne elstrekos lian nomon el la libro de vivo, kaj mi konfesos lian nomon antaŭ mia Patro kaj antaŭ Liaj anĝeloj.","La venkanto estos tiel vestita per blankaj vestoj; kaj mi ja ne elstrekos lian nomon el la libro de vivo, kaj mi konfesos lian nomon antaŭ mia Patro kaj antaŭ Liaj anĝeloj."],[3,6,"Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.","Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj."],[3,7,"Kaj al la anĝelo de la eklezio en Filadelfia skribu: Tiele diras la sanktulo, la verulo, kiu havas la ŝlosilon de David, tiu, kiu malfermas, kaj neniu fermas; kiu fermas, kaj neniu malfermas:","Kaj al la anĝelo de la eklezio en Filadelfia skribu: Tiele diras la sanktulo, la verulo, kiu havas la ŝlosilon de David, tiu, kiu malfermas, kaj neniu fermas; kiu fermas, kaj neniu malfermas:"],[3,8,"Mi scias viajn farojn (jen mi donis antaŭ vi pordon malfermitan, kiun neniu povas fermi), ke vi havas kelkan potencon, kaj observis mian vorton, kaj ne malkonfesis mian nomon.","Mi scias viajn farojn (jen mi donis antaŭ vi pordon malfermitan, kiun neniu povas fermi), ke vi havas kelkan potencon, kaj observis mian vorton, kaj ne malkonfesis mian nomon."],[3,9,"Jen mi donas el la sinagogo de Satano, kiuj sin nomas Judoj, kaj estas ne tiaj, sed mensogas; jen mi igos ilin veni kaj adorkliniĝi antaŭ viaj piedoj, kaj scii, ke mi vin amis.","Jen mi donas el la sinagogo de Satano, kiuj sin nomas Judoj, kaj estas ne tiaj, sed mensogas; jen mi igos ilin veni kaj adorkliniĝi antaŭ viaj piedoj, kaj scii, ke mi vin amis."],[3,10,"Ĉar vi observis la vorton de mia pacienco, mi ankaŭ vin konservos el tiu horo de provo, kiu venos sur la tutan mondon, por provi la loĝantojn sur la tero.","Ĉar vi observis la vorton de mia pacienco, mi ankaŭ vin konservos el tiu horo de provo, kiu venos sur la tutan mondon, por provi la loĝantojn sur la tero."],[3,11,"Mi venos rapide; tenadu tion, kion vi havas, por ke neniu forprenu vian kronon.","Mi venos rapide; tenadu tion, kion vi havas, por ke neniu forprenu vian kronon."],[3,12,"La venkanton mi faros kolono en la templo de mia Dio, kaj li ne plu eliros el ĝi; kaj mi skribos sur li la nomon de mia Dio, kaj la nomon de la urbo de mia Dio, la nova Jerusalem, kiu venas malsupren de mia Dio el la ĉielo, kaj mian novan nomon.","La venkanton mi faros kolono en la templo de mia Dio, kaj li ne plu eliros el ĝi; kaj mi skribos sur li la nomon de mia Dio, kaj la nomon de la urbo de mia Dio, la nova Jerusalem, kiu venas malsupren de mia Dio el la ĉielo, kaj mian novan nomon."],[3,13,"Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.","Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj."],[3,14,"Kaj al la anĝelo de la eklezio en Laodikea skribu: Tiele diras la Amen, la atestanto fidela kaj vera, la komenco de la kreo de Dio:","Kaj al la anĝelo de la eklezio en Laodikea skribu: Tiele diras la Amen, la atestanto fidela kaj vera, la komenco de la kreo de Dio:"],[3,15,"Mi scias viajn farojn, ke vi estas nek malvarma, nek varmega; mi volus, ke vi estu aŭ malvarma aŭ varmega.","Mi scias viajn farojn, ke vi estas nek malvarma, nek varmega; mi volus, ke vi estu aŭ malvarma aŭ varmega."],[3,16,"Tial, ĉar vi estas varmeta, kaj nek malvarma nek varmega, mi elsputos vin el mia buŝo.","Tial, ĉar vi estas varmeta, kaj nek malvarma nek varmega, mi elsputos vin el mia buŝo."],[3,17,"Ĉar vi diras: Mi estas riĉa kaj akiris riĉon, kaj nenion mi bezonas; kaj vi ne scias, ke vi estas la mizera kaj kompatinda kaj malriĉa kaj blinda kaj nuda;","Ĉar vi diras: Mi estas riĉa kaj akiris riĉon, kaj nenion mi bezonas; kaj vi ne scias, ke vi estas la mizera kaj kompatinda kaj malriĉa kaj blinda kaj nuda;"],[3,18,"mi konsilas al vi aĉeti de mi oron rafinitan per fajro, por ke vi riĉiĝu; kaj blankajn vestojn, por ke vi vin vestu, kaj por ke ne aperu la honto de via nudeco; kaj kolirion, por ŝmiri viajn okulojn, por ke vi vidu.","mi konsilas al vi aĉeti de mi oron rafinitan per fajro, por ke vi riĉiĝu; kaj blankajn vestojn, por ke vi vin vestu, kaj por ke ne aperu la honto de via nudeco; kaj kolirion, por ŝmiri viajn okulojn, por ke vi vidu."],[3,19,"Ĉiujn, kiujn mi amas, mi riproĉas kaj punas; estu do fervora, kaj pentu.","Ĉiujn, kiujn mi amas, mi riproĉas kaj punas; estu do fervora, kaj pentu."],[3,20,"Jen mi staras ĉe la pordo kaj frapas; se iu aŭdas mian voĉon kaj malfermas la pordon, mi eniros al li kaj manĝos kun li, kaj li kun mi.","Jen mi staras ĉe la pordo kaj frapas; se iu aŭdas mian voĉon kaj malfermas la pordon, mi eniros al li kaj manĝos kun li, kaj li kun mi."],[3,21,"Al la venkanto mi donos sidiĝi kun mi sur mia trono, kiel mi ankaŭ venkis kaj sidiĝis kun mia Patro sur Lia trono.","Al la venkanto mi donos sidiĝi kun mi sur mia trono, kiel mi ankaŭ venkis kaj sidiĝis kun mia Patro sur Lia trono."],[3,22,"Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.","Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj."],[4,1,"Post tio mi rigardis, kaj jen pordo malfermita en la ĉielo, kaj la unua voĉo, kiun mi aŭdis, estis voĉo kvazaŭ de trumpeto parolanta kun mi, dirante: Suprenvenu ĉi tien, kaj mi montros al vi tion, kio devas okazi poste.","Post tio mi rigardis, kaj jen pordo malfermita en la ĉielo, kaj la unua voĉo, kiun mi aŭdis, estis voĉo kvazaŭ de trumpeto parolanta kun mi, dirante: Suprenvenu ĉi tien, kaj mi montros al vi tion, kio devas okazi poste."],[4,2,"Tuj mi min trovis en la Spirito; kaj jen trono stariĝis en la ĉielo, kaj sur la trono unu sidanta;","Tuj mi min trovis en la Spirito; kaj jen trono stariĝis en la ĉielo, kaj sur la trono unu sidanta;"],[4,3,"kaj la Sidanto estis en aspekto simila al ŝtono jaspisa kaj sardia; kaj jen ĉielarko ĉirkaŭ la trono, aspekte simila al smeraldo.","kaj la Sidanto estis en aspekto simila al ŝtono jaspisa kaj sardia; kaj jen ĉielarko ĉirkaŭ la trono, aspekte simila al smeraldo."],[4,4,"Kaj ĉirkaŭ la trono estis dudek kvar tronoj; kaj sur la tronoj mi vidis dudek kvar presbiterojn sidantajn, vestitajn per blankaj vestoj; kaj sur iliaj kapoj orajn kronojn.","Kaj ĉirkaŭ la trono estis dudek kvar tronoj; kaj sur la tronoj mi vidis dudek kvar presbiterojn sidantajn, vestitajn per blankaj vestoj; kaj sur iliaj kapoj orajn kronojn."],[4,5,"Kaj el la trono eliris fulmoj kaj voĉoj kaj tondroj. Kaj antaŭ la trono brulis sep fajraj torĉoj, kiuj estas la sep Spiritoj de Dio;","Kaj el la trono eliris fulmoj kaj voĉoj kaj tondroj. Kaj antaŭ la trono brulis sep fajraj torĉoj, kiuj estas la sep Spiritoj de Dio;"],[4,6,"kaj antaŭ la trono kvazaŭ vitra maro, simila al kristalo; kaj meze apud la trono kaj ronde ĉirkaŭ la trono kvar kreitaĵoj, plenaj de okuloj antaŭe kaj malantaŭe.","kaj antaŭ la trono kvazaŭ vitra maro, simila al kristalo; kaj meze apud la trono kaj ronde ĉirkaŭ la trono kvar kreitaĵoj, plenaj de okuloj antaŭe kaj malantaŭe."],[4,7,"Kaj la unua kreitaĵo similis leonon, kaj la dua kreitaĵo similis bovidon, kaj la tria kreitaĵo havis vizaĝon kvazaŭ homan, kaj la kvara kreitaĵo similis aglon flugantan.","Kaj la unua kreitaĵo similis leonon, kaj la dua kreitaĵo similis bovidon, kaj la tria kreitaĵo havis vizaĝon kvazaŭ homan, kaj la kvara kreitaĵo similis aglon flugantan."],[4,8,"Kaj la kvar kreitaĵoj, havantaj po ses flugiloj, estas ĉirkaŭe kaj interne plenaj de okuloj; kaj paŭzon ili ne havas tage kaj nokte, dirante: Sankta, sankta, sankta, estas Dio, la Sinjoro, la Plejpotenca, la estanta kaj estinta kaj venonta.","Kaj la kvar kreitaĵoj, havantaj po ses flugiloj, estas ĉirkaŭe kaj interne plenaj de okuloj; kaj paŭzon ili ne havas tage kaj nokte, dirante: Sankta, sankta, sankta, estas Dio, la Sinjoro, la Plejpotenca, la estanta kaj estinta kaj venonta."],[4,9,"Kaj kiam la kreitaĵoj donos gloron kaj honoron kaj dankon al la Sidanto sur la trono, al la Vivanto por ĉiam kaj eterne,","Kaj kiam la kreitaĵoj donos gloron kaj honoron kaj dankon al la Sidanto sur la trono, al la Vivanto por ĉiam kaj eterne,"],[4,10,"la dudek kvar presbiteroj falos antaŭ la Sidanto sur la trono, kaj ili adorkliniĝos al la Vivanto por ĉiam kaj eterne, kaj ĵetos siajn kronojn antaŭ la trono, dirante:","la dudek kvar presbiteroj falos antaŭ la Sidanto sur la trono, kaj ili adorkliniĝos al la Vivanto por ĉiam kaj eterne, kaj ĵetos siajn kronojn antaŭ la trono, dirante:"],[4,11,"Inda Vi estas, ho nia Sinjoro kaj nia Dio, ricevi la gloron kaj la honoron kaj la potencon; ĉar Vi kreis ĉion, kaj pro Via volo ĉio ekzistis kaj kreiĝis.","Inda Vi estas, ho nia Sinjoro kaj nia Dio, ricevi la gloron kaj la honoron kaj la potencon; ĉar Vi kreis ĉion, kaj pro Via volo ĉio ekzistis kaj kreiĝis."],[5,1,"Kaj mi vidis en la dekstra mano de la Sidanto sur la trono libron, skribitan interne kaj malantaŭe, sigelitan per sep sigeloj.","Kaj mi vidis en la dekstra mano de la Sidanto sur la trono libron, skribitan interne kaj malantaŭe, sigelitan per sep sigeloj."],[5,2,"Kaj mi vidis fortan anĝelon, proklamantan per granda voĉo: Kiu estas inda malfermi la libron kaj rompi ĝiajn sigelojn?","Kaj mi vidis fortan anĝelon, proklamantan per granda voĉo: Kiu estas inda malfermi la libron kaj rompi ĝiajn sigelojn?"],[5,3,"Kaj neniu en la ĉielo, nek sur la tero, nek sub la tero, povis malfermi la libron, aŭ rigardi ĝin.","Kaj neniu en la ĉielo, nek sur la tero, nek sub la tero, povis malfermi la libron, aŭ rigardi ĝin."],[5,4,"Kaj mi multe ploris, ĉar troviĝis neniu inda malfermi la libron, aŭ ĝin rigardi;","Kaj mi multe ploris, ĉar troviĝis neniu inda malfermi la libron, aŭ ĝin rigardi;"],[5,5,"kaj unu el la presbiteroj diris al mi: Ne ploru; jen la leono el la tribo de Jehuda, la Markoto de David, venkis, por malfermi la libron kaj ĝiajn sep sigelojn.","kaj unu el la presbiteroj diris al mi: Ne ploru; jen la leono el la tribo de Jehuda, la Markoto de David, venkis, por malfermi la libron kaj ĝiajn sep sigelojn."],[5,6,"Kaj mi vidis meze inter la trono kaj la kvar kreitaĵoj, kaj meze de la presbiteroj, Ŝafidon starantan, kvazaŭ oferbuĉitan, havantan sep kornojn kaj sep okulojn, kiuj estas la sep Spiritoj de Dio, senditaj sur la tutan teron.","Kaj mi vidis meze inter la trono kaj la kvar kreitaĵoj, kaj meze de la presbiteroj, Ŝafidon starantan, kvazaŭ oferbuĉitan, havantan sep kornojn kaj sep okulojn, kiuj estas la sep Spiritoj de Dio, senditaj sur la tutan teron."],[5,7,"Kaj li venis, kaj prenis ĝin el la dekstra mano de la Sidanto sur la trono.","Kaj li venis, kaj prenis ĝin el la dekstra mano de la Sidanto sur la trono."],[5,8,"Kaj kiam li prenis la libron, la kvar kreitaĵoj kaj la dudek kvar presbiteroj falis antaŭ la Ŝafido, havantaj ĉiu harpon, kaj orajn pelvojn plenajn de incenso, kiuj estas la preĝoj de la sanktuloj.","Kaj kiam li prenis la libron, la kvar kreitaĵoj kaj la dudek kvar presbiteroj falis antaŭ la Ŝafido, havantaj ĉiu harpon, kaj orajn pelvojn plenajn de incenso, kiuj estas la preĝoj de la sanktuloj."],[5,9,"Kaj ili kantis novan kanton, dirante: Vi estas inda preni la libron kaj malfermi ĝiajn sigelojn; ĉar vi estis mortigita, kaj vi elaĉetis al Dio per via sango homojn el ĉiu tribo kaj lingvo kaj popolo kaj nacio,","Kaj ili kantis novan kanton, dirante: Vi estas inda preni la libron kaj malfermi ĝiajn sigelojn; ĉar vi estis mortigita, kaj vi elaĉetis al Dio per via sango homojn el ĉiu tribo kaj lingvo kaj popolo kaj nacio,"],[5,10,"kaj faris ilin al nia Dio regno kaj pastroj; kaj ili reĝas sur la tero.","kaj faris ilin al nia Dio regno kaj pastroj; kaj ili reĝas sur la tero."],[5,11,"Kaj mi rigardis, kaj mi aŭdis voĉon de multaj anĝeloj, ronde ĉirkaŭ la trono kaj la kreitaĵoj kaj la presbiteroj; kaj ilia nombro estis miriadoj da miriadoj kaj miloj da miloj;","Kaj mi rigardis, kaj mi aŭdis voĉon de multaj anĝeloj, ronde ĉirkaŭ la trono kaj la kreitaĵoj kaj la presbiteroj; kaj ilia nombro estis miriadoj da miriadoj kaj miloj da miloj;"],[5,12,"dirantaj per granda voĉo: Inda estas la Ŝafido, la mortigita, ricevi la potencon kaj riĉon kaj saĝecon kaj forton kaj honoron kaj gloron kaj laŭdon.","dirantaj per granda voĉo: Inda estas la Ŝafido, la mortigita, ricevi la potencon kaj riĉon kaj saĝecon kaj forton kaj honoron kaj gloron kaj laŭdon."],[5,13,"Kaj ĉiun kreitaĵon, kiu estis en la ĉielo kaj sur la tero kaj sub la tero kaj sur la maro, kaj ĉion en ili, mi aŭdis dirantajn: Al la Sidanto sur la trono, kaj al la Ŝafido, estu la laŭdo kaj la honoro kaj la gloro kaj la potenco por ĉiam kaj eterne.","Kaj ĉiun kreitaĵon, kiu estis en la ĉielo kaj sur la tero kaj sub la tero kaj sur la maro, kaj ĉion en ili, mi aŭdis dirantajn: Al la Sidanto sur la trono, kaj al la Ŝafido, estu la laŭdo kaj la honoro kaj la gloro kaj la potenco por ĉiam kaj eterne."],[5,14,"Kaj la kvar kreitaĵoj diris: Amen. Kaj la presbiteroj falis kaj adorkliniĝis.","Kaj la kvar kreitaĵoj diris: Amen. Kaj la presbiteroj falis kaj adorkliniĝis."],[6,1,"Kaj mi rigardis, kiam la Ŝafido malfermis unu el la sep sigeloj, kaj mi aŭdis unu el la kvar kreitaĵoj dirantan kvazaŭ per voĉo de tondro: Venu.","Kaj mi rigardis, kiam la Ŝafido malfermis unu el la sep sigeloj, kaj mi aŭdis unu el la kvar kreitaĵoj dirantan kvazaŭ per voĉo de tondro: Venu."],[6,2,"Kaj mi rigardis, kaj jen blanka ĉevalo, kaj la sidanta sur ĝi havis pafarkon; kaj estis donita al li krono; kaj li eliris venkanta, kaj por venki.","Kaj mi rigardis, kaj jen blanka ĉevalo, kaj la sidanta sur ĝi havis pafarkon; kaj estis donita al li krono; kaj li eliris venkanta, kaj por venki."],[6,3,"Kaj kiam li malfermis la duan sigelon, mi aŭdis la duan kreitaĵon dirantan: Venu.","Kaj kiam li malfermis la duan sigelon, mi aŭdis la duan kreitaĵon dirantan: Venu."],[6,4,"Kaj eliris alia ĉevalo, flamkolora; kaj al la sidanta sur ĝi estis donite forpreni pacon de la tero, kaj ke oni mortigu unu la alian; kaj al li estis donita granda glavo.","Kaj eliris alia ĉevalo, flamkolora; kaj al la sidanta sur ĝi estis donite forpreni pacon de la tero, kaj ke oni mortigu unu la alian; kaj al li estis donita granda glavo."],[6,5,"Kaj kiam li malfermis la trian sigelon, mi aŭdis la trian kreitaĵon dirantan: Venu. Kaj mi rigardis, kaj jen nigra ĉevalo; kaj la sidanta sur ĝi havis en la mano pesilon.","Kaj kiam li malfermis la trian sigelon, mi aŭdis la trian kreitaĵon dirantan: Venu. Kaj mi rigardis, kaj jen nigra ĉevalo; kaj la sidanta sur ĝi havis en la mano pesilon."],[6,6,"Kaj mi aŭdis kvazaŭ voĉon, meze de la kvar kreitaĵoj, dirantan: Mezuro da tritiko por denaro, kaj tri mezuroj da hordeo por denaro; kaj la oleon kaj la vinon ne difektu.","Kaj mi aŭdis kvazaŭ voĉon, meze de la kvar kreitaĵoj, dirantan: Mezuro da tritiko por denaro, kaj tri mezuroj da hordeo por denaro; kaj la oleon kaj la vinon ne difektu."],[6,7,"Kaj kiam li malfermis la kvaran sigelon, mi aŭdis la voĉon de la kvara kreitaĵo dirantan: Venu.","Kaj kiam li malfermis la kvaran sigelon, mi aŭdis la voĉon de la kvara kreitaĵo dirantan: Venu."],[6,8,"Kaj mi rigardis, kaj jen pala ĉevalo; kaj la nomo de la sidanta sur ĝi estis Morto; kaj Hades sekvis kun li. Kaj estis donita al ili aŭtoritato super kvarono de la tero, por mortigi per glavo kaj per malsato kaj per morto kaj per la sovaĝaj bestoj de la tero.","Kaj mi rigardis, kaj jen pala ĉevalo; kaj la nomo de la sidanta sur ĝi estis Morto; kaj Hades sekvis kun li. Kaj estis donita al ili aŭtoritato super kvarono de la tero, por mortigi per glavo kaj per malsato kaj per morto kaj per la sovaĝaj bestoj de la tero."],[6,9,"Kaj kiam li malfermis la kvinan sigelon, mi vidis sub la altaro la animojn de la mortigitaj pro la vorto de Dio kaj pro la atesto, kiun ili havadis;","Kaj kiam li malfermis la kvinan sigelon, mi vidis sub la altaro la animojn de la mortigitaj pro la vorto de Dio kaj pro la atesto, kiun ili havadis;"],[6,10,"kaj ili kriis per granda voĉo, dirante: Ĝis kiam, ho Estro, la sankta kaj vera, Vi ne juĝas kaj ne venĝas nian sangon al la loĝantoj sur la tero?","kaj ili kriis per granda voĉo, dirante: Ĝis kiam, ho Estro, la sankta kaj vera, Vi ne juĝas kaj ne venĝas nian sangon al la loĝantoj sur la tero?"],[6,11,"Kaj estis donita al ĉiu el ili blanka robo; kaj estis dirite al ili, ke ili atendu ankoraŭ kelkan tempon, ĝis ankaŭ iliaj kunservistoj kaj iliaj fratoj, mortigotaj kiel ili mem, plensumiĝos.","Kaj estis donita al ĉiu el ili blanka robo; kaj estis dirite al ili, ke ili atendu ankoraŭ kelkan tempon, ĝis ankaŭ iliaj kunservistoj kaj iliaj fratoj, mortigotaj kiel ili mem, plensumiĝos."],[6,12,"Kaj mi rigardis, kiam li malfermis la sesan sigelon, kaj fariĝis granda tertremo; kaj la suno fariĝis nigra kiel sakaĵo el haroj, kaj la tuta luno fariĝis kiel sango;","Kaj mi rigardis, kiam li malfermis la sesan sigelon, kaj fariĝis granda tertremo; kaj la suno fariĝis nigra kiel sakaĵo el haroj, kaj la tuta luno fariĝis kiel sango;"],[6,13,"kaj la steloj de la ĉielo falis sur la teron, kiel figarbo, skuate de forta vento, ĵetas siajn nematurajn figojn.","kaj la steloj de la ĉielo falis sur la teron, kiel figarbo, skuate de forta vento, ĵetas siajn nematurajn figojn."],[6,14,"Kaj la ĉielo formoviĝis, kvazaŭ kunvolvata libro; kaj ĉiu monto kaj ĉiu insulo formoviĝis de sia loko.","Kaj la ĉielo formoviĝis, kvazaŭ kunvolvata libro; kaj ĉiu monto kaj ĉiu insulo formoviĝis de sia loko."],[6,15,"Kaj la reĝoj de la tero kaj la granduloj kaj la milestroj kaj la riĉuloj kaj la fortuloj kaj ĉiu sklavo kaj ĉiu liberulo sin kaŝis en la kavernoj kaj inter la rokoj de la montoj;","Kaj la reĝoj de la tero kaj la granduloj kaj la milestroj kaj la riĉuloj kaj la fortuloj kaj ĉiu sklavo kaj ĉiu liberulo sin kaŝis en la kavernoj kaj inter la rokoj de la montoj;"],[6,16,"kaj ili diris al la montoj kaj al la rokoj: Falu sur nin, kaj nin kaŝu for de la vizaĝo de la Sidanto sur la trono, kaj for de la kolero de la Ŝafido;","kaj ili diris al la montoj kaj al la rokoj: Falu sur nin, kaj nin kaŝu for de la vizaĝo de la Sidanto sur la trono, kaj for de la kolero de la Ŝafido;"],[6,17,"ĉar venis la granda tago de ilia kolero; kaj kiu povas stari?","ĉar venis la granda tago de ilia kolero; kaj kiu povas stari?"],[7,1,"Post tio mi vidis kvar anĝelojn starantajn sur la kvar anguloj de la tero, retenantajn la kvar ventojn de la tero, por ke ne blovu vento sur la teron, nek sur la maron, nek sur ian arbon.","Post tio mi vidis kvar anĝelojn starantajn sur la kvar anguloj de la tero, retenantajn la kvar ventojn de la tero, por ke ne blovu vento sur la teron, nek sur la maron, nek sur ian arbon."],[7,2,"Kaj mi vidis alian anĝelon suprenirantan de la sunleviĝo, havantan sigelilon de la vivanta Dio; kaj li ekkriis per granda voĉo al la kvar anĝeloj, al kiuj estis donite difekti la teron kaj la maron,","Kaj mi vidis alian anĝelon suprenirantan de la sunleviĝo, havantan sigelilon de la vivanta Dio; kaj li ekkriis per granda voĉo al la kvar anĝeloj, al kiuj estis donite difekti la teron kaj la maron,"],[7,3,"dirante: Ne difektu la teron, nek la maron, nek la arbojn, antaŭ ol ni sigelos sur iliaj fruntoj la servistojn de nia Dio.","dirante: Ne difektu la teron, nek la maron, nek la arbojn, antaŭ ol ni sigelos sur iliaj fruntoj la servistojn de nia Dio."],[7,4,"Kaj mi aŭdis la nombron de la sigelitoj, cent kvardek kvar miloj, sigelitaj el ĉiuj triboj de la Izraelidoj:","Kaj mi aŭdis la nombron de la sigelitoj, cent kvardek kvar miloj, sigelitaj el ĉiuj triboj de la Izraelidoj:"],[7,5,"El la tribo de Jehuda estis sigelitaj dek du miloj; El la tribo de Ruben, dek du miloj; El la tribo de Gad, dek du miloj;","El la tribo de Jehuda estis sigelitaj dek du miloj; El la tribo de Ruben, dek du miloj; El la tribo de Gad, dek du miloj;"],[7,6,"El la tribo de Aŝer, dek du miloj; El la tribo de Naftali, dek du miloj; El la tribo de Manase, dek du miloj;","El la tribo de Aŝer, dek du miloj; El la tribo de Naftali, dek du miloj; El la tribo de Manase, dek du miloj;"],[7,7,"El la tribo de Simeon, dek du miloj; El la tribo de Levi, dek du miloj; El la tribo de Isaĥar, dek du miloj;","El la tribo de Simeon, dek du miloj; El la tribo de Levi, dek du miloj; El la tribo de Isaĥar, dek du miloj;"],[7,8,"El la tribo de Zebulun, dek du miloj; El la tribo de Jozef, dek du miloj; El la tribo de Benjamen estis sigelitaj dek du miloj.","El la tribo de Zebulun, dek du miloj; El la tribo de Jozef, dek du miloj; El la tribo de Benjamen estis sigelitaj dek du miloj."],[7,9,"Post tio mi rigardis, kaj jen granda homamaso, kiun neniu povis kalkuli, el ĉiu nacio, kaj el ĉiuj triboj kaj popoloj kaj lingvoj, starantaj antaŭ la trono kaj antaŭ la Ŝafido, vestitaj per blankaj roboj, kaj kun palmoj en iliaj manoj;","Post tio mi rigardis, kaj jen granda homamaso, kiun neniu povis kalkuli, el ĉiu nacio, kaj el ĉiuj triboj kaj popoloj kaj lingvoj, starantaj antaŭ la trono kaj antaŭ la Ŝafido, vestitaj per blankaj roboj, kaj kun palmoj en iliaj manoj;"],[7,10,"kaj ili kriis per granda voĉo, dirante: Savo al nia Dio, la sidanta sur la trono, kaj al la Ŝafido.","kaj ili kriis per granda voĉo, dirante: Savo al nia Dio, la sidanta sur la trono, kaj al la Ŝafido."],[7,11,"Kaj ĉiuj anĝeloj staris ĉirkaŭ la trono kaj la presbiteroj kaj la kvar kreitaĵoj; kaj ili falis sur sian vizaĝon antaŭ la trono, kaj adorkliniĝis al Dio,","Kaj ĉiuj anĝeloj staris ĉirkaŭ la trono kaj la presbiteroj kaj la kvar kreitaĵoj; kaj ili falis sur sian vizaĝon antaŭ la trono, kaj adorkliniĝis al Dio,"],[7,12,"dirante: Amen; La laŭdo kaj la gloro kaj la saĝeco kaj la danko kaj la honoro kaj la potenco kaj la forto estu al nia Dio por ĉiam kaj eterne. Amen.","dirante: Amen; La laŭdo kaj la gloro kaj la saĝeco kaj la danko kaj la honoro kaj la potenco kaj la forto estu al nia Dio por ĉiam kaj eterne. Amen."],[7,13,"Kaj respondis unu el la presbiteroj, dirante al mi: Kiuj estas ĉi tiuj per blankaj roboj vestitaj, kaj de kie ili venis?","Kaj respondis unu el la presbiteroj, dirante al mi: Kiuj estas ĉi tiuj per blankaj roboj vestitaj, kaj de kie ili venis?"],[7,14,"Kaj mi diris al li: Mia sinjoro, vi scias. Kaj li diris al mi: Ĉi tiuj estas la venantoj el la granda afliktado, kaj ili lavis siajn robojn, kaj blankigis ilin en la sango de la Ŝafido.","Kaj mi diris al li: Mia sinjoro, vi scias. Kaj li diris al mi: Ĉi tiuj estas la venantoj el la granda afliktado, kaj ili lavis siajn robojn, kaj blankigis ilin en la sango de la Ŝafido."],[7,15,"Tial ili estas antaŭ la trono de Dio; kaj ili servas al Li tage kaj nokte en Lia templo; kaj la Sidanto sur la trono etendos super ili Sian tabernaklon.","Tial ili estas antaŭ la trono de Dio; kaj ili servas al Li tage kaj nokte en Lia templo; kaj la Sidanto sur la trono etendos super ili Sian tabernaklon."],[7,16,"Ili ne plu malsatos, nek plu soifos; ne frapos ilin la suno nek ia varmego;","Ili ne plu malsatos, nek plu soifos; ne frapos ilin la suno nek ia varmego;"],[7,17,"ĉar la Ŝafido, kiu estas meze de la trono, paŝtos ilin kaj kondukos ilin al akvofontoj de vivo; kaj Dio forviŝos de iliaj okuloj ĉiun larmon.","ĉar la Ŝafido, kiu estas meze de la trono, paŝtos ilin kaj kondukos ilin al akvofontoj de vivo; kaj Dio forviŝos de iliaj okuloj ĉiun larmon."],[8,1,"Kaj kiam li malfermis la sepan sigelon, fariĝis silento en la ĉielo por ĉirkaŭ duono de horo.","Kaj kiam li malfermis la sepan sigelon, fariĝis silento en la ĉielo por ĉirkaŭ duono de horo."],[8,2,"Kaj mi vidis la sep anĝelojn, kiuj staras antaŭ Dio; kaj estis donitaj al ili sep trumpetoj.","Kaj mi vidis la sep anĝelojn, kiuj staras antaŭ Dio; kaj estis donitaj al ili sep trumpetoj."],[8,3,"Kaj alia anĝelo venis, kaj staris apud la altaro, havante incensilon oran; kaj estis donita al li multe da incenso, por ke li aldonu ĝin al la preĝoj de ĉiuj sanktuloj sur la altaro ora, kiu estis antaŭ la trono.","Kaj alia anĝelo venis, kaj staris apud la altaro, havante incensilon oran; kaj estis donita al li multe da incenso, por ke li aldonu ĝin al la preĝoj de ĉiuj sanktuloj sur la altaro ora, kiu estis antaŭ la trono."],[8,4,"Kaj la fumo de la incenso, kun la preĝoj de la sanktuloj, leviĝis antaŭ Dio el la mano de la anĝelo.","Kaj la fumo de la incenso, kun la preĝoj de la sanktuloj, leviĝis antaŭ Dio el la mano de la anĝelo."],[8,5,"Kaj la anĝelo prenis la incensilon, kaj li plenigis ĝin per la fajro de la altaro, kaj ĵetis ĝin sur la teron; kaj fariĝis tondroj kaj voĉoj kaj fulmoj kaj tertremo.","Kaj la anĝelo prenis la incensilon, kaj li plenigis ĝin per la fajro de la altaro, kaj ĵetis ĝin sur la teron; kaj fariĝis tondroj kaj voĉoj kaj fulmoj kaj tertremo."],[8,6,"Kaj la sep anĝeloj, havantaj la sep trumpetojn, sin pretigis, por trumpeti.","Kaj la sep anĝeloj, havantaj la sep trumpetojn, sin pretigis, por trumpeti."],[8,7,"Kaj la unua trumpetis, kaj fariĝis hajlo kaj fajro, miksitaj kun sango, kaj ili estis ĵetitaj sur la teron; kaj triono de la tero forbrulis, kaj triono de la arboj forbrulis, kaj la tuta verda herbo forbrulis.","Kaj la unua trumpetis, kaj fariĝis hajlo kaj fajro, miksitaj kun sango, kaj ili estis ĵetitaj sur la teron; kaj triono de la tero forbrulis, kaj triono de la arboj forbrulis, kaj la tuta verda herbo forbrulis."],[8,8,"Kaj la dua anĝelo trumpetis, kaj kvazaŭ granda monto, per fajro brulanta, estis ĵetita en la maron; kaj triono de la maro fariĝis sango;","Kaj la dua anĝelo trumpetis, kaj kvazaŭ granda monto, per fajro brulanta, estis ĵetita en la maron; kaj triono de la maro fariĝis sango;"],[8,9,"kaj mortis triono de la kreitaĵoj en la maro, kiuj havis vivon; kaj triono de la ŝipoj pereis.","kaj mortis triono de la kreitaĵoj en la maro, kiuj havis vivon; kaj triono de la ŝipoj pereis."],[8,10,"Kaj la tria anĝelo trumpetis, kaj falis el la ĉielo granda stelo, brulanta kiel torĉo, kaj ĝi falis sur trionon de la riveroj kaj sur la fontojn de la akvoj;","Kaj la tria anĝelo trumpetis, kaj falis el la ĉielo granda stelo, brulanta kiel torĉo, kaj ĝi falis sur trionon de la riveroj kaj sur la fontojn de la akvoj;"],[8,11,"kaj la nomo de la stelo estas Absinto; kaj triono de la akvoj fariĝis absintaĵo; kaj multe da homoj mortis de la akvoj, ĉar ili maldolĉiĝis.","kaj la nomo de la stelo estas Absinto; kaj triono de la akvoj fariĝis absintaĵo; kaj multe da homoj mortis de la akvoj, ĉar ili maldolĉiĝis."],[8,12,"Kaj la kvara anĝelo trumpetis, kaj estis frapita triono de la suno kaj triono de la luno kaj triono de la steloj, por ke mallumiĝu triono de ili, kaj ke ne lumu dum triono de la tago, kaj por la nokto tiel same.","Kaj la kvara anĝelo trumpetis, kaj estis frapita triono de la suno kaj triono de la luno kaj triono de la steloj, por ke mallumiĝu triono de ili, kaj ke ne lumu dum triono de la tago, kaj por la nokto tiel same."],[8,13,"Kaj mi rigardis, kaj mi aŭdis unu aglon, flugantan en meza ĉielo, dirantan per granda voĉo: Ve! ve! ve al la loĝantoj sur la tero, pro la ceteraj voĉoj trumpetaj de la tri anĝeloj ankoraŭ trumpetontaj!","Kaj mi rigardis, kaj mi aŭdis unu aglon, flugantan en meza ĉielo, dirantan per granda voĉo: Ve! ve! ve al la loĝantoj sur la tero, pro la ceteraj voĉoj trumpetaj de la tri anĝeloj ankoraŭ trumpetontaj!"],[9,1,"Kaj la kvina anĝelo trumpetis, kaj mi vidis stelon el la ĉielo falintan sur la teron; kaj al li estis donita la ŝlosilo de la puto de la abismo.","Kaj la kvina anĝelo trumpetis, kaj mi vidis stelon el la ĉielo falintan sur la teron; kaj al li estis donita la ŝlosilo de la puto de la abismo."],[9,2,"Kaj li malfermis la puton de la abismo; kaj el la puto leviĝadis fumo, kiel fumo el granda forno; kaj mallumiĝis la suno kaj la aero pro la fumo de la puto.","Kaj li malfermis la puton de la abismo; kaj el la puto leviĝadis fumo, kiel fumo el granda forno; kaj mallumiĝis la suno kaj la aero pro la fumo de la puto."],[9,3,"Kaj el la fumo eliris akridoj sur la teron; kaj al ili estis donita povo, kiel havas povon la skorpioj de la tero.","Kaj el la fumo eliris akridoj sur la teron; kaj al ili estis donita povo, kiel havas povon la skorpioj de la tero."],[9,4,"Kaj estis ordonite al ili, ke ili ne difektu la herbon de la tero, nek ian verdaĵon, nek ian arbon, sed nur tiujn homojn, kiuj ne havas sur la frunto la sigelon de Dio.","Kaj estis ordonite al ili, ke ili ne difektu la herbon de la tero, nek ian verdaĵon, nek ian arbon, sed nur tiujn homojn, kiuj ne havas sur la frunto la sigelon de Dio."],[9,5,"Kaj al ili estis komisiite, ke ili ne mortigu ilin, sed ke ili estu turmentataj kvin monatojn; kaj ilia turmento estis kiel turmento de skorpio, kiam ĝi pikvundas homon.","Kaj al ili estis komisiite, ke ili ne mortigu ilin, sed ke ili estu turmentataj kvin monatojn; kaj ilia turmento estis kiel turmento de skorpio, kiam ĝi pikvundas homon."],[9,6,"Kaj en tiuj tagoj la homoj serĉos morton, kaj ĝin tute ne trovos; kaj ili deziregos morti, kaj morto forflugos de ili.","Kaj en tiuj tagoj la homoj serĉos morton, kaj ĝin tute ne trovos; kaj ili deziregos morti, kaj morto forflugos de ili."],[9,7,"Kaj la formoj de la akridoj similis ĉevalojn, pretigitajn por milito; kaj sur iliaj kapoj estis kvazaŭ kronoj similaj al oro, kaj iliaj vizaĝoj estis kiel vizaĝoj de homoj.","Kaj la formoj de la akridoj similis ĉevalojn, pretigitajn por milito; kaj sur iliaj kapoj estis kvazaŭ kronoj similaj al oro, kaj iliaj vizaĝoj estis kiel vizaĝoj de homoj."],[9,8,"Kaj ili havis harojn kiel haroj de virinoj, kaj iliaj dentoj estis kiel de leonoj.","Kaj ili havis harojn kiel haroj de virinoj, kaj iliaj dentoj estis kiel de leonoj."],[9,9,"Kaj ili havis kirasojn, kiel kirasoj el fero; kaj la sono de iliaj flugiloj estis kiel la sono de ĉaroj, de multe da ĉevaloj kurantaj en militon.","Kaj ili havis kirasojn, kiel kirasoj el fero; kaj la sono de iliaj flugiloj estis kiel la sono de ĉaroj, de multe da ĉevaloj kurantaj en militon."],[9,10,"Kaj ili havis vostojn similajn al vostoj de skorpioj, kaj pikilojn; kaj en iliaj vostoj estas ilia kapablo difekti la homojn kvin monatojn.","Kaj ili havis vostojn similajn al vostoj de skorpioj, kaj pikilojn; kaj en iliaj vostoj estas ilia kapablo difekti la homojn kvin monatojn."],[9,11,"Ili havis super si reĝon, la anĝelon de la abismo; lia nomo estas en la Hebrea lingvo Abadon, kaj en la Greka lingvo li havas la nomon Apolion.","Ili havis super si reĝon, la anĝelon de la abismo; lia nomo estas en la Hebrea lingvo Abadon, kaj en la Greka lingvo li havas la nomon Apolion."],[9,12,"La unua Veo jam pasis; jen post tio venas ankoraŭ du Veoj.","La unua Veo jam pasis; jen post tio venas ankoraŭ du Veoj."],[9,13,"Kaj la sesa anĝelo trumpetis, kaj mi aŭdis voĉon el la kornoj de la ora altaro, kiu staras antaŭ Dio,","Kaj la sesa anĝelo trumpetis, kaj mi aŭdis voĉon el la kornoj de la ora altaro, kiu staras antaŭ Dio,"],[9,14,"dirantan al la sesa anĝelo, kiu havis la trumpeton: Malligu la kvar anĝelojn, ligitajn apud la granda rivero Eŭfrato.","dirantan al la sesa anĝelo, kiu havis la trumpeton: Malligu la kvar anĝelojn, ligitajn apud la granda rivero Eŭfrato."],[9,15,"Kaj malligiĝis la kvar anĝeloj, pretigitaj por la horo kaj tago kaj monato kaj jaro, por ke ili mortigu trionon de la homoj.","Kaj malligiĝis la kvar anĝeloj, pretigitaj por la horo kaj tago kaj monato kaj jaro, por ke ili mortigu trionon de la homoj."],[9,16,"Kaj la nombro de la armeoj de la kavalerio estis ducent milionoj; mi aŭdis ilian nombron.","Kaj la nombro de la armeoj de la kavalerio estis ducent milionoj; mi aŭdis ilian nombron."],[9,17,"Kaj tiel mi vidis la ĉevalojn en la vizio, kaj la sidantajn sur ili, havantajn kirasojn kiel el fajro kaj el jacinto kaj el sulfuro; kaj la kapoj de la ĉevaloj estis kiel kapoj de leonoj, kaj el iliaj buŝoj eliris fajro kaj fumo kaj sulfuro.","Kaj tiel mi vidis la ĉevalojn en la vizio, kaj la sidantajn sur ili, havantajn kirasojn kiel el fajro kaj el jacinto kaj el sulfuro; kaj la kapoj de la ĉevaloj estis kiel kapoj de leonoj, kaj el iliaj buŝoj eliris fajro kaj fumo kaj sulfuro."],[9,18,"Per tiuj tri plagoj triono de la homoj estis mortigita, per la fajro kaj la fumo kaj la sulfuro elirantaj el iliaj buŝoj.","Per tiuj tri plagoj triono de la homoj estis mortigita, per la fajro kaj la fumo kaj la sulfuro elirantaj el iliaj buŝoj."],[9,19,"Ĉar la kapablo de la ĉevaloj estas en iliaj buŝoj kaj en iliaj vostoj; ĉar iliaj vostoj similas serpentojn kaj havas kapojn; kaj per ĉi tiuj ili vundas.","Ĉar la kapablo de la ĉevaloj estas en iliaj buŝoj kaj en iliaj vostoj; ĉar iliaj vostoj similas serpentojn kaj havas kapojn; kaj per ĉi tiuj ili vundas."],[9,20,"Kaj la ceteraj homoj, kiuj ne estis mortigitaj per tiuj plagoj, ne pentis pri la faroj de siaj manoj, por ne adorkliniĝi al demonoj, kaj al la idoloj oraj kaj arĝentaj kaj kupraj kaj ŝtonaj kaj lignaj, kiuj povas nek vidi, nek aŭdi, nek marŝi;","Kaj la ceteraj homoj, kiuj ne estis mortigitaj per tiuj plagoj, ne pentis pri la faroj de siaj manoj, por ne adorkliniĝi al demonoj, kaj al la idoloj oraj kaj arĝentaj kaj kupraj kaj ŝtonaj kaj lignaj, kiuj povas nek vidi, nek aŭdi, nek marŝi;"],[9,21,"kaj ili ne pentis pri siaj mortigoj, nek pri siaj sorĉoj, nek pri sia malĉastado, nek pri siaj ŝteloj.","kaj ili ne pentis pri siaj mortigoj, nek pri siaj sorĉoj, nek pri sia malĉastado, nek pri siaj ŝteloj."],[10,1,"Kaj mi vidis alian fortan anĝelon, malsuprenirantan el la ĉielo, vestitan per nubo; kaj la ĉielarko estis super lia kapo, kaj lia vizaĝo estis kiel la suno, kaj liaj piedoj kiel kolonoj el fajro;","Kaj mi vidis alian fortan anĝelon, malsuprenirantan el la ĉielo, vestitan per nubo; kaj la ĉielarko estis super lia kapo, kaj lia vizaĝo estis kiel la suno, kaj liaj piedoj kiel kolonoj el fajro;"],[10,2,"kaj li havis en la mano libreton malfermitan; kaj li metis la dekstran piedon sur la maron, kaj la maldekstran sur la teron;","kaj li havis en la mano libreton malfermitan; kaj li metis la dekstran piedon sur la maron, kaj la maldekstran sur la teron;"],[10,3,"kaj li ekkriis per granda voĉo, kiel leono blekas; kaj kiam li kriis, la sep tondroj parolis per siaj voĉoj.","kaj li ekkriis per granda voĉo, kiel leono blekas; kaj kiam li kriis, la sep tondroj parolis per siaj voĉoj."],[10,4,"Kaj kiam la sep tondroj parolis, mi volis skribi; kaj mi aŭdis voĉon el la ĉielo, dirantan: Sigelu tion, kion parolis la sep tondroj, kaj ĝin ne skribu.","Kaj kiam la sep tondroj parolis, mi volis skribi; kaj mi aŭdis voĉon el la ĉielo, dirantan: Sigelu tion, kion parolis la sep tondroj, kaj ĝin ne skribu."],[10,5,"Kaj la anĝelo, kiun mi vidis staranta sur la maro kaj sur la tero, levis sian dekstran manon al la ĉielo,","Kaj la anĝelo, kiun mi vidis staranta sur la maro kaj sur la tero, levis sian dekstran manon al la ĉielo,"],[10,6,"kaj ĵuris per la Vivanto por ĉiam kaj eterne, kiu kreis la ĉielon kaj tion, kio estas en ĝi, kaj la teron kaj tion, kio estas en ĝi, kaj la maron kaj tion, kio estas en ĝi, ke tempo ne plu ekzistos;","kaj ĵuris per la Vivanto por ĉiam kaj eterne, kiu kreis la ĉielon kaj tion, kio estas en ĝi, kaj la teron kaj tion, kio estas en ĝi, kaj la maron kaj tion, kio estas en ĝi, ke tempo ne plu ekzistos;"],[10,7,"sed en la tagoj de la voĉo de la sepa anĝelo, kiam li tuj trumpetos, tiam finiĝos la mistero de Dio, kiel Li evangeliis al Siaj servistoj, la profetoj.","sed en la tagoj de la voĉo de la sepa anĝelo, kiam li tuj trumpetos, tiam finiĝos la mistero de Dio, kiel Li evangeliis al Siaj servistoj, la profetoj."],[10,8,"Kaj la voĉo, kiun mi aŭdis el la ĉielo, parolis al mi denove, dirante: Iru, prenu la libreton malfermitan en la mano de la anĝelo, staranta sur la maro kaj sur la tero.","Kaj la voĉo, kiun mi aŭdis el la ĉielo, parolis al mi denove, dirante: Iru, prenu la libreton malfermitan en la mano de la anĝelo, staranta sur la maro kaj sur la tero."],[10,9,"Kaj mi iris al la anĝelo, kaj diris al li: Donu al mi la libreton. Kaj li diris al mi: Prenu ĝin, kaj formanĝu ĝin; kaj ĝi maldolĉigos al vi la ventron, sed en via buŝo ĝi estos dolĉa kiel mielo.","Kaj mi iris al la anĝelo, kaj diris al li: Donu al mi la libreton. Kaj li diris al mi: Prenu ĝin, kaj formanĝu ĝin; kaj ĝi maldolĉigos al vi la ventron, sed en via buŝo ĝi estos dolĉa kiel mielo."],[10,10,"Kaj mi prenis la libreton el la mano de la anĝelo, kaj formanĝis ĝin; kaj en mia buŝo ĝi estis dolĉa kiel mielo, kaj kiam mi ĝin manĝis, mia ventro maldolĉiĝis.","Kaj mi prenis la libreton el la mano de la anĝelo, kaj formanĝis ĝin; kaj en mia buŝo ĝi estis dolĉa kiel mielo, kaj kiam mi ĝin manĝis, mia ventro maldolĉiĝis."],[10,11,"Kaj ili diris al mi: Vi devas denove profeti ĉe multaj popoloj kaj nacioj kaj lingvoj kaj reĝoj.","Kaj ili diris al mi: Vi devas denove profeti ĉe multaj popoloj kaj nacioj kaj lingvoj kaj reĝoj."],[11,1,"Kaj estis donita al mi kano, simila al bastono; kaj iu diris: Leviĝu, kaj mezuru la templon de Dio, kaj la altaron, kaj la adorantojn en ĝi.","Kaj estis donita al mi kano, simila al bastono; kaj iu diris: Leviĝu, kaj mezuru la templon de Dio, kaj la altaron, kaj la adorantojn en ĝi."],[11,2,"Kaj la korton ekster la templo preterlasu, kaj ne mezuru ĝin, ĉar ĝi estas donita al la nacioj; kaj la sanktan urbon ili piedpremos kvardek du monatojn.","Kaj la korton ekster la templo preterlasu, kaj ne mezuru ĝin, ĉar ĝi estas donita al la nacioj; kaj la sanktan urbon ili piedpremos kvardek du monatojn."],[11,3,"Kaj mi donos komision al miaj du atestantoj, kaj ili profetos mil ducent sesdek tagojn, vestite per sakaĵo.","Kaj mi donos komision al miaj du atestantoj, kaj ili profetos mil ducent sesdek tagojn, vestite per sakaĵo."],[11,4,"Ili estas la du olivarboj kaj la du lampingoj, starantaj antaŭ la Sinjoro de la tero.","Ili estas la du olivarboj kaj la du lampingoj, starantaj antaŭ la Sinjoro de la tero."],[11,5,"Kaj se iu volas difekti ilin, fajro elvenas el ilia buŝo kaj formanĝas iliajn malamikojn; kaj se iu volas difekti ilin, tiamaniere li devas esti mortigita.","Kaj se iu volas difekti ilin, fajro elvenas el ilia buŝo kaj formanĝas iliajn malamikojn; kaj se iu volas difekti ilin, tiamaniere li devas esti mortigita."],[11,6,"Ili havas la povon fermi la ĉielon, por ke ne pluvu dum la tagoj de ilia profetado; kaj ili havas povon super la akvoj, por ŝanĝi ilin en sangon, kaj frapi la teron per ĉia plago ĉiufoje, kiam ili volos.","Ili havas la povon fermi la ĉielon, por ke ne pluvu dum la tagoj de ilia profetado; kaj ili havas povon super la akvoj, por ŝanĝi ilin en sangon, kaj frapi la teron per ĉia plago ĉiufoje, kiam ili volos."],[11,7,"Kaj kiam ili finos sian ateston, la besto, kiu suprenvenas el la abismo, faros militon kontraŭ ili kaj venkos ilin kaj mortigos ilin.","Kaj kiam ili finos sian ateston, la besto, kiu suprenvenas el la abismo, faros militon kontraŭ ili kaj venkos ilin kaj mortigos ilin."],[11,8,"Kaj iliaj kadavroj kuŝas sur la strato de la granda urbo, kiu nomiĝas laŭspirite Sodom kaj Egiptujo, kie ankaŭ ilia Sinjoro estis krucumita.","Kaj iliaj kadavroj kuŝas sur la strato de la granda urbo, kiu nomiĝas laŭspirite Sodom kaj Egiptujo, kie ankaŭ ilia Sinjoro estis krucumita."],[11,9,"Kaj el la popoloj kaj triboj kaj lingvoj kaj nacioj oni rigardas iliajn kadavrojn dum tri tagoj kaj duono, kaj ne lasas meti iliajn kadavrojn en tombon.","Kaj el la popoloj kaj triboj kaj lingvoj kaj nacioj oni rigardas iliajn kadavrojn dum tri tagoj kaj duono, kaj ne lasas meti iliajn kadavrojn en tombon."],[11,10,"Kaj la loĝantoj sur la tero ĝojas pri ili, kaj gajiĝas; kaj ili sendos donacojn unu al la alia; ĉar tiuj du profetoj turmentadis la loĝantojn sur la tero.","Kaj la loĝantoj sur la tero ĝojas pri ili, kaj gajiĝas; kaj ili sendos donacojn unu al la alia; ĉar tiuj du profetoj turmentadis la loĝantojn sur la tero."],[11,11,"Kaj post la tri tagoj kaj duono la spirito de vivo el Dio eniris en ilin, kaj ili stariĝis sur siaj piedoj; kaj granda timo falis sur tiujn, kiuj ilin rigardis.","Kaj post la tri tagoj kaj duono la spirito de vivo el Dio eniris en ilin, kaj ili stariĝis sur siaj piedoj; kaj granda timo falis sur tiujn, kiuj ilin rigardis."],[11,12,"Kaj ili aŭdis grandan voĉon el la ĉielo, dirantan al ili: Suprenvenu ĉi tien. Kaj ili supreniris en la ĉielon en la nubo; kaj iliaj malamikoj rigardis ilin.","Kaj ili aŭdis grandan voĉon el la ĉielo, dirantan al ili: Suprenvenu ĉi tien. Kaj ili supreniris en la ĉielon en la nubo; kaj iliaj malamikoj rigardis ilin."],[11,13,"Kaj en tiu horo fariĝis granda tertremo, kaj dekono de la urbo falis; kaj en la tertremo mortis sep mil homoj; kaj la ceteraj pleniĝis de timo, kaj donis laŭdon al la Dio de la ĉielo.","Kaj en tiu horo fariĝis granda tertremo, kaj dekono de la urbo falis; kaj en la tertremo mortis sep mil homoj; kaj la ceteraj pleniĝis de timo, kaj donis laŭdon al la Dio de la ĉielo."],[11,14,"La dua Veo jam pasis; jen la tria Veo rapide venas.","La dua Veo jam pasis; jen la tria Veo rapide venas."],[11,15,"Kaj la sepa anĝelo trumpetis; kaj fariĝis grandaj voĉoj en la ĉielo, dirante: La regno de la mondo fariĝis regno de nia Sinjoro kaj de Lia Kristo; kaj li reĝos por ĉiam kaj eterne.","Kaj la sepa anĝelo trumpetis; kaj fariĝis grandaj voĉoj en la ĉielo, dirante: La regno de la mondo fariĝis regno de nia Sinjoro kaj de Lia Kristo; kaj li reĝos por ĉiam kaj eterne."],[11,16,"Kaj la dudek kvar presbiteroj, kiuj antaŭ Dio sidas sur siaj tronoj, falis sur la vizaĝon kaj adorkliniĝis al Dio,","Kaj la dudek kvar presbiteroj, kiuj antaŭ Dio sidas sur siaj tronoj, falis sur la vizaĝon kaj adorkliniĝis al Dio,"],[11,17,"dirante: Ni dankas Vin, ho Dio, la Sinjoro, la Plejpotenca, kiu estas kaj estis; ĉar Vi alprenis Vian grandan potencon kaj reĝis.","dirante: Ni dankas Vin, ho Dio, la Sinjoro, la Plejpotenca, kiu estas kaj estis; ĉar Vi alprenis Vian grandan potencon kaj reĝis."],[11,18,"Kaj la nacioj furiozis, kaj venis Via kolero, kaj la tempo de la mortintoj, por esti juĝataj, kaj la tempo doni la rekompencon al Viaj servistoj, la profetoj, kaj al la sanktuloj, kaj al la timantoj de Via nomo, malgrandaj kaj grandaj, kaj pereigi la detruantojn de la tero.","Kaj la nacioj furiozis, kaj venis Via kolero, kaj la tempo de la mortintoj, por esti juĝataj, kaj la tempo doni la rekompencon al Viaj servistoj, la profetoj, kaj al la sanktuloj, kaj al la timantoj de Via nomo, malgrandaj kaj grandaj, kaj pereigi la detruantojn de la tero."],[11,19,"Kaj malfermiĝis la enĉiela templo de Dio, kaj vidiĝis en Lia templo la kesto de Lia interligo; kaj fariĝis fulmoj kaj voĉoj kaj tondroj kaj tertremo kaj granda hajlo.","Kaj malfermiĝis la enĉiela templo de Dio, kaj vidiĝis en Lia templo la kesto de Lia interligo; kaj fariĝis fulmoj kaj voĉoj kaj tondroj kaj tertremo kaj granda hajlo."],[12,1,"Kaj granda signo vidiĝis en la ĉielo: virino vestita per la suno, kaj la luno sub ŝiaj piedoj, kaj sur ŝia kapo krono el dek du steloj;","Kaj granda signo vidiĝis en la ĉielo: virino vestita per la suno, kaj la luno sub ŝiaj piedoj, kaj sur ŝia kapo krono el dek du steloj;"],[12,2,"kaj estante graveda, ŝi ekkriis, naskodolorigate kaj suferante por naski.","kaj estante graveda, ŝi ekkriis, naskodolorigate kaj suferante por naski."],[12,3,"Kaj vidiĝis alia signo en la ĉielo; kaj jen granda ruĝa drako, havanta sep kapojn kaj dek kornojn, kaj sur siaj kapoj sep diademojn.","Kaj vidiĝis alia signo en la ĉielo; kaj jen granda ruĝa drako, havanta sep kapojn kaj dek kornojn, kaj sur siaj kapoj sep diademojn."],[12,4,"Kaj ĝia vosto trenis trionon de la steloj de la ĉielo, kaj ĵetis ilin sur la teron; kaj la drako staris antaŭ la virino naskonta, por ke, kiam ŝi estos naskinta, ĝi formanĝu ŝian infanon.","Kaj ĝia vosto trenis trionon de la steloj de la ĉielo, kaj ĵetis ilin sur la teron; kaj la drako staris antaŭ la virino naskonta, por ke, kiam ŝi estos naskinta, ĝi formanĝu ŝian infanon."],[12,5,"Kaj ŝi naskis filon, viran infanon, kiu regos ĉiujn naciojn per fera sceptro; kaj ŝia infano estis forkaptita supren al Dio kaj al Lia trono.","Kaj ŝi naskis filon, viran infanon, kiu regos ĉiujn naciojn per fera sceptro; kaj ŝia infano estis forkaptita supren al Dio kaj al Lia trono."],[12,6,"Kaj la virino forkuris en la dezerton, kie ŝi havis lokon pretigitan de Dio, por ke tie oni nutru ŝin mil ducent sesdek tagojn.","Kaj la virino forkuris en la dezerton, kie ŝi havis lokon pretigitan de Dio, por ke tie oni nutru ŝin mil ducent sesdek tagojn."],[12,7,"Kaj fariĝis milito en la ĉielo: Miĥael kaj liaj anĝeloj ekmilitis kontraŭ la drako; kaj militis la drako kaj ĝiaj anĝeloj;","Kaj fariĝis milito en la ĉielo: Miĥael kaj liaj anĝeloj ekmilitis kontraŭ la drako; kaj militis la drako kaj ĝiaj anĝeloj;"],[12,8,"kaj ne prosperis al ili, kaj ne plu troviĝis ilia loko en la ĉielo.","kaj ne prosperis al ili, kaj ne plu troviĝis ilia loko en la ĉielo."],[12,9,"Kaj ĵetiĝis malsupren la granda drako, la antikva serpento, nomata Diablo kaj Satano, la trompanto de la tuta mondo; ĝi ĵetiĝis sur la teron, kaj ĝiaj anĝeloj ĵetiĝis kun ĝi.","Kaj ĵetiĝis malsupren la granda drako, la antikva serpento, nomata Diablo kaj Satano, la trompanto de la tuta mondo; ĝi ĵetiĝis sur la teron, kaj ĝiaj anĝeloj ĵetiĝis kun ĝi."],[12,10,"Kaj mi aŭdis grandan voĉon en la ĉielo, dirantan: Nun fariĝis la savo kaj la potenco kaj la reĝeco de nia Dio, kaj la aŭtoritato de Lia Kristo; ĉar ĵetiĝis malsupren la akuzanto de niaj fratoj, kiu tage kaj nokte akuzas ilin antaŭ nia Dio.","Kaj mi aŭdis grandan voĉon en la ĉielo, dirantan: Nun fariĝis la savo kaj la potenco kaj la reĝeco de nia Dio, kaj la aŭtoritato de Lia Kristo; ĉar ĵetiĝis malsupren la akuzanto de niaj fratoj, kiu tage kaj nokte akuzas ilin antaŭ nia Dio."],[12,11,"Kaj ili venkis ĝin pro la sango de la Ŝafido, kaj pro la vorto de sia atesto; kaj ili ne amis sian vivon ĝis morto mem.","Kaj ili venkis ĝin pro la sango de la Ŝafido, kaj pro la vorto de sia atesto; kaj ili ne amis sian vivon ĝis morto mem."],[12,12,"Pro tio ĝoju, ho ĉieloj, kaj vi, kiuj en ili loĝas. Ve al la tero kaj al la maro! ĉar la diablo malsupreniris en vin, havante grandan koleron, sciante, ke li havas nur mallongan tempon.","Pro tio ĝoju, ho ĉieloj, kaj vi, kiuj en ili loĝas. Ve al la tero kaj al la maro! ĉar la diablo malsupreniris en vin, havante grandan koleron, sciante, ke li havas nur mallongan tempon."],[12,13,"Kaj kiam la drako vidis, ke ĝi estas ĵetita sur la teron, ĝi persekutis la virinon, kiu naskis la viran infanon.","Kaj kiam la drako vidis, ke ĝi estas ĵetita sur la teron, ĝi persekutis la virinon, kiu naskis la viran infanon."],[12,14,"Kaj al la virino estis donitaj la du flugiloj de la granda aglo, por ke ŝi flugu en la dezerton, sur sian lokon, kie ŝi estas nutrata tempon kaj tempojn kaj duontempon, for de la vizaĝo de la serpento.","Kaj al la virino estis donitaj la du flugiloj de la granda aglo, por ke ŝi flugu en la dezerton, sur sian lokon, kie ŝi estas nutrata tempon kaj tempojn kaj duontempon, for de la vizaĝo de la serpento."],[12,15,"Kaj la serpento elĵetis el sia buŝo, post la virinon, akvon kvazaŭ riveron, por ke ĝi igu ŝin forportiĝi de la fluo.","Kaj la serpento elĵetis el sia buŝo, post la virinon, akvon kvazaŭ riveron, por ke ĝi igu ŝin forportiĝi de la fluo."],[12,16,"Kaj la tero helpis la virinon, kaj la tero malfermis sian buŝon, kaj englutis la riveron, kiun la drako elĵetis el sia buŝo.","Kaj la tero helpis la virinon, kaj la tero malfermis sian buŝon, kaj englutis la riveron, kiun la drako elĵetis el sia buŝo."],[12,17,"Kaj la drako furiozis kontraŭ la virino, kaj foriris, por fari militon kontraŭ la restintojn de ŝia idaro, kiuj observas la ordonojn de Dio kaj havas la ateston de Jesuo;","Kaj la drako furiozis kontraŭ la virino, kaj foriris, por fari militon kontraŭ la restintojn de ŝia idaro, kiuj observas la ordonojn de Dio kaj havas la ateston de Jesuo;"],[13,1,"kaj ĝi staris sur la sablo de la maro. Kaj mi vidis beston suprenirantan el la maro, havantan dek kornojn kaj sep kapojn, kaj sur siaj kornoj dek diademojn, kaj sur siaj kapoj nomojn de blasfemo.","kaj ĝi staris sur la sablo de la maro. Kaj mi vidis beston suprenirantan el la maro, havantan dek kornojn kaj sep kapojn, kaj sur siaj kornoj dek diademojn, kaj sur siaj kapoj nomojn de blasfemo."],[13,2,"Kaj la besto, kiun mi vidis, estis simila al leopardo, kaj ĝiaj piedoj estis kiel de urso, kaj ĝia buŝo kiel buŝo de leono; kaj la drako donis al ĝi sian potencon kaj sian tronon kaj grandan aŭtoritaton.","Kaj la besto, kiun mi vidis, estis simila al leopardo, kaj ĝiaj piedoj estis kiel de urso, kaj ĝia buŝo kiel buŝo de leono; kaj la drako donis al ĝi sian potencon kaj sian tronon kaj grandan aŭtoritaton."],[13,3,"Kaj mi vidis unu el ĝiaj kapoj kvazaŭ morte vunditan; kaj la morta vundo saniĝis; kaj la tuta tero miris post la besto;","Kaj mi vidis unu el ĝiaj kapoj kvazaŭ morte vunditan; kaj la morta vundo saniĝis; kaj la tuta tero miris post la besto;"],[13,4,"kaj ili adorkliniĝis al la drako, ĉar ĝi donis sian aŭtoritaton al la besto; kaj ili adorkliniĝis al la besto, dirante: Kiu estas simila al la besto? kaj kiu povas militi kontraŭ ĝi?","kaj ili adorkliniĝis al la drako, ĉar ĝi donis sian aŭtoritaton al la besto; kaj ili adorkliniĝis al la besto, dirante: Kiu estas simila al la besto? kaj kiu povas militi kontraŭ ĝi?"],[13,5,"kaj estis donita al ĝi buŝo, parolanta grandaĵojn kaj blasfemaĵojn; kaj estis donita al ĝi aŭtoritato agadi dum kvardek du monatoj.","kaj estis donita al ĝi buŝo, parolanta grandaĵojn kaj blasfemaĵojn; kaj estis donita al ĝi aŭtoritato agadi dum kvardek du monatoj."],[13,6,"Kaj ĝi malfermis la buŝon por blasfemoj kontraŭ Dio, por blasfemi Lian nomon kaj Lian tabernaklon kaj la loĝantojn de la ĉielo.","Kaj ĝi malfermis la buŝon por blasfemoj kontraŭ Dio, por blasfemi Lian nomon kaj Lian tabernaklon kaj la loĝantojn de la ĉielo."],[13,7,"Kaj estis donite al ĝi fari militon kontraŭ la sanktuloj, kaj venki ilin; kaj estis donita al ĝi aŭtoritato sur ĉiu tribo kaj popolo kaj lingvo kaj nacio.","Kaj estis donite al ĝi fari militon kontraŭ la sanktuloj, kaj venki ilin; kaj estis donita al ĝi aŭtoritato sur ĉiu tribo kaj popolo kaj lingvo kaj nacio."],[13,8,"Kaj adorkliniĝos al ĝi ĉiuj loĝantoj de la tero, kies nomo ne estas skribita en la libro de vivo, libro de la Ŝafido oferita jam de la fondo de la mondo.","Kaj adorkliniĝos al ĝi ĉiuj loĝantoj de la tero, kies nomo ne estas skribita en la libro de vivo, libro de la Ŝafido oferita jam de la fondo de la mondo."],[13,9,"Se iu havas orelon, tiu aŭskultu.","Se iu havas orelon, tiu aŭskultu."],[13,10,"Se iu malliberigas, en malliberecon li iras; se iu per la glavo mortigos, li devas per la glavo esti mortigita. Ĉi tie estas la pacienco kaj la fido de la sanktuloj.","Se iu malliberigas, en malliberecon li iras; se iu per la glavo mortigos, li devas per la glavo esti mortigita. Ĉi tie estas la pacienco kaj la fido de la sanktuloj."],[13,11,"Kaj mi vidis alian beston suprenirantan el la tero; kaj ĝi havis du kornojn, simile al ŝafido, kaj ĝi parolis kiel drako.","Kaj mi vidis alian beston suprenirantan el la tero; kaj ĝi havis du kornojn, simile al ŝafido, kaj ĝi parolis kiel drako."],[13,12,"Kaj ĝi ekzercas la tutan aŭtoritaton de la unua besto antaŭ ĝi. Kaj ĝi devigas la teron kaj la loĝantojn sur ĝi adorkliniĝi al la unua besto, kies morta vundo saniĝis.","Kaj ĝi ekzercas la tutan aŭtoritaton de la unua besto antaŭ ĝi. Kaj ĝi devigas la teron kaj la loĝantojn sur ĝi adorkliniĝi al la unua besto, kies morta vundo saniĝis."],[13,13,"Kaj ĝi faras grandajn signojn, devigante eĉ fajron malsupreniri el la ĉielo sur la teron antaŭ la homoj.","Kaj ĝi faras grandajn signojn, devigante eĉ fajron malsupreniri el la ĉielo sur la teron antaŭ la homoj."],[13,14,"Kaj ĝi trompas la loĝantojn de la tero per la signoj, kiujn estis donite al ĝi fari antaŭ la besto; dirante al la loĝantoj sur la tero, ke ili faru bildon al la besto, kiu havis la glavovundon kaj vivis.","Kaj ĝi trompas la loĝantojn de la tero per la signoj, kiujn estis donite al ĝi fari antaŭ la besto; dirante al la loĝantoj sur la tero, ke ili faru bildon al la besto, kiu havis la glavovundon kaj vivis."],[13,15,"Kaj estis donite, ke ĝi donu spiron al la bildo de la besto, por ke eĉ parolu la bildo de la besto, kaj faru, ke ĉiuj, kiuj ne volas adorkliniĝi al la bildo de la besto, estu mortigitaj.","Kaj estis donite, ke ĝi donu spiron al la bildo de la besto, por ke eĉ parolu la bildo de la besto, kaj faru, ke ĉiuj, kiuj ne volas adorkliniĝi al la bildo de la besto, estu mortigitaj."],[13,16,"Kaj ĝi devigas ĉiujn, la malgrandajn kaj la grandajn, la riĉajn kaj la malriĉajn, la liberajn kaj la sklavajn, ricevi markon sur la dekstra mano aŭ sur la frunto;","Kaj ĝi devigas ĉiujn, la malgrandajn kaj la grandajn, la riĉajn kaj la malriĉajn, la liberajn kaj la sklavajn, ricevi markon sur la dekstra mano aŭ sur la frunto;"],[13,17,"por ke neniu povu aĉeti aŭ vendi, krom tiuj, kiuj havas la markon, la nomon de la besto, aŭ la numeron de ĝia nomo.","por ke neniu povu aĉeti aŭ vendi, krom tiuj, kiuj havas la markon, la nomon de la besto, aŭ la numeron de ĝia nomo."],[13,18,"Ĉi tie estas saĝeco. Kiu havas prudenton, tiu kalkulu la numeron de la besto; ĉar ĝi estas la numero de homo; kaj ĝia numero estas sescent sesdek ses.","Ĉi tie estas saĝeco. Kiu havas prudenton, tiu kalkulu la numeron de la besto; ĉar ĝi estas la numero de homo; kaj ĝia numero estas sescent sesdek ses."],[14,1,"Kaj mi rigardis, kaj jen la Ŝafido staranta sur la monto Cion, kaj kun li cent kvardek kvar miloj, havantaj lian nomon, kaj la nomon de lia Patro, skribitajn sur ilia frunto.","Kaj mi rigardis, kaj jen la Ŝafido staranta sur la monto Cion, kaj kun li cent kvardek kvar miloj, havantaj lian nomon, kaj la nomon de lia Patro, skribitajn sur ilia frunto."],[14,2,"Kaj mi aŭdis voĉon el la ĉielo, kiel voĉon de multaj akvoj, kaj kiel voĉon de granda tondro; kaj la voĉo, kiun mi aŭdis, estis kiel de harpistoj, harpantaj per siaj harpoj;","Kaj mi aŭdis voĉon el la ĉielo, kiel voĉon de multaj akvoj, kaj kiel voĉon de granda tondro; kaj la voĉo, kiun mi aŭdis, estis kiel de harpistoj, harpantaj per siaj harpoj;"],[14,3,"kaj ili kantas kvazaŭ novan kanton antaŭ la trono kaj antaŭ la kvar kreitaĵoj kaj la presbiteroj; kaj neniu povis lerni la kanton krom la cent kvardek kvar miloj, la elaĉetitoj el la tero.","kaj ili kantas kvazaŭ novan kanton antaŭ la trono kaj antaŭ la kvar kreitaĵoj kaj la presbiteroj; kaj neniu povis lerni la kanton krom la cent kvardek kvar miloj, la elaĉetitoj el la tero."],[14,4,"Ili estas tiuj, kiuj ne malpuriĝis kun virinoj; ĉar ili estas virguloj. Ili estas la sekvantoj de la Ŝafido, kien ajn li iras. Ili estas elaĉetitaj el inter la homoj, la unuaaĵo al Dio kaj al la Ŝafido.","Ili estas tiuj, kiuj ne malpuriĝis kun virinoj; ĉar ili estas virguloj. Ili estas la sekvantoj de la Ŝafido, kien ajn li iras. Ili estas elaĉetitaj el inter la homoj, la unuaaĵo al Dio kaj al la Ŝafido."],[14,5,"Kaj en ilia buŝo ne troviĝis mensogo; ili estas senkulpaj.","Kaj en ilia buŝo ne troviĝis mensogo; ili estas senkulpaj."],[14,6,"Kaj mi vidis alian anĝelon, flugantan en meza ĉielo, havantan eternan evangelion, por evangelii la loĝantojn de la tero kaj ĉiun nacion kaj tribon kaj lingvon kaj popolon,","Kaj mi vidis alian anĝelon, flugantan en meza ĉielo, havantan eternan evangelion, por evangelii la loĝantojn de la tero kaj ĉiun nacion kaj tribon kaj lingvon kaj popolon,"],[14,7,"kaj dirantan per granda voĉo: Timu Dion, kaj donu al Li gloron, ĉar venis la horo de Lia juĝo; kaj adorkliniĝu al la Kreinto de la ĉielo kaj la tero kaj la maro kaj la fontoj akvaj.","kaj dirantan per granda voĉo: Timu Dion, kaj donu al Li gloron, ĉar venis la horo de Lia juĝo; kaj adorkliniĝu al la Kreinto de la ĉielo kaj la tero kaj la maro kaj la fontoj akvaj."],[14,8,"Kaj alia anĝelo, dua, sekvis, dirante: Falis, falis Babel la granda, kiu trinkigis ĉiujn naciojn el la vino de la kolero de ŝia malĉastaĵo.","Kaj alia anĝelo, dua, sekvis, dirante: Falis, falis Babel la granda, kiu trinkigis ĉiujn naciojn el la vino de la kolero de ŝia malĉastaĵo."],[14,9,"Kaj alia anĝelo, tria, sekvis ilin, dirante per granda voĉo: Se iu adorkliniĝas al la besto kaj al ĝia bildo, kaj ricevas markon sur sia frunto aŭ sur sia mano,","Kaj alia anĝelo, tria, sekvis ilin, dirante per granda voĉo: Se iu adorkliniĝas al la besto kaj al ĝia bildo, kaj ricevas markon sur sia frunto aŭ sur sia mano,"],[14,10,"tiu ankaŭ trinkos el la vino de la kolero de Dio, kiu estas pretigita nemiksite en la pokalo de Lia kolero, kaj li turmentiĝos en fajro kaj sulfuro antaŭ la sanktaj anĝeloj kaj antaŭ la Ŝafido;","tiu ankaŭ trinkos el la vino de la kolero de Dio, kiu estas pretigita nemiksite en la pokalo de Lia kolero, kaj li turmentiĝos en fajro kaj sulfuro antaŭ la sanktaj anĝeloj kaj antaŭ la Ŝafido;"],[14,11,"kaj la fumo de ilia turmento leviĝas por ĉiam kaj eterne; kaj ne havas paŭzon tage kaj nokte tiuj, kiuj adorkliniĝas al la besto kaj al ĝia bildo, kaj ĉiu, kiu ricevas la markon de ĝia nomo.","kaj la fumo de ilia turmento leviĝas por ĉiam kaj eterne; kaj ne havas paŭzon tage kaj nokte tiuj, kiuj adorkliniĝas al la besto kaj al ĝia bildo, kaj ĉiu, kiu ricevas la markon de ĝia nomo."],[14,12,"Ĉi tie estas la pacienco de la sanktuloj, kiuj observas la ordonojn de Dio kaj la fidon de Jesuo.","Ĉi tie estas la pacienco de la sanktuloj, kiuj observas la ordonojn de Dio kaj la fidon de Jesuo."],[14,13,"Kaj mi aŭdis voĉon el la ĉielo, dirantan: Skribu: Feliĉaj estas la mortintoj, kiuj de nun mortas en la Sinjoro; vere, diras la Spirito, por ke ili ripozu de siaj laboroj; ĉar iliaj faroj sekvas kun ili.","Kaj mi aŭdis voĉon el la ĉielo, dirantan: Skribu: Feliĉaj estas la mortintoj, kiuj de nun mortas en la Sinjoro; vere, diras la Spirito, por ke ili ripozu de siaj laboroj; ĉar iliaj faroj sekvas kun ili."],[14,14,"Kaj mi rigardis, kaj jen blanka nubo, kaj sur la nubo sidanto, simila al la Filo de homo, havanta sur sia kapo oran kronon, kaj en sia mano akran rikoltilon.","Kaj mi rigardis, kaj jen blanka nubo, kaj sur la nubo sidanto, simila al la Filo de homo, havanta sur sia kapo oran kronon, kaj en sia mano akran rikoltilon."],[14,15,"Kaj alia anĝelo eliris el la templo, kriante per granda voĉo al la sidanta sur la nubo: Sendu vian rikoltilon, kaj rikoltu; ĉar venis la horo por rikolti, ĉar la rikolto de la tero tromaturiĝis.","Kaj alia anĝelo eliris el la templo, kriante per granda voĉo al la sidanta sur la nubo: Sendu vian rikoltilon, kaj rikoltu; ĉar venis la horo por rikolti, ĉar la rikolto de la tero tromaturiĝis."],[14,16,"Kaj la sidanta sur la nubo ĵetis sian rikoltilon sur la teron; kaj la tero rikoltiĝis.","Kaj la sidanta sur la nubo ĵetis sian rikoltilon sur la teron; kaj la tero rikoltiĝis."],[14,17,"Kaj alia anĝelo eliris el la enĉiela templo, ankaŭ havante akran rikoltilon.","Kaj alia anĝelo eliris el la enĉiela templo, ankaŭ havante akran rikoltilon."],[14,18,"Kaj alia anĝelo eliris el la altaro, havante aŭtoritaton super la fajro; kaj li kriis per granda voĉo al la portanto de la akra rikoltilo, dirante: Sendu vian akran rikoltilon, kaj detranĉu la vinberarojn de la vinberarbo de la tero; ĉar tute maturiĝis ĝiaj vinberoj.","Kaj alia anĝelo eliris el la altaro, havante aŭtoritaton super la fajro; kaj li kriis per granda voĉo al la portanto de la akra rikoltilo, dirante: Sendu vian akran rikoltilon, kaj detranĉu la vinberarojn de la vinberarbo de la tero; ĉar tute maturiĝis ĝiaj vinberoj."],[14,19,"Kaj la anĝelo ĵetis sian rikoltilon en la teron kaj detranĉis la vinberarbon de la tero kaj ĵetis ĝin en la grandan vinpremilon de la kolero de Dio.","Kaj la anĝelo ĵetis sian rikoltilon en la teron kaj detranĉis la vinberarbon de la tero kaj ĵetis ĝin en la grandan vinpremilon de la kolero de Dio."],[14,20,"Kaj la vinpremilo estis tretita ekster la urbo, kaj eliris sango el la vinpremilo, ĝis la bridoj de la ĉevaloj, en la spaco de mil sescent stadioj.","Kaj la vinpremilo estis tretita ekster la urbo, kaj eliris sango el la vinpremilo, ĝis la bridoj de la ĉevaloj, en la spaco de mil sescent stadioj."],[15,1,"Kaj mi vidis alian signon en la ĉielo, grandan kaj mirindan: sep anĝelojn havantajn sep plagojn, la finajn, ĉar en ili finiĝis la kolero de Dio.","Kaj mi vidis alian signon en la ĉielo, grandan kaj mirindan: sep anĝelojn havantajn sep plagojn, la finajn, ĉar en ili finiĝis la kolero de Dio."],[15,2,"Kaj mi vidis kvazaŭ vitran maron, miksitan kun fajro; kaj tiujn, kiuj venkis la beston kaj ĝian bildon kaj la numeron de ĝia nomo; kaj ili staris sur la vitra maro, havante harpojn de Dio.","Kaj mi vidis kvazaŭ vitran maron, miksitan kun fajro; kaj tiujn, kiuj venkis la beston kaj ĝian bildon kaj la numeron de ĝia nomo; kaj ili staris sur la vitra maro, havante harpojn de Dio."],[15,3,"Kaj ili kantis la kanton de Moseo, la servanto de Dio, kaj la kanton de la Ŝafido, dirante: Grandaj kaj mirindaj estas Viaj faroj, ho Dio, la Sinjoro, la Plejpotenca; justaj kaj veraj estas Viaj vojoj, ho Reĝo de la nacioj.","Kaj ili kantis la kanton de Moseo, la servanto de Dio, kaj la kanton de la Ŝafido, dirante: Grandaj kaj mirindaj estas Viaj faroj, ho Dio, la Sinjoro, la Plejpotenca; justaj kaj veraj estas Viaj vojoj, ho Reĝo de la nacioj."],[15,4,"Kiu ne timos, ho Sinjoro, kaj ne gloros Vian nomon? ĉar Vi sola estas sankta; ĉar ĉiuj nacioj venos kaj adorkliniĝos al Vi; ĉar Viaj justaĵoj elmontriĝis.","Kiu ne timos, ho Sinjoro, kaj ne gloros Vian nomon? ĉar Vi sola estas sankta; ĉar ĉiuj nacioj venos kaj adorkliniĝos al Vi; ĉar Viaj justaĵoj elmontriĝis."],[15,5,"Kaj post tio mi rigardis, kaj malfermiĝis la templo de la tabernaklo de la atesto en la ĉielo;","Kaj post tio mi rigardis, kaj malfermiĝis la templo de la tabernaklo de la atesto en la ĉielo;"],[15,6,"kaj elvenis el la templo la sep anĝeloj, havante la sep plagojn, vestite per linaĵo pura kaj luma, kaj zonite ĉirkaŭ la brusto per ora zono.","kaj elvenis el la templo la sep anĝeloj, havante la sep plagojn, vestite per linaĵo pura kaj luma, kaj zonite ĉirkaŭ la brusto per ora zono."],[15,7,"Kaj unu el la kvar kreitaĵoj donis al la sep anĝeloj sep orajn pelvojn, plenajn de la kolero de Dio, la vivanta por ĉiam kaj eterne.","Kaj unu el la kvar kreitaĵoj donis al la sep anĝeloj sep orajn pelvojn, plenajn de la kolero de Dio, la vivanta por ĉiam kaj eterne."],[15,8,"Kaj la templo pleniĝis de fumo el la gloro de Dio kaj el Lia potenco; kaj neniu povis eniri en la templon, ĝis finiĝos la sep plagoj de la sep anĝeloj.","Kaj la templo pleniĝis de fumo el la gloro de Dio kaj el Lia potenco; kaj neniu povis eniri en la templon, ĝis finiĝos la sep plagoj de la sep anĝeloj."],[16,1,"Kaj mi aŭdis grandan voĉon el la templo, dirantan al la sep anĝeloj: Iru, kaj elverŝu sur la teron la sep pelvojn de la kolero de Dio.","Kaj mi aŭdis grandan voĉon el la templo, dirantan al la sep anĝeloj: Iru, kaj elverŝu sur la teron la sep pelvojn de la kolero de Dio."],[16,2,"Kaj la unua foriris, kaj elverŝis sian pelvon sur la teron; kaj fariĝis malbona kaj dolora ulcero sur la homoj, kiuj havis la markon de la besto kaj kiuj adorkliniĝis al ĝia bildo.","Kaj la unua foriris, kaj elverŝis sian pelvon sur la teron; kaj fariĝis malbona kaj dolora ulcero sur la homoj, kiuj havis la markon de la besto kaj kiuj adorkliniĝis al ĝia bildo."],[16,3,"Kaj la dua elverŝis sian pelvon en la maron; kaj fariĝis sango, kiel de mortinto; kaj mortis ĉiu vivanta estaĵo en la maro.","Kaj la dua elverŝis sian pelvon en la maron; kaj fariĝis sango, kiel de mortinto; kaj mortis ĉiu vivanta estaĵo en la maro."],[16,4,"Kaj la tria elverŝis sian pelvon en la riverojn kaj en la fontojn de akvoj; kaj fariĝis sango.","Kaj la tria elverŝis sian pelvon en la riverojn kaj en la fontojn de akvoj; kaj fariĝis sango."],[16,5,"Kaj mi aŭdis la anĝelon de la akvoj dirantan: Justa estas Vi, la estanta kaj estinta, la Sanktulo, ĉar Vi tiele juĝis;","Kaj mi aŭdis la anĝelon de la akvoj dirantan: Justa estas Vi, la estanta kaj estinta, la Sanktulo, ĉar Vi tiele juĝis;"],[16,6,"ĉar ili elverŝis la sangon de sanktuloj kaj profetoj, kaj sangon Vi donis al ili trinki; ili tion meritas.","ĉar ili elverŝis la sangon de sanktuloj kaj profetoj, kaj sangon Vi donis al ili trinki; ili tion meritas."],[16,7,"Kaj mi aŭdis la altaron dirantan: Vere, ho Dio, la Sinjoro, la Plejpotenca, veraj kaj justaj estas Viaj juĝoj.","Kaj mi aŭdis la altaron dirantan: Vere, ho Dio, la Sinjoro, la Plejpotenca, veraj kaj justaj estas Viaj juĝoj."],[16,8,"Kaj la kvara elverŝis sian pelvon sur la sunon; kaj estis donite al ĝi brulvundi homojn per fajro.","Kaj la kvara elverŝis sian pelvon sur la sunon; kaj estis donite al ĝi brulvundi homojn per fajro."],[16,9,"Kaj la homoj brulvundiĝis per granda varmego, kaj ili blasfemis la nomon de Dio, kiu havas aŭtoritaton sur tiuj plagoj; kaj ili ne pentis, por doni al Li gloron.","Kaj la homoj brulvundiĝis per granda varmego, kaj ili blasfemis la nomon de Dio, kiu havas aŭtoritaton sur tiuj plagoj; kaj ili ne pentis, por doni al Li gloron."],[16,10,"Kaj la kvina elverŝis sian pelvon sur la tronon de la besto; kaj ĝia regno mallumiĝis; kaj ili mordis sian langon pro dolorego,","Kaj la kvina elverŝis sian pelvon sur la tronon de la besto; kaj ĝia regno mallumiĝis; kaj ili mordis sian langon pro dolorego,"],[16,11,"kaj ili blasfemis la Dion de la ĉielo pro siaj doloroj kaj siaj ulceroj; kaj ili ne pentis pri siaj faroj.","kaj ili blasfemis la Dion de la ĉielo pro siaj doloroj kaj siaj ulceroj; kaj ili ne pentis pri siaj faroj."],[16,12,"Kaj la sesa elverŝis sian pelvon sur la grandan riveron, la riveron Eŭfrato; kaj ĝia akvo forsekiĝis, por ke pretiĝu la vojo de la reĝoj, kiuj venas el la sunleviĝejo.","Kaj la sesa elverŝis sian pelvon sur la grandan riveron, la riveron Eŭfrato; kaj ĝia akvo forsekiĝis, por ke pretiĝu la vojo de la reĝoj, kiuj venas el la sunleviĝejo."],[16,13,"Kaj mi vidis tri malpurajn spiritojn, kvazaŭ ranojn, elirantaj el la buŝo de la drako, kaj el la buŝo de la besto, kaj el la buŝo de la falsa profeto;","Kaj mi vidis tri malpurajn spiritojn, kvazaŭ ranojn, elirantaj el la buŝo de la drako, kaj el la buŝo de la besto, kaj el la buŝo de la falsa profeto;"],[16,14,"ĉar ili estas spiritoj de demonoj, farantaj signojn; ili foriras al la reĝoj de la tuta mondo, por kolekti ilin por la milito de la granda tago de Dio, la Plejpotenca.","ĉar ili estas spiritoj de demonoj, farantaj signojn; ili foriras al la reĝoj de la tuta mondo, por kolekti ilin por la milito de la granda tago de Dio, la Plejpotenca."],[16,15,"(Jen mi venas kvazaŭ ŝtelisto. Feliĉa estas tiu, kiu viglas kaj konservas siajn vestojn, por ke li ne iru nuda, kaj oni ne vidu lian honton.)","(Jen mi venas kvazaŭ ŝtelisto. Feliĉa estas tiu, kiu viglas kaj konservas siajn vestojn, por ke li ne iru nuda, kaj oni ne vidu lian honton.)"],[16,16,"Kaj oni kolektis ilin en lokon, nomatan en la Hebrea lingvo Har-Magedon.","Kaj oni kolektis ilin en lokon, nomatan en la Hebrea lingvo Har-Magedon."],[16,17,"Kaj la sepa anĝelo elverŝis sian pelvon sur la aeron; kaj eliris granda voĉo el la templo, for de la trono, dirante: Fariĝis!","Kaj la sepa anĝelo elverŝis sian pelvon sur la aeron; kaj eliris granda voĉo el la templo, for de la trono, dirante: Fariĝis!"],[16,18,"kaj okazis fulmoj kaj voĉoj kaj tondroj; kaj okazis granda tertremo tia, kia ne okazis de kiam homoj estiĝis sur la tero, tiela tertremo, tiel granda.","kaj okazis fulmoj kaj voĉoj kaj tondroj; kaj okazis granda tertremo tia, kia ne okazis de kiam homoj estiĝis sur la tero, tiela tertremo, tiel granda."],[16,19,"Kaj la granda urbo disiĝis en tri partojn, kaj la urboj de la nacioj falis; kaj Babel la granda estis memorata antaŭ Dio, por doni al ĝi la pokalon de la vino de la furiozeco de Lia kolero.","Kaj la granda urbo disiĝis en tri partojn, kaj la urboj de la nacioj falis; kaj Babel la granda estis memorata antaŭ Dio, por doni al ĝi la pokalon de la vino de la furiozeco de Lia kolero."],[16,20,"Kaj ĉiu insulo forflugis, kaj la montoj ne troviĝis.","Kaj ĉiu insulo forflugis, kaj la montoj ne troviĝis."],[16,21,"Kaj granda hajlo, peza kvazaŭ po talanto, falis el la ĉielo sur la homojn; kaj la homoj blasfemis Dion pro la plago de la hajlo; ĉar ĝia plago estas treege granda.","Kaj granda hajlo, peza kvazaŭ po talanto, falis el la ĉielo sur la homojn; kaj la homoj blasfemis Dion pro la plago de la hajlo; ĉar ĝia plago estas treege granda."],[17,1,"Kaj unu el la sep anĝeloj, havantaj la sep pelvojn, venis kaj parolis kun mi, dirante: Venu ĉi tien, mi montros al vi la juĝon de la granda malĉastistino, kiu sidas sur multaj akvoj;","Kaj unu el la sep anĝeloj, havantaj la sep pelvojn, venis kaj parolis kun mi, dirante: Venu ĉi tien, mi montros al vi la juĝon de la granda malĉastistino, kiu sidas sur multaj akvoj;"],[17,2,"kun kiu la reĝoj de la tero malĉastis, kaj la loĝantoj sur la tero ebriiĝis per la vino de ŝia malĉasteco.","kun kiu la reĝoj de la tero malĉastis, kaj la loĝantoj sur la tero ebriiĝis per la vino de ŝia malĉasteco."],[17,3,"Kaj li forportis min en la Spirito en dezerton; kaj mi vidis virinon, sidantan sur skarlata besto, plena de nomoj de blasfemo, havanta sep kapojn kaj dek kornojn.","Kaj li forportis min en la Spirito en dezerton; kaj mi vidis virinon, sidantan sur skarlata besto, plena de nomoj de blasfemo, havanta sep kapojn kaj dek kornojn."],[17,4,"Kaj la virino estis vestita per purpuro kaj skarlato, kaj ornamita per oro kaj altvaloraj ŝtonoj kaj perloj, kaj havis en sia mano oran pokalon, plenan de abomenindaĵoj kaj la malpuraĵoj de ŝia malĉasteco,","Kaj la virino estis vestita per purpuro kaj skarlato, kaj ornamita per oro kaj altvaloraj ŝtonoj kaj perloj, kaj havis en sia mano oran pokalon, plenan de abomenindaĵoj kaj la malpuraĵoj de ŝia malĉasteco,"],[17,5,"kaj sur sia frunto nomon skribitan: MISTERO, BABEL LA GRANDA, LA PATRINO DE LA MALĈASTISTINOJ KAJ DE LA ABOMENINDAĴOJ DE LA TERO.","kaj sur sia frunto nomon skribitan: MISTERO, BABEL LA GRANDA, LA PATRINO DE LA MALĈASTISTINOJ KAJ DE LA ABOMENINDAĴOJ DE LA TERO."],[17,6,"Kaj mi vidis la virinon ebria de la sango de la sanktuloj, kaj de la sango de la martiroj de Jesuo. Kaj vidinte ŝin, mi miris per granda miro.","Kaj mi vidis la virinon ebria de la sango de la sanktuloj, kaj de la sango de la martiroj de Jesuo. Kaj vidinte ŝin, mi miris per granda miro."],[17,7,"Kaj la anĝelo diris al mi: Kial vi miris? mi diros al vi la misteron de la virino, kaj de la besto, kiu portas ŝin kaj kiu havas la sep kapojn kaj la dek kornojn.","Kaj la anĝelo diris al mi: Kial vi miris? mi diros al vi la misteron de la virino, kaj de la besto, kiu portas ŝin kaj kiu havas la sep kapojn kaj la dek kornojn."],[17,8,"La besto, kiun vi vidis, ekzistis, sed ne ekzistas, kaj venos supren el la abismo kaj iros en pereon. Kaj la loĝantoj sur la tero, kies nomoj ne estas skribitaj en la libro de vivo jam de la fondo de la mondo, miros, kiam ili vidos la beston, ke ĝi ekzistis kaj ne ekzistas, sed venos.","La besto, kiun vi vidis, ekzistis, sed ne ekzistas, kaj venos supren el la abismo kaj iros en pereon. Kaj la loĝantoj sur la tero, kies nomoj ne estas skribitaj en la libro de vivo jam de la fondo de la mondo, miros, kiam ili vidos la beston, ke ĝi ekzistis kaj ne ekzistas, sed venos."],[17,9,"Ĉi tie estas la signifo, kiu havas saĝecon: la sep kapoj estas sep montoj, sur kiuj sidas la virino;","Ĉi tie estas la signifo, kiu havas saĝecon: la sep kapoj estas sep montoj, sur kiuj sidas la virino;"],[17,10,"kaj ili estas sep reĝoj; la kvin jam falis, la unu estas, la alia ankoraŭ ne venis; kaj kiam li venos, li devos resti kelkan tempon.","kaj ili estas sep reĝoj; la kvin jam falis, la unu estas, la alia ankoraŭ ne venis; kaj kiam li venos, li devos resti kelkan tempon."],[17,11,"Kaj la besto, kiu ekzistis kaj ne ekzistas, estas ankaŭ oka, kaj estas el la sep; kaj ĝi iras en pereon.","Kaj la besto, kiu ekzistis kaj ne ekzistas, estas ankaŭ oka, kaj estas el la sep; kaj ĝi iras en pereon."],[17,12,"Kaj la dek kornoj, kiujn vi vidis, estas dek reĝoj, kiuj ankoraŭ ne ricevis regnon; sed ili ricevas aŭtoritaton kiel reĝoj, kun la besto, por unu horo.","Kaj la dek kornoj, kiujn vi vidis, estas dek reĝoj, kiuj ankoraŭ ne ricevis regnon; sed ili ricevas aŭtoritaton kiel reĝoj, kun la besto, por unu horo."],[17,13,"Tiuj havas unu intencon, kaj ili donas sian potencon kaj aŭtoritaton al la besto.","Tiuj havas unu intencon, kaj ili donas sian potencon kaj aŭtoritaton al la besto."],[17,14,"Tiuj militos kontraŭ la Ŝafido, kaj la Ŝafido venkos ilin, ĉar li estas Sinjoro de sinjoroj, kaj Reĝo de reĝoj; kaj venkos tiuj, kiuj estas kun li, vokitaj kaj elektitaj kaj fidelaj.","Tiuj militos kontraŭ la Ŝafido, kaj la Ŝafido venkos ilin, ĉar li estas Sinjoro de sinjoroj, kaj Reĝo de reĝoj; kaj venkos tiuj, kiuj estas kun li, vokitaj kaj elektitaj kaj fidelaj."],[17,15,"Kaj li diris al mi: La akvoj, kiujn vi vidis, kie sidas la malĉastistino, estas popoloj kaj homamasoj kaj nacioj kaj lingvoj.","Kaj li diris al mi: La akvoj, kiujn vi vidis, kie sidas la malĉastistino, estas popoloj kaj homamasoj kaj nacioj kaj lingvoj."],[17,16,"Kaj la dek kornoj, kiujn vi vidis, kaj la besto, malamos la malĉastistinon, kaj faros ŝin izolita kaj nuda, kaj manĝos ŝian karnon, kaj forbruligos ŝin per fajro.","Kaj la dek kornoj, kiujn vi vidis, kaj la besto, malamos la malĉastistinon, kaj faros ŝin izolita kaj nuda, kaj manĝos ŝian karnon, kaj forbruligos ŝin per fajro."],[17,17,"Ĉar Dio enmetis en ilian koron efektivigi Lian intencon, kaj efektivigi unu intencon, kaj doni sian regnon al la besto, ĝis la vortoj de Dio plenumiĝos.","Ĉar Dio enmetis en ilian koron efektivigi Lian intencon, kaj efektivigi unu intencon, kaj doni sian regnon al la besto, ĝis la vortoj de Dio plenumiĝos."],[17,18,"Kaj la virino, kiun vi vidis, estas la granda urbo, kiu havas reĝecon super la reĝoj de la tero.","Kaj la virino, kiun vi vidis, estas la granda urbo, kiu havas reĝecon super la reĝoj de la tero."],[18,1,"Post tio mi vidis alian anĝelon, malsuprenirantan el la ĉielo, havantan grandan aŭtoritaton; kaj la tero lumiĝis per lia gloro.","Post tio mi vidis alian anĝelon, malsuprenirantan el la ĉielo, havantan grandan aŭtoritaton; kaj la tero lumiĝis per lia gloro."],[18,2,"Kaj li forte kriis per granda voĉo, dirante: Falis, falis Babel la granda, kaj fariĝis loĝejo de demonoj, kaj malliberejo de ĉia malpura spirito, kaj malliberejo de ĉia malpura kaj malaminda birdo.","Kaj li forte kriis per granda voĉo, dirante: Falis, falis Babel la granda, kaj fariĝis loĝejo de demonoj, kaj malliberejo de ĉia malpura spirito, kaj malliberejo de ĉia malpura kaj malaminda birdo."],[18,3,"Ĉar per la vino de la kolero de ŝia malĉasteco falis ĉiuj nacioj; kaj la reĝoj de la tero malĉastis kun ŝi, kaj la komercistoj de la tero riĉiĝis per la potenco de ŝia lukso.","Ĉar per la vino de la kolero de ŝia malĉasteco falis ĉiuj nacioj; kaj la reĝoj de la tero malĉastis kun ŝi, kaj la komercistoj de la tero riĉiĝis per la potenco de ŝia lukso."],[18,4,"Kaj mi aŭdis alian voĉon el la ĉielo, dirantan: Elvenu el ŝi, ho Mia popolo, por ke vi ne partoprenu en ŝiaj pekoj, kaj por ke vi ne ricevu el ŝiaj plagoj;","Kaj mi aŭdis alian voĉon el la ĉielo, dirantan: Elvenu el ŝi, ho Mia popolo, por ke vi ne partoprenu en ŝiaj pekoj, kaj por ke vi ne ricevu el ŝiaj plagoj;"],[18,5,"ĉar ŝiaj pekoj amasiĝis ĝis la ĉielo, kaj Dio memoris ŝiajn maljustaĵojn.","ĉar ŝiaj pekoj amasiĝis ĝis la ĉielo, kaj Dio memoris ŝiajn maljustaĵojn."],[18,6,"Redonu al ŝi, ĝuste kiel ŝi donis, kaj duobligu duoble laŭ ŝiaj faroj; en la pokalo, kiun ŝi miksis, miksu al ŝi duoblon.","Redonu al ŝi, ĝuste kiel ŝi donis, kaj duobligu duoble laŭ ŝiaj faroj; en la pokalo, kiun ŝi miksis, miksu al ŝi duoblon."],[18,7,"Kiom ŝi gloris sin kaj voluptis, tiom donu al ŝi da turmento kaj funebro; ĉar ŝi diras en sia koro: Mi sidas reĝino, kaj mi ne estas vidvino, kaj mi tute ne vidos funebron.","Kiom ŝi gloris sin kaj voluptis, tiom donu al ŝi da turmento kaj funebro; ĉar ŝi diras en sia koro: Mi sidas reĝino, kaj mi ne estas vidvino, kaj mi tute ne vidos funebron."],[18,8,"Tial en unu tago venos ŝiaj plagoj, morto kaj funebro kaj malsatego; kaj ŝi forbrulos per fajro; ĉar forta estas Dio, la Sinjoro, kiu ŝin juĝas.","Tial en unu tago venos ŝiaj plagoj, morto kaj funebro kaj malsatego; kaj ŝi forbrulos per fajro; ĉar forta estas Dio, la Sinjoro, kiu ŝin juĝas."],[18,9,"Kaj la reĝoj de la tero, kiuj malĉastis kun ŝi kaj voluptis, ploros kaj ĝemos pri ŝi, kiam ili rigardos la fumon de ŝia brulado,","Kaj la reĝoj de la tero, kiuj malĉastis kun ŝi kaj voluptis, ploros kaj ĝemos pri ŝi, kiam ili rigardos la fumon de ŝia brulado,"],[18,10,"starante malproksime pro timo de ŝia turmento, dirante: Ve! ve, la granda urbo, Babel, la forta urbo! ĉar en unu horo venis via juĝo.","starante malproksime pro timo de ŝia turmento, dirante: Ve! ve, la granda urbo, Babel, la forta urbo! ĉar en unu horo venis via juĝo."],[18,11,"Kaj la komercistoj de la tero ploras kaj lamentas pri ŝi, ĉar jam neniu aĉetas ilian komercaĵon;","Kaj la komercistoj de la tero ploras kaj lamentas pri ŝi, ĉar jam neniu aĉetas ilian komercaĵon;"],[18,12,"komercaĵon el oro kaj arĝento kaj altvaloraj ŝtonoj kaj perloj kaj bisino kaj purpuro kaj silko kaj skarlato, kaj ĉia parfuma ligno kaj ĉia vazo ebura kaj ĉia vazo el plej altvalora ligno kaj el kupro kaj fero kaj marmoro,","komercaĵon el oro kaj arĝento kaj altvaloraj ŝtonoj kaj perloj kaj bisino kaj purpuro kaj silko kaj skarlato, kaj ĉia parfuma ligno kaj ĉia vazo ebura kaj ĉia vazo el plej altvalora ligno kaj el kupro kaj fero kaj marmoro,"],[18,13,"kaj cinamo kaj amomo kaj incenso kaj ŝmiraĵo kaj olibano kaj vino kaj oleo kaj faruno kaj tritiko kaj brutoj kaj ŝafoj, kaj el ĉevaloj kaj ĉaroj, kaj korpoj kaj animoj de homoj.","kaj cinamo kaj amomo kaj incenso kaj ŝmiraĵo kaj olibano kaj vino kaj oleo kaj faruno kaj tritiko kaj brutoj kaj ŝafoj, kaj el ĉevaloj kaj ĉaroj, kaj korpoj kaj animoj de homoj."],[18,14,"Kaj la fruktaro de la deziroj de via animo malaperis for de vi, kaj ĉio bongusta kaj brila pereis for de vi, kaj oni ne plu trovos ilin.","Kaj la fruktaro de la deziroj de via animo malaperis for de vi, kaj ĉio bongusta kaj brila pereis for de vi, kaj oni ne plu trovos ilin."],[18,15,"La negocintoj de tiuj komercaĵoj, kiuj riĉiĝis per ŝi, malproksime staros pro la timo de ŝia turmento, plorante kaj lamentante,","La negocintoj de tiuj komercaĵoj, kiuj riĉiĝis per ŝi, malproksime staros pro la timo de ŝia turmento, plorante kaj lamentante,"],[18,16,"kaj dirante: Ve! ve, la granda urbo, la vestita per bisino kaj purpuro kaj skarlato, kaj ornamita per oro kaj altvaloraj ŝtonoj kaj perloj!","kaj dirante: Ve! ve, la granda urbo, la vestita per bisino kaj purpuro kaj skarlato, kaj ornamita per oro kaj altvaloraj ŝtonoj kaj perloj!"],[18,17,"ĉar en unu horo pereis tiom da riĉeco. Kaj ĉiu ŝipestro, kaj ĉiu ien ŝipe veturanta, kaj maristoj, kaj ĉiuj, kiuj sur la maro laboris, staris malproksime,","ĉar en unu horo pereis tiom da riĉeco. Kaj ĉiu ŝipestro, kaj ĉiu ien ŝipe veturanta, kaj maristoj, kaj ĉiuj, kiuj sur la maro laboris, staris malproksime,"],[18,18,"kaj kriis, vidante la fumon de ŝia brulego, dirante: Kio similas la grandan urbon?","kaj kriis, vidante la fumon de ŝia brulego, dirante: Kio similas la grandan urbon?"],[18,19,"Kaj ili ĵetis polvon sur siajn kapojn, kaj kriis, plorante kaj lamentante, kaj dirante: Ve! ve, la granda urbo! en kiu riĉiĝis ĉiuj, kiuj havis siajn ŝipojn sur la maro per ŝia luksego! ĉar en unu horo ŝi dezertiĝis.","Kaj ili ĵetis polvon sur siajn kapojn, kaj kriis, plorante kaj lamentante, kaj dirante: Ve! ve, la granda urbo! en kiu riĉiĝis ĉiuj, kiuj havis siajn ŝipojn sur la maro per ŝia luksego! ĉar en unu horo ŝi dezertiĝis."],[18,20,"Ĝojegu super ŝi, ho ĉielo, kaj la sanktuloj, kaj la apostoloj, kaj la profetoj; ĉar Dio decidis pri ŝi laŭ via juĝo.","Ĝojegu super ŝi, ho ĉielo, kaj la sanktuloj, kaj la apostoloj, kaj la profetoj; ĉar Dio decidis pri ŝi laŭ via juĝo."],[18,21,"Kaj forta anĝelo prenis ŝtonon, kvazaŭ grandan muelŝtonon, kaj ĵetis ĝin en la maron, dirante: Tiel per puŝego deĵetiĝos Babel, la granda urbo, kaj jam ne plu troviĝos.","Kaj forta anĝelo prenis ŝtonon, kvazaŭ grandan muelŝtonon, kaj ĵetis ĝin en la maron, dirante: Tiel per puŝego deĵetiĝos Babel, la granda urbo, kaj jam ne plu troviĝos."],[18,22,"Kaj voĉo de harpistoj kaj muzikistoj kaj flutistoj kaj trumpetistoj jam ne plu aŭdiĝos en vi; kaj ĉia metiisto de ĉia metio jam ne plu troviĝos en vi; kaj sono de muelŝtono jam ne plu aŭdiĝos en vi;","Kaj voĉo de harpistoj kaj muzikistoj kaj flutistoj kaj trumpetistoj jam ne plu aŭdiĝos en vi; kaj ĉia metiisto de ĉia metio jam ne plu troviĝos en vi; kaj sono de muelŝtono jam ne plu aŭdiĝos en vi;"],[18,23,"kaj lumo de lampo jam ne plu brilos en vi; kaj voĉo de fianĉo kaj fianĉino jam ne plu aŭdiĝos en vi; ĉar viaj komercistoj estis la granduloj de la tero; ĉar per via sorĉado ĉiuj nacioj trompiĝis.","kaj lumo de lampo jam ne plu brilos en vi; kaj voĉo de fianĉo kaj fianĉino jam ne plu aŭdiĝos en vi; ĉar viaj komercistoj estis la granduloj de la tero; ĉar per via sorĉado ĉiuj nacioj trompiĝis."],[18,24,"Kaj en ŝi troviĝis la sango de profetoj kaj sanktuloj, kaj de ĉiuj mortigitoj sur la tero.","Kaj en ŝi troviĝis la sango de profetoj kaj sanktuloj, kaj de ĉiuj mortigitoj sur la tero."],[19,1,"Post tio mi aŭdis kvazaŭ grandan voĉon de granda homamaso en la ĉielo, dirantan: Haleluja! La savo kaj la gloro kaj la potenco apartenas al nia Dio;","Post tio mi aŭdis kvazaŭ grandan voĉon de granda homamaso en la ĉielo, dirantan: Haleluja! La savo kaj la gloro kaj la potenco apartenas al nia Dio;"],[19,2,"ĉar veraj kaj justaj estas Liaj juĝoj; ĉar Li juĝis la grandan malĉastistinon, kiu infektis la teron per sia malĉasteco, kaj Li venĝis la sangon de Siaj servistoj el ŝia mano.","ĉar veraj kaj justaj estas Liaj juĝoj; ĉar Li juĝis la grandan malĉastistinon, kiu infektis la teron per sia malĉasteco, kaj Li venĝis la sangon de Siaj servistoj el ŝia mano."],[19,3,"Kaj duan fojon ili diris: Haleluja! Kaj ŝia fumo leviĝas por ĉiam kaj eterne.","Kaj duan fojon ili diris: Haleluja! Kaj ŝia fumo leviĝas por ĉiam kaj eterne."],[19,4,"Kaj la dudek kvar presbiteroj kaj la kvar kreitaĵoj falis kaj adorkliniĝis al Dio, la sidanta sur la trono, dirante: Amen, Haleluja!","Kaj la dudek kvar presbiteroj kaj la kvar kreitaĵoj falis kaj adorkliniĝis al Dio, la sidanta sur la trono, dirante: Amen, Haleluja!"],[19,5,"Kaj el la trono eliris voĉo, dirante: Laŭdu nian Dion, ĉiuj Liaj servistoj, vi, kiuj timas Lin, la malgrandaj kaj la grandaj.","Kaj el la trono eliris voĉo, dirante: Laŭdu nian Dion, ĉiuj Liaj servistoj, vi, kiuj timas Lin, la malgrandaj kaj la grandaj."],[19,6,"Kaj mi aŭdis kvazaŭ voĉon de granda homamaso kaj kvazaŭ voĉon de multaj akvoj kaj kvazaŭ voĉon de fortaj tondroj, dirantajn: Haleluja! ĉar la Sinjoro, nia Dio, la Plejpotenca, reĝas.","Kaj mi aŭdis kvazaŭ voĉon de granda homamaso kaj kvazaŭ voĉon de multaj akvoj kaj kvazaŭ voĉon de fortaj tondroj, dirantajn: Haleluja! ĉar la Sinjoro, nia Dio, la Plejpotenca, reĝas."],[19,7,"Ni ĝoju kaj triumfu, kaj donu al Li la gloron; ĉar venis la edziĝo de la Ŝafido, kaj lia edzino sin pretigis.","Ni ĝoju kaj triumfu, kaj donu al Li la gloron; ĉar venis la edziĝo de la Ŝafido, kaj lia edzino sin pretigis."],[19,8,"Kaj estis donite al ŝi, ke ŝi sin vestu per bisino luma kaj pura; ĉar la bisino estas la justaĵoj de la sanktuloj.","Kaj estis donite al ŝi, ke ŝi sin vestu per bisino luma kaj pura; ĉar la bisino estas la justaĵoj de la sanktuloj."],[19,9,"Kaj li diris al mi: Skribu: Feliĉaj estas la invititaj al la edziĝa festeno de la Ŝafido. Kaj li diris al mi: Tio estas la veraj vortoj de Dio.","Kaj li diris al mi: Skribu: Feliĉaj estas la invititaj al la edziĝa festeno de la Ŝafido. Kaj li diris al mi: Tio estas la veraj vortoj de Dio."],[19,10,"Kaj mi falis antaŭ liaj piedoj, por adorkliniĝi al li. Kaj li diris al mi: Gardu vin, ke vi tion ne faru; mi estas kunservisto kun vi kaj kun viaj fratoj, kiuj konservas la ateston de Jesuo; adorkliniĝu al Dio; ĉar la atesto de Jesuo estas la spirito de profetado.","Kaj mi falis antaŭ liaj piedoj, por adorkliniĝi al li. Kaj li diris al mi: Gardu vin, ke vi tion ne faru; mi estas kunservisto kun vi kaj kun viaj fratoj, kiuj konservas la ateston de Jesuo; adorkliniĝu al Dio; ĉar la atesto de Jesuo estas la spirito de profetado."],[19,11,"Kaj mi vidis la ĉielon malfermitan; kaj jen blanka ĉevalo, kaj la sidanta sur ĝi, nomata Fidela kaj Vera; en justeco li juĝas kaj militas.","Kaj mi vidis la ĉielon malfermitan; kaj jen blanka ĉevalo, kaj la sidanta sur ĝi, nomata Fidela kaj Vera; en justeco li juĝas kaj militas."],[19,12,"Kaj liaj okuloj estas fajra flamo, kaj sur lia kapo estas multaj diademoj; kaj li havas nomon skribitan, kiun konas neniu krom li mem.","Kaj liaj okuloj estas fajra flamo, kaj sur lia kapo estas multaj diademoj; kaj li havas nomon skribitan, kiun konas neniu krom li mem."],[19,13,"Kaj li estas vestita per vesto, trempita en sangon; kaj lia nomo estas: La Vorto de Dio.","Kaj li estas vestita per vesto, trempita en sangon; kaj lia nomo estas: La Vorto de Dio."],[19,14,"Kaj la armeoj en la ĉielo sekvis lin sur blankaj ĉevaloj, vestite per bisino blanka kaj pura.","Kaj la armeoj en la ĉielo sekvis lin sur blankaj ĉevaloj, vestite per bisino blanka kaj pura."],[19,15,"Kaj el lia buŝo eliras akra glavo, por ke li per ĝi frapu la naciojn; kaj li regos ilin per fera sceptro; kaj li tretas la vinpremilon de la furiozeco de la kolero de Dio, la Plejpotenca.","Kaj el lia buŝo eliras akra glavo, por ke li per ĝi frapu la naciojn; kaj li regos ilin per fera sceptro; kaj li tretas la vinpremilon de la furiozeco de la kolero de Dio, la Plejpotenca."],[19,16,"Kaj li havas sur la vesto kaj sur la femuro nomon skribitan: REĜO DE REĜOJ KAJ SINJORO DE SINJOROJ.","Kaj li havas sur la vesto kaj sur la femuro nomon skribitan: REĜO DE REĜOJ KAJ SINJORO DE SINJOROJ."],[19,17,"Kaj mi vidis unu anĝelon, starantan en la suno; kaj li ekkriis per granda voĉo, dirante al ĉiuj birdoj, kiuj flugas en meza ĉielo: Venu, kolektiĝu al la granda festeno de Dio;","Kaj mi vidis unu anĝelon, starantan en la suno; kaj li ekkriis per granda voĉo, dirante al ĉiuj birdoj, kiuj flugas en meza ĉielo: Venu, kolektiĝu al la granda festeno de Dio;"],[19,18,"por ke vi manĝu karnon de reĝoj kaj karnon de milestroj kaj karnon de fortuloj kaj karnon de ĉevaloj kaj de iliaj rajdantoj, kaj karnon de ĉiuj homoj, liberaj kaj sklavaj, grandaj kaj malgrandaj.","por ke vi manĝu karnon de reĝoj kaj karnon de milestroj kaj karnon de fortuloj kaj karnon de ĉevaloj kaj de iliaj rajdantoj, kaj karnon de ĉiuj homoj, liberaj kaj sklavaj, grandaj kaj malgrandaj."],[19,19,"Kaj mi vidis la beston, kaj la reĝojn de la tero kaj iliajn armeojn, kunigitajn, por fari militon kontraŭ la sidanta sur la ĉevalo kaj kontraŭ lia armeo.","Kaj mi vidis la beston, kaj la reĝojn de la tero kaj iliajn armeojn, kunigitajn, por fari militon kontraŭ la sidanta sur la ĉevalo kaj kontraŭ lia armeo."],[19,20,"Kaj la besto estis kaptita, kaj kun ĝi la falsa profeto, kiu faris antaŭ ĝi la signojn, per kiuj li trompis tiujn, kiuj ricevis la markon de la besto kaj adorkliniĝis al ĝia bildo; ili ambaŭ estis ĵetitaj vivaj en la lagon fajran, brulantan per sulfuro;","Kaj la besto estis kaptita, kaj kun ĝi la falsa profeto, kiu faris antaŭ ĝi la signojn, per kiuj li trompis tiujn, kiuj ricevis la markon de la besto kaj adorkliniĝis al ĝia bildo; ili ambaŭ estis ĵetitaj vivaj en la lagon fajran, brulantan per sulfuro;"],[19,21,"kaj la ceteraj estis mortigitaj per la glavo de la sidanta sur la ĉevalo, la glavo, kiu eliris el lia buŝo; kaj ĉiuj birdoj satiĝis per ilia karno.","kaj la ceteraj estis mortigitaj per la glavo de la sidanta sur la ĉevalo, la glavo, kiu eliris el lia buŝo; kaj ĉiuj birdoj satiĝis per ilia karno."],[20,1,"Kaj mi vidis anĝelon malsuprenirantan el la ĉielo, havantan la ŝlosilon de la abismo kaj grandan katenon en sia mano.","Kaj mi vidis anĝelon malsuprenirantan el la ĉielo, havantan la ŝlosilon de la abismo kaj grandan katenon en sia mano."],[20,2,"Kaj li ekkaptis la drakon, la antikvan serpenton, kiu estas la Diablo kaj Satano, kaj enkatenis lin por mil jaroj,","Kaj li ekkaptis la drakon, la antikvan serpenton, kiu estas la Diablo kaj Satano, kaj enkatenis lin por mil jaroj,"],[20,3,"kaj ĵetis lin en la abismon kaj fermis ĝin kaj sigelis ĝin super li, por ke li ne plu trompu la naciojn, ĝis finiĝos la mil jaroj; post tio li devos esti malligita por kelka tempo.","kaj ĵetis lin en la abismon kaj fermis ĝin kaj sigelis ĝin super li, por ke li ne plu trompu la naciojn, ĝis finiĝos la mil jaroj; post tio li devos esti malligita por kelka tempo."],[20,4,"Kaj mi vidis tronojn, kaj oni sidis sur ili, kaj juĝo estis donita al ili; kaj mi vidis la animojn de la senkapigitaj pro la atesto de Jesuo kaj pro la vorto de Dio, kaj tiujn, kiuj ne adorkliniĝis al la besto, nek al ĝia bildo, kaj ne ricevis la markon sur sia frunto kaj sur sia mano; kaj ili vivis, kaj ili reĝis kun Kristo mil jarojn.","Kaj mi vidis tronojn, kaj oni sidis sur ili, kaj juĝo estis donita al ili; kaj mi vidis la animojn de la senkapigitaj pro la atesto de Jesuo kaj pro la vorto de Dio, kaj tiujn, kiuj ne adorkliniĝis al la besto, nek al ĝia bildo, kaj ne ricevis la markon sur sia frunto kaj sur sia mano; kaj ili vivis, kaj ili reĝis kun Kristo mil jarojn."],[20,5,"La ceteraj mortintoj ne vivis, ĝis finiĝos la mil jaroj. Tio estas la unua releviĝo.","La ceteraj mortintoj ne vivis, ĝis finiĝos la mil jaroj. Tio estas la unua releviĝo."],[20,6,"Feliĉa kaj sankta estas la partoprenanto en la unua releviĝo; super tiuj la dua morto havas nenian aŭtoritaton; sed ili estos pastroj de Dio kaj de Kristo, kaj reĝos kun li mil jarojn.","Feliĉa kaj sankta estas la partoprenanto en la unua releviĝo; super tiuj la dua morto havas nenian aŭtoritaton; sed ili estos pastroj de Dio kaj de Kristo, kaj reĝos kun li mil jarojn."],[20,7,"Kaj kiam finiĝos la mil jaroj, Satano estos ellasita el sia malliberejo,","Kaj kiam finiĝos la mil jaroj, Satano estos ellasita el sia malliberejo,"],[20,8,"kaj eliros, por trompi la naciojn en la kvar anguloj de la tero, Gog kaj Magog, por kolekti ilin por la milito; ilia nombro estas kiel la sablo de la maro.","kaj eliros, por trompi la naciojn en la kvar anguloj de la tero, Gog kaj Magog, por kolekti ilin por la milito; ilia nombro estas kiel la sablo de la maro."],[20,9,"Kaj ili supreniris laŭlarĝe de la tero kaj ĉirkaŭis la tendaron de la sanktuloj kaj la amatan urbon; kaj fajro malsupreniris el la ĉielo, kaj ekstermis ilin.","Kaj ili supreniris laŭlarĝe de la tero kaj ĉirkaŭis la tendaron de la sanktuloj kaj la amatan urbon; kaj fajro malsupreniris el la ĉielo, kaj ekstermis ilin."],[20,10,"Kaj la diablo, kiu trompis ilin, estis ĵetita en la lagon fajran kaj sulfuran, kie troviĝas la besto kaj la falsa profeto; kaj ili estos turmentataj tage kaj nokte por ĉiam kaj eterne.","Kaj la diablo, kiu trompis ilin, estis ĵetita en la lagon fajran kaj sulfuran, kie troviĝas la besto kaj la falsa profeto; kaj ili estos turmentataj tage kaj nokte por ĉiam kaj eterne."],[20,11,"Kaj mi vidis grandan blankan tronon, kaj la Sidanton sur ĝi, antaŭ kies vizaĝo forflugis la tero kaj la ĉielo; kaj ne troviĝis loko por ili.","Kaj mi vidis grandan blankan tronon, kaj la Sidanton sur ĝi, antaŭ kies vizaĝo forflugis la tero kaj la ĉielo; kaj ne troviĝis loko por ili."],[20,12,"Kaj mi vidis la mortintojn, grandajn kaj malgrandajn, starantajn antaŭ la trono; kaj libroj estis malfermitaj; kaj estis malfermita alia libro, kiu estas la libro de vivo; kaj la mortintoj estis juĝataj el la skribitaĵoj en la libroj, laŭ siaj faroj.","Kaj mi vidis la mortintojn, grandajn kaj malgrandajn, starantajn antaŭ la trono; kaj libroj estis malfermitaj; kaj estis malfermita alia libro, kiu estas la libro de vivo; kaj la mortintoj estis juĝataj el la skribitaĵoj en la libroj, laŭ siaj faroj."],[20,13,"Kaj la maro liveris la mortintojn, kiuj estis en ĝi; kaj la morto kaj Hades liveris la mortintojn, kiuj estis en ili; kaj ĉiu estis juĝata laŭ siaj faroj.","Kaj la maro liveris la mortintojn, kiuj estis en ĝi; kaj la morto kaj Hades liveris la mortintojn, kiuj estis en ili; kaj ĉiu estis juĝata laŭ siaj faroj."],[20,14,"Kaj la morto kaj Hades estis ĵetitaj en la fajran lagon. Tio estas la dua morto — la fajra lago.","Kaj la morto kaj Hades estis ĵetitaj en la fajran lagon. Tio estas la dua morto — la fajra lago."],[20,15,"Kaj se iu ne troviĝis skribita en la libro de vivo, tiu estis ĵetita en la fajran lagon.","Kaj se iu ne troviĝis skribita en la libro de vivo, tiu estis ĵetita en la fajran lagon."],[21,1,"Kaj mi vidis novan ĉielon kaj novan teron; ĉar la unua ĉielo kaj la unua tero forpasis; kaj la maro jam ne ekzistis.","Kaj mi vidis novan ĉielon kaj novan teron; ĉar la unua ĉielo kaj la unua tero forpasis; kaj la maro jam ne ekzistis."],[21,2,"Kaj mi vidis la sanktan urbon, novan Jerusalemon, malsuprenirantan el la ĉielo for de Dio, pretigitan kiel fianĉino, ornamita por sia edzo.","Kaj mi vidis la sanktan urbon, novan Jerusalemon, malsuprenirantan el la ĉielo for de Dio, pretigitan kiel fianĉino, ornamita por sia edzo."],[21,3,"Kaj mi aŭdis grandan voĉon el la trono, dirantan: Jen la tabernaklo de Dio estas kun la homoj, kaj Li loĝos kun ili, kaj ili estos Liaj popoloj, kaj Dio mem estos kun ili kaj estos ilia Dio;","Kaj mi aŭdis grandan voĉon el la trono, dirantan: Jen la tabernaklo de Dio estas kun la homoj, kaj Li loĝos kun ili, kaj ili estos Liaj popoloj, kaj Dio mem estos kun ili kaj estos ilia Dio;"],[21,4,"kaj Li forviŝos ĉiun larmon el iliaj okuloj; kaj la morto jam ne ekzistos; ne plu ekzistos funebro, nek plorado, nek doloro; la unuaj aferoj forpasis.","kaj Li forviŝos ĉiun larmon el iliaj okuloj; kaj la morto jam ne ekzistos; ne plu ekzistos funebro, nek plorado, nek doloro; la unuaj aferoj forpasis."],[21,5,"Kaj diris la Sidanto sur la trono: Vidu, Mi faras ĉion nova. Kaj Li diris: Skribu, ĉar tiuj vortoj estas fidelaj kaj veraj.","Kaj diris la Sidanto sur la trono: Vidu, Mi faras ĉion nova. Kaj Li diris: Skribu, ĉar tiuj vortoj estas fidelaj kaj veraj."],[21,6,"Kaj Li diris al mi: Ĉio fariĝis. Mi estas la Alfa kaj la Omega, la komenco kaj la fino. Mi donos donace al la soifanto el la fonto de la akvo de vivo.","Kaj Li diris al mi: Ĉio fariĝis. Mi estas la Alfa kaj la Omega, la komenco kaj la fino. Mi donos donace al la soifanto el la fonto de la akvo de vivo."],[21,7,"La venkanto heredos ĉion; kaj Mi estos por li Dio, kaj li estos por Mi filo.","La venkanto heredos ĉion; kaj Mi estos por li Dio, kaj li estos por Mi filo."],[21,8,"Sed por la timemaj kaj nekredemaj kaj abomenindaj kaj mortigistoj kaj malĉastuloj kaj sorĉistoj kaj idolanoj kaj ĉiuj mensoguloj, ilia lotaĵo estos en la lago, brulanta per fajro kaj sulfuro; tio estas la dua morto.","Sed por la timemaj kaj nekredemaj kaj abomenindaj kaj mortigistoj kaj malĉastuloj kaj sorĉistoj kaj idolanoj kaj ĉiuj mensoguloj, ilia lotaĵo estos en la lago, brulanta per fajro kaj sulfuro; tio estas la dua morto."],[21,9,"Kaj venis unu el la sep anĝeloj, havantaj la sep pelvojn, plenajn de la sep finaj plagoj; kaj li parolis kun mi, dirante: Venu ĉi tien, mi montros al vi la fianĉinon, la edzinon de la Ŝafido.","Kaj venis unu el la sep anĝeloj, havantaj la sep pelvojn, plenajn de la sep finaj plagoj; kaj li parolis kun mi, dirante: Venu ĉi tien, mi montros al vi la fianĉinon, la edzinon de la Ŝafido."],[21,10,"Kaj li forportis min en la Spirito sur monton, grandan kaj altan, kaj li montris al mi la sanktan urbon Jerusalem, malsuprenirantan el la ĉielo for de Dio,","Kaj li forportis min en la Spirito sur monton, grandan kaj altan, kaj li montris al mi la sanktan urbon Jerusalem, malsuprenirantan el la ĉielo for de Dio,"],[21,11,"havantan la gloron de Dio; ĝia lumo estis simila al ŝtono plej altvalora, kvazaŭ jaspiso kristaleca;","havantan la gloron de Dio; ĝia lumo estis simila al ŝtono plej altvalora, kvazaŭ jaspiso kristaleca;"],[21,12,"kun muro granda kaj alta, kun dek du pordegoj, kaj apud la pordegoj dek du anĝeloj; kaj nomoj surskribitaj, kiuj estas la nomoj de la dek du triboj de la Izraelidoj;","kun muro granda kaj alta, kun dek du pordegoj, kaj apud la pordegoj dek du anĝeloj; kaj nomoj surskribitaj, kiuj estas la nomoj de la dek du triboj de la Izraelidoj;"],[21,13,"oriente estis tri pordegoj, kaj norde tri pordegoj, kaj sude tri pordegoj, kaj okcidente tri pordegoj.","oriente estis tri pordegoj, kaj norde tri pordegoj, kaj sude tri pordegoj, kaj okcidente tri pordegoj."],[21,14,"Kaj la muro de la urbo havis dek du fundamentojn, kaj sur ili dek du nomojn de la dek du apostoloj de la Ŝafido.","Kaj la muro de la urbo havis dek du fundamentojn, kaj sur ili dek du nomojn de la dek du apostoloj de la Ŝafido."],[21,15,"Kaj mia kunparolanto havis mezurilon, oran vergon, por mezuri la urbon kaj ĝiajn pordegojn kaj ĝian muron.","Kaj mia kunparolanto havis mezurilon, oran vergon, por mezuri la urbon kaj ĝiajn pordegojn kaj ĝian muron."],[21,16,"Kaj la urbo staras kvadrate, kaj ĝia longo estas tiom, kiom la larĝo; kaj li mezuris la urbon per la vergo, dek du mil stadiojn; ĝia longo kaj ĝia larĝo kaj ĝia alto estas egalaj.","Kaj la urbo staras kvadrate, kaj ĝia longo estas tiom, kiom la larĝo; kaj li mezuris la urbon per la vergo, dek du mil stadiojn; ĝia longo kaj ĝia larĝo kaj ĝia alto estas egalaj."],[21,17,"Kaj li mezuris ĝian muron, cent kvardek kvar ulnojn, laŭ mezuro de homo, tio estas, de anĝelo.","Kaj li mezuris ĝian muron, cent kvardek kvar ulnojn, laŭ mezuro de homo, tio estas, de anĝelo."],[21,18,"Kaj la strukturo de ĝia muro estis jaspiso; kaj la urbo estis pura oro, simila al pura vitro.","Kaj la strukturo de ĝia muro estis jaspiso; kaj la urbo estis pura oro, simila al pura vitro."],[21,19,"La fundamentoj de la muro de la urbo estis ornamitaj per altvaloraj ŝtonoj ĉiuspecaj. La unua fundamento estis jaspiso; la dua, safiro; la tria, kalcedonio; la kvara, smeraldo;","La fundamentoj de la muro de la urbo estis ornamitaj per altvaloraj ŝtonoj ĉiuspecaj. La unua fundamento estis jaspiso; la dua, safiro; la tria, kalcedonio; la kvara, smeraldo;"],[21,20,"la kvina, sardonikso; la sesa, sardio; la sepa, krizolito; la oka, berilo; la naŭa, topazo; la deka, krizopraso; la dek-unua, jacinto; la dek-dua, ametisto.","la kvina, sardonikso; la sesa, sardio; la sepa, krizolito; la oka, berilo; la naŭa, topazo; la deka, krizopraso; la dek-unua, jacinto; la dek-dua, ametisto."],[21,21,"Kaj la dek du pordegoj estis dek du perloj, ĉiu el la pordegoj estis el unu perlo; kaj la strato de la urbo estis pura oro, kvazaŭ travidebla vitro.","Kaj la dek du pordegoj estis dek du perloj, ĉiu el la pordegoj estis el unu perlo; kaj la strato de la urbo estis pura oro, kvazaŭ travidebla vitro."],[21,22,"Kaj templon en ĝi mi ne vidis; ĉar Dio, la Sinjoro, la Plejpotenca, kaj la Ŝafido estas ĝia templo.","Kaj templon en ĝi mi ne vidis; ĉar Dio, la Sinjoro, la Plejpotenca, kaj la Ŝafido estas ĝia templo."],[21,23,"Kaj la urbo ne bezonas la sunon, nek la lunon, por brili al ĝi; ĉar la gloro de Dio lumis al ĝi, kaj ĝia lampo estas la Ŝafido.","Kaj la urbo ne bezonas la sunon, nek la lunon, por brili al ĝi; ĉar la gloro de Dio lumis al ĝi, kaj ĝia lampo estas la Ŝafido."],[21,24,"Kaj la nacioj promenos per ĝia lumo; kaj la reĝoj de la tero alportas en ĝin sian gloron.","Kaj la nacioj promenos per ĝia lumo; kaj la reĝoj de la tero alportas en ĝin sian gloron."],[21,25,"Kaj ĝiaj pordegoj tute ne estos fermitaj tage (ĉar nokto ne ekzistos tie);","Kaj ĝiaj pordegoj tute ne estos fermitaj tage (ĉar nokto ne ekzistos tie);"],[21,26,"kaj ili alportos en ĝin la gloron kaj la honoron de la nacioj;","kaj ili alportos en ĝin la gloron kaj la honoron de la nacioj;"],[21,27,"kaj tute ne eniros en ĝin io malpura, nek faranto de abomenindaĵo kaj mensogo; sed nur la skribitaj en la libro de vivo de la Ŝafido.","kaj tute ne eniros en ĝin io malpura, nek faranto de abomenindaĵo kaj mensogo; sed nur la skribitaj en la libro de vivo de la Ŝafido."],[22,1,"Kaj li montris al mi riveron de akvo de vivo, helan kiel kristalo, elirantan el la trono de Dio kaj de la Ŝafido,","Kaj li montris al mi riveron de akvo de vivo, helan kiel kristalo, elirantan el la trono de Dio kaj de la Ŝafido,"],[22,2,"meze de ĝia strato. Kaj ĉe ĉiu flanko de la rivero estis arbo de vivo, portanta dek du fruktojn, liveranta sian frukton ĉiumonate; kaj la folioj de la arbo estis por la resanigo de la nacioj.","meze de ĝia strato. Kaj ĉe ĉiu flanko de la rivero estis arbo de vivo, portanta dek du fruktojn, liveranta sian frukton ĉiumonate; kaj la folioj de la arbo estis por la resanigo de la nacioj."],[22,3,"Kaj ne plu ekzistos malbeno; kaj en ĝi estos la trono de Dio kaj de la Ŝafido; kaj Liaj servistoj Lin adoros;","Kaj ne plu ekzistos malbeno; kaj en ĝi estos la trono de Dio kaj de la Ŝafido; kaj Liaj servistoj Lin adoros;"],[22,4,"kaj ili vidos Lian vizaĝon; kaj Lia nomo estos sur ilia frunto.","kaj ili vidos Lian vizaĝon; kaj Lia nomo estos sur ilia frunto."],[22,5,"Kaj nokto ne plu ekzistos; kaj ili ne bezonas lumon de lampo, nek lumon de suno; ĉar Dio, la Sinjoro, lumos al ili; kaj ili reĝos por ĉiam kaj eterne.","Kaj nokto ne plu ekzistos; kaj ili ne bezonas lumon de lampo, nek lumon de suno; ĉar Dio, la Sinjoro, lumos al ili; kaj ili reĝos por ĉiam kaj eterne."],[22,6,"Kaj li diris al mi: Tiuj vortoj estas fidelaj kaj veraj; kaj la Sinjoro, la Dio de la spiritoj de la profetoj, sendis Sian anĝelon, por montri al Siaj servistoj tion, kio devas okazi baldaŭ.","Kaj li diris al mi: Tiuj vortoj estas fidelaj kaj veraj; kaj la Sinjoro, la Dio de la spiritoj de la profetoj, sendis Sian anĝelon, por montri al Siaj servistoj tion, kio devas okazi baldaŭ."],[22,7,"Kaj jen mi rapide venos. Feliĉa estas tiu, kiu observas la vortojn de la profetaĵo de ĉi tiu libro.","Kaj jen mi rapide venos. Feliĉa estas tiu, kiu observas la vortojn de la profetaĵo de ĉi tiu libro."],[22,8,"Kaj mi, Johano, estis la aŭdanto kaj la vidanto de ĉi tio. Kaj kiam mi aŭdis kaj vidis, mi falis, por adorkliniĝi antaŭ la piedoj de la anĝelo, kiu montris tion al mi.","Kaj mi, Johano, estis la aŭdanto kaj la vidanto de ĉi tio. Kaj kiam mi aŭdis kaj vidis, mi falis, por adorkliniĝi antaŭ la piedoj de la anĝelo, kiu montris tion al mi."],[22,9,"Kaj li diris al mi: Gardu vin, ke vi tion ne faru; mi estas kunservisto kun vi kaj kun viaj fratoj, la profetoj, kaj kun la observantoj de la vortoj de ĉi tiu libro; adorkliniĝu al Dio.","Kaj li diris al mi: Gardu vin, ke vi tion ne faru; mi estas kunservisto kun vi kaj kun viaj fratoj, la profetoj, kaj kun la observantoj de la vortoj de ĉi tiu libro; adorkliniĝu al Dio."],[22,10,"Kaj li diris al mi: Ne sigelu la vortojn de la profetaĵo de ĉi tiu libro; ĉar la tempo estas proksima.","Kaj li diris al mi: Ne sigelu la vortojn de la profetaĵo de ĉi tiu libro; ĉar la tempo estas proksima."],[22,11,"La maljustulo ankoraŭ estu maljusta; kaj la malpurulo ankoraŭ estu malpura; kaj la justulo ankoraŭ faru juston; kaj la sanktulo ankoraŭ sanktiĝu.","La maljustulo ankoraŭ estu maljusta; kaj la malpurulo ankoraŭ estu malpura; kaj la justulo ankoraŭ faru juston; kaj la sanktulo ankoraŭ sanktiĝu."],[22,12,"Jen mi rapide venos; kaj mia rekompenco estas kun mi, por repagi al ĉiu laŭ lia faro.","Jen mi rapide venos; kaj mia rekompenco estas kun mi, por repagi al ĉiu laŭ lia faro."],[22,13,"Mi estas la Alfa kaj la Omega, la unua kaj la lasta, la komenco kaj la fino.","Mi estas la Alfa kaj la Omega, la unua kaj la lasta, la komenco kaj la fino."],[22,14,"Feliĉaj estas tiuj, kiuj lavas siajn robojn, por ke ili havu rajton sur la arbo de vivo, kaj ke ili eniru tra la pordegoj en la urbon.","Feliĉaj estas tiuj, kiuj lavas siajn robojn, por ke ili havu rajton sur la arbo de vivo, kaj ke ili eniru tra la pordegoj en la urbon."],[22,15,"Ekstere estas la hundoj kaj la sorĉistoj kaj la malĉastuloj kaj la mortigistoj kaj la idolanoj, kaj ĉiu, kiu amas kaj faras mensogon.","Ekstere estas la hundoj kaj la sorĉistoj kaj la malĉastuloj kaj la mortigistoj kaj la idolanoj, kaj ĉiu, kiu amas kaj faras mensogon."],[22,16,"Mi, Jesuo, sendis mian anĝelon, por atesti al vi ĉi tion por la eklezioj. Mi estas la markoto kaj ido de David, la hela, la matena stelo.","Mi, Jesuo, sendis mian anĝelon, por atesti al vi ĉi tion por la eklezioj. Mi estas la markoto kaj ido de David, la hela, la matena stelo."],[22,17,"Kaj la Spirito kaj la fianĉino diras: Venu. Kaj la aŭdanto diru: Venu. Kaj la soifanto venu; kiu volas, tiu prenu donace la akvon de vivo.","Kaj la Spirito kaj la fianĉino diras: Venu. Kaj la aŭdanto diru: Venu. Kaj la soifanto venu; kiu volas, tiu prenu donace la akvon de vivo."],[22,18,"Mi atestas al ĉiu, kiu aŭdas la vortojn de la profetaĵo de ĉi tiu libro: Se iu aldonos al ili, Dio aldonos al li la plagojn, skribitajn en ĉi tiu libro;","Mi atestas al ĉiu, kiu aŭdas la vortojn de la profetaĵo de ĉi tiu libro: Se iu aldonos al ili, Dio aldonos al li la plagojn, skribitajn en ĉi tiu libro;"],[22,19,"kaj se iu forprenos el la vortoj de la libro de ĉi tiu profetaĵo, skribitaj en ĉi tiu libro, Dio forprenos lian lotaĵon el la arbo de vivo kaj el la sankta urbo.","kaj se iu forprenos el la vortoj de la libro de ĉi tiu profetaĵo, skribitaj en ĉi tiu libro, Dio forprenos lian lotaĵon el la arbo de vivo kaj el la sankta urbo."],[22,20,"La atestanto de tio diras: Vere, mi rapide venos. Amen; venu, Sinjoro Jesuo.","La atestanto de tio diras: Vere, mi rapide venos. Amen; venu, Sinjoro Jesuo."],[22,21,"La graco de la Sinjoro Jesuo estu kun ĉiuj sanktuloj. Amen.","La graco de la Sinjoro Jesuo estu kun ĉiuj sanktuloj. Amen."]]}};